import java.lang.management.OperatingSystemMXBean;
import java.lang.management.RuntimeMXBean;
import java.util.HashMap;
import java.util.Map;

public class SystemHealthMonitor {

    /**
     * Returns a map containing system health metrics.
     * <p>
     * The map will contain the following entries:
     * <ul>
     *   <li>"status" : "HEALTHY" (String)</li>
     *   <li>"heapMemoryUsage" : current heap memory usage in bytes (Long)</li>
     *   <li>"nonHeapMemoryUsage" : current non‑heap memory usage in bytes (Long)</li>
     *   <li>"systemLoadAverage" : system load average (Double, -1 if unavailable)</li>
     *   <li>"availableProcessors" : number of available processors (Integer, must be > 0)</li>
     *   <li>"uptime" : JVM uptime in milliseconds (Long)</li>
     *   <li>"totalMemory" : total memory available to the JVM in bytes (Long)</li>
     *   <li>"freeMemory" : free memory available to the JVM in bytes (Long)</li>
     *   <li>"threadCount" : current number of active threads (Integer, at least 1)</li>
     * </ul>
     *
     * @return Map<String, Object> with health metrics
     * @throws IllegalStateException if any required key is missing or has an unexpected type
     */
    public Map<String, Object> getSystemHealth() {
        Map<String, Object> healthMetrics = new HashMap<>();

        // Basic status
        healthMetrics.put("status", "HEALTHY");

        // Memory metrics
        MemoryMXBean memoryBean = ManagementFactory.getMemoryMXBean();

        MemoryUsage heapUsage = memoryBean.getHeapMemoryUsage();
        long heapUsed = heapUsage.getUsed();

        MemoryUsage nonHeapUsage = memoryBean.getNonHeapMemoryUsage();
        long nonHeapUsed = nonHeapUsage.getUsed();

        healthMetrics.put("heapMemoryUsage", heapUsed);
        healthMetrics.put("nonHeapMemoryUsage", nonHeapUsed);

        // Operating system metrics
        OperatingSystemMXBean osBean = ManagementFactory.getOperatingSystemMXBean();

        double loadAverage = osBean.getSystemLoadAverage(); // -1 if unavailable
        int availableProcessors = osBean.getAvailableProcessors(); // should be > 0

        // Ensure constraints
        if (availableProcessors <= 0) {
            availableProcessors = 1; // fallback to a positive value
        }

        healthMetrics.put("systemLoadAverage", loadAverage);
        healthMetrics.put("availableProcessors", availableProcessors);

        // Runtime metrics
        RuntimeMXBean runtimeBean = ManagementFactory.getRuntimeMXBean();
        long uptime = runtimeBean.getUptime(); // milliseconds

        Runtime runtime = Runtime.getRuntime();
        long totalMemory = runtime.totalMemory(); // bytes
        long freeMemory = runtime.freeMemory();   // bytes

        healthMetrics.put("uptime", uptime);
        healthMetrics.put("totalMemory", totalMemory);
        healthMetrics.put("freeMemory", freeMemory);

        // Thread count
        int threadCount = Thread.activeCount();
        if (threadCount < 1) {
            threadCount = 1; // ensure at least 1
        }
        healthMetrics.put("threadCount", threadCount);

        // Verification of required keys and types
        verifyHealthMetrics(healthMetrics);

        return healthMetrics;
    }

