import java.util.HashMap;
import java.util.Map;

class UrlRouter {
    private Map<String, String> routeMap;
    private String defaultRoute;

    public UrlRouter(Map<String, String> routes, String defaultRoute) {
        this.routeMap = new HashMap<>(routes);
        this.defaultRoute = defaultRoute;
    }

    public String resolveRoute(String path) {
        // 1. Check for an exact static match first
        if (routeMap.containsKey(path)) {
            return routeMap.get(path);
        }

        // 2. Check for a dynamic (parameterized) match
        for (Map.Entry<String, String> entry : routeMap.entrySet()) {
            String route = entry.getKey();
            if (isParameterizedRoute(route) && matchPath(route, path)) {
                return entry.getValue();
            }
        }

        // 3. No match found – return the default route
        return defaultRoute;
    }

    // Determines whether a route contains a parameter placeholder like {id}
    private boolean isParameterizedRoute(String route) {
        return route.matches(".*\\{[^}]+\\}.*");
    }

    // Checks if the given path matches the parameterized route pattern
    private boolean matchPath(String route, String path) {
        String[] routeParts = route.split("/");
        String[] pathParts = path.split("/");

        if (routeParts.length != pathParts.length) {
            return false;
        }

        for (int i = 0; i < routeParts.length; i++) {
            String r = routeParts[i];
            String p = pathParts[i];

            if (r.startsWith("{") && r.endsWith("}")) {
                // Placeholder matches any non‑empty segment
                if (p.isEmpty()) {
                    return false;
                }
            } else {
                if (!r.equals(p)) {
                    return false;
                }
            }
        }
        return true;
    }
}

