import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

/**
 * Manages daemon threads, automatically cleaning up dead ones and providing
 * a graceful shutdown mechanism.
 */
public class ThreadResourceManager {

    /** Stores active threads keyed by their unique names. */
    private final Map<String, Thread> threadMap = new ConcurrentHashMap<>();

    /** Scheduler that periodically removes dead threads from the map. */
    private final ScheduledExecutorService scheduler;

    /**
     * Creates the manager and starts a background task that removes any
     * threads from the internal map that are no longer alive.
     */
    public ThreadResourceManager() {
        scheduler = Executors.newSingleThreadScheduledExecutor();
        scheduler.scheduleAtFixedRate(
                () -> threadMap.entrySet().removeIf(entry -> !entry.getValue().isAlive()),
                1, 1, TimeUnit.SECONDS);
    }

    /**
     * Creates a daemon thread with the specified name and task.
     *
     * @param threadName the unique name of the thread to create
     * @param task       the Runnable task to run in the thread
     * @return {@code true} if the thread was created and started successfully;
     *         {@code false} if {@code threadName} or {@code task} is {@code null}
     *         or a thread with the same name already exists
     */
    public boolean createDaemonThread(String threadName, Runnable task) {
        if (threadName == null || task == null) {
            return false;
        }
        // Ensure thread names are unique
        if (threadMap.containsKey(threadName)) {
            return false;
        }
        Thread thread = new Thread(task, threadName);
        thread.setDaemon(true);
        thread.start();
        threadMap.put(threadName, thread);
        return true;
    }

    /**
     * Stops (interrupts) and removes the daemon thread with the given name.
     *
     * @param threadName the name of the thread to stop
     * @return {@code true} if the thread was found and stopped; {@code false}
     *         otherwise
     */
    public boolean stopDaemonThread(String threadName) {
        if (threadName == null) {
            return false;
        }
        Thread thread = threadMap.remove(threadName);
        if (thread == null) {
            return false; // No such thread
        }
        thread.interrupt();
        return true;
    }

    /**
     * Returns the current number of active daemon threads managed by this instance.
     *
     * @return the size of the internal thread map
     */
    public int getActiveThreadCount() {
        return threadMap.size();
    }

    /**
     * Gracefully shuts down the manager:
     * <ul>
     *   <li>Interrupts all active threads.</li>
     *   <li>Clears the thread map.</li>
     *   <li>Stops the monitoring executor service.</li>
     * </ul>
     * This method is thread‑safe and can be called multiple times without adverse effects.
     */
    public void shutdown() {
        // Interrupt all active threads
        for (Thread thread : threadMap.values()) {
            thread.interrupt();
        }
        // Clear the map
        threadMap.clear();
        // Shut down the monitoring scheduler
        scheduler.shutdownNow();
    }
}

