import org.json.JSONObject;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.HashMap;

/**
 * Represents a single member in a lobby.
 */
class LobbyMember {
    private final String id;
    private final String name;
    private final int colorIndex;
    private final boolean isReady;

    public LobbyMember(String id, String name, int colorIndex, boolean isReady) {
        this.id = id;
        this.name = name;
        this.colorIndex = colorIndex;
        this.isReady = isReady;
    }

    public String getId() { return id; }
    public String getName() { return name; }
    public int getColorIndex() { return colorIndex; }
    public boolean isReady() { return isReady; }
}

/**
 * Manages a lobby, its members and settings.
 */
class EnhancedLobbyManager {
    private final String lobbyId;
    private final String ownerId;
    private final List<LobbyMember> members;
    private final Map<String, String> settings;

    /**
     * Creates a new lobby manager.
     *
     * @param lobbyJson JSON object containing lobby data. It may contain an optional
     *                  "settings" object with key/value pairs.
     * @param lobbyId   The unique identifier for the lobby.
     */
    public EnhancedLobbyManager(JSONObject lobbyJson, String lobbyId) {
        this.lobbyId = lobbyId;
        this.ownerId = lobbyJson.getString("ownerId");
        this.members = new ArrayList<>();
        this.settings = new HashMap<>();

        // Parse initial settings if present
        if (lobbyJson.has("settings")) {
            JSONObject settingsObj = lobbyJson.getJSONObject("settings");
            for (String key : settingsObj.keySet()) {
                settings.put(key, settingsObj.getString(key));
            }
        }
    }

    /**
     * Adds a new member to the lobby.
     *
     * @param memberJson JSON object containing member data. Expected keys:
     *                   "id", "name", "colorIndex", "isReady".
     * @return true if the member was added, false if a member with the same id already exists.
     */
    public boolean addMember(JSONObject memberJson) {
        String memberId = memberJson.getString("id");

        // Check for duplicate
        for (LobbyMember m : members) {
            if (m.getId().equals(memberId)) {
                return false;
            }
        }

        String name = memberJson.optString("name", "");
        int colorIndex = memberJson.optInt("colorIndex", 0);
        boolean isReady = memberJson.optBoolean("isReady", false);

        members.add(new LobbyMember(memberId, name, colorIndex, isReady));
        return true;
    }

    /**
     * Updates the lobby settings with the values from the provided JSON object.
     * Existing settings are replaced by the new values; keys not present in the
     * JSON remain unchanged.
     *
     * @param settingsJson JSON object containing key/value pairs for settings.
     */
    public void updateSettings(JSONObject settingsJson) {
        for (String key : settingsJson.keySet()) {
            settings.put(key, settingsJson.getString(key));
        }
    }

    // Getters
    public String getLobbyId() { return lobbyId; }
    public String getOwnerId() { return ownerId; }
    public List<LobbyMember> getMembers() { return new ArrayList<>(members); }
    public Map<String, String> getSettings() { return new HashMap<>(settings); }
}

