import java.util.Map;

class EnhancedActivityManager {
    private Map<String, String> activityParams;
    private Locale currentLocale;
    private String lastErrorMessage;

    public EnhancedActivityManager() {
        this.activityParams = new HashMap<>();
        this.currentLocale = Locale.getDefault();
        this.lastErrorMessage = null;
    }

    /**
     * Navigates to the specified activity with the given parameters.
     *
     * @param targetActivity the name of the target activity
     * @param params         parameters to be passed to the activity
     * @return true if navigation is successful; false otherwise
     */
    public boolean navigateTo(String targetActivity, Map<String, String> params) {
        if (targetActivity == null || targetActivity.trim().isEmpty()) {
            this.lastErrorMessage = "Target activity cannot be null or empty";
            return false;
        }

        // Store parameters if provided
        if (params != null) {
            this.activityParams.putAll(params);
        }

        // Clear any previous error message on success
        this.lastErrorMessage = null;
        return true;
    }

    // Getters and setters
    public Map<String, String> getActivityParams() {
        return activityParams;
    }

    public void setActivityParams(Map<String, String> activityParams) {
        this.activityParams = activityParams;
    }

    public Locale getCurrentLocale() {
        return currentLocale;
    }

    public void setCurrentLocale(Locale currentLocale) {
        this.currentLocale = currentLocale;
    }

    public String getLastErrorMessage() {
        return lastErrorMessage;
    }

    public void setLastErrorMessage(String lastErrorMessage) {
        this.lastErrorMessage = lastErrorMessage;
    }
}

