public class StringProcessor {

    public static Map<String, Object> processString(String input) {
        if (input == null) {
            throw new IllegalArgumentException("Input string cannot be null");
        }

        Map<String, Object> result = new HashMap<>();

        // Trim to handle empty or whitespace‑only strings
        String trimmed = input.trim();

        // Basic transformations
        String noSpaces = input.replaceAll("\\s+", "");
        String lowercase = input.toLowerCase();
        String uppercase = input.toUpperCase();
        String noPunctuation = input.replaceAll("[^a-zA-Z0-9]", "");

        // If the trimmed string is empty, set transformations to empty strings
        if (trimmed.isEmpty()) {
            noSpaces = "";
            lowercase = "";
            uppercase = "";
            noPunctuation = "";
        }

        // Counters
        int vowelCount = 0;
        int consonantCount = 0;
        int digitCount = 0;

        for (char c : input.toCharArray()) {
            if (Character.isDigit(c)) {
                digitCount++;
            } else if (Character.isLetter(c)) {
                if ("AEIOUaeiou".indexOf(c) >= 0) {
                    vowelCount++;
                } else {
                    consonantCount++;
                }
            }
        }

        // Word count: sequences separated by whitespace
        int wordCount = 0;
        if (!trimmed.isEmpty()) {
            wordCount = trimmed.split("\\s+").length;
        }

        // Populate result map
        result.put("noSpaces", noSpaces);
        result.put("lowercase", lowercase);
        result.put("uppercase", uppercase);
        result.put("noPunctuation", noPunctuation);
        result.put("vowelCount", vowelCount);
        result.put("consonantCount", consonantCount);
        result.put("digitCount", digitCount);
        result.put("wordCount", wordCount);

        return result;
    }
}
