     * @param clickY the Y coordinate of the click
     * @return true if the score was increased, false otherwise
     */
    public boolean handleMouseClick(int clickX, int clickY) {
        if (!gameState.getOrDefault("gameStarted", false)) {
            return false;
        }
        int[] pos = player.getPosition();
        int dx = clickX - pos[0];
        int dy = clickY - pos[1];
        double distance = Math.sqrt(dx * dx + dy * dy);
        if (distance <= 50.0) {
            score += 10;
            return true;
        }
        return false;
    }

    /** Pauses the game if it is currently running and not over. */
