import java.util.HashMap;
import java.util.Map;

class GameEngine {
    private final Player player;
    private final Map<String, Boolean> gameState;
    private int score;

    public GameEngine() {
        this.player = new Player();
        this.gameState = new HashMap<>();
        this.score = 0;
        initializeGameState();
    }

    /** Initializes all game state flags to false. */
    private void initializeGameState() {
        gameState.put("gameStarted", false);
        gameState.put("gamePaused", false);
        gameState.put("gameOver", false);
    }

    /**
     * Starts a new game by setting the player's position and updating the game state.
     *
     * @param startX the starting X coordinate
     * @param startY the starting Y coordinate
     */
    public void startNewGame(int startX, int startY) {
        player.setPosition(startX, startY);
        gameState.put("gameStarted", true);
        gameState.put("gamePaused", false);
        gameState.put("gameOver", false);
    }

    /**
     * Moves the player in the specified direction by 1 unit, but only if the game
     * has started and is not paused.
     *
     * @param direction the direction to move (UP, DOWN, LEFT, RIGHT)
     * @return the new position of the player as an int array [x, y]
     */
    public int[] handlePlayerMovement(Direction direction) {
        if (!gameState.getOrDefault("gameStarted", false) ||
            gameState.getOrDefault("gamePaused", false)) {
            return player.getPosition(); // No movement when not allowed
        }

        int dx = 0, dy = 0;
        switch (direction) {
            case UP:
                dy = -1;
                break;
            case DOWN:
                dy = 1;
                break;
            case LEFT:
                dx = -1;
                break;
            case RIGHT:
                dx = 1;
                break;
        }
        player.move(dx, dy);
        return player.getPosition();
    }

    /**
     * Handles a mouse click event. If the click is within 50 units of the player's
     * current position and the game has started, the score is increased by 10.
     *
     * @param clickX the X coordinate of the click
     * @param clickY the Y coordinate of the click
     * @return true if the score was increased, false otherwise
     */
    public boolean handleMouseClick(int clickX, int clickY) {
        if (!gameState.getOrDefault("gameStarted", false)) {
            return false;
        }
        int[] pos = player.getPosition();
        int dx = clickX - pos[0];
        int dy = clickY - pos[1];
        double distance = Math.sqrt(dx * dx + dy * dy);
        if (distance <= 50.0) {
            score += 10;
            return true;
        }
        return false;
    }

    /** Pauses the game if it is currently running and not over. */
    public void pauseGame() {
        if (gameState.get("gameStarted") && !gameState.get("gameOver")) {
            gameState.put("gamePaused", true);
        }
    }

    /** Resumes the game if it was paused. */
    public void resumeGame() {
        if (gameState.get("gamePaused")) {
            gameState.put("gamePaused", false);
        }
    }

    /** Ends the game, resetting relevant flags. */
    public void endGame() {
        gameState.put("gameOver", true);
        gameState.put("gameStarted", false);
        gameState.put("gamePaused", false);
    }

    /**
     * Returns a copy of the current game state map to prevent external modification.
     *
     * @return a new Map containing the same key/value pairs as the internal gameState
