public class Venue {
    private final int rows;
    private final int columns;
    private final boolean[][] seats; // true = reserved, false = available

    /**
     * Creates a venue with the specified number of rows and columns.
     * All seats are initially available.
     *
     * @param rows    number of rows (must be > 0)
     * @param columns number of columns (must be > 0)
     * @throws IllegalArgumentException if rows or columns are not positive
     */
    public Venue(int rows, int columns) {
        if (rows <= 0 || columns <= 0) {
            throw new IllegalArgumentException("Rows and columns must be positive");
        }
        this.rows = rows;
        this.columns = columns;
        this.seats = new boolean[rows][columns];
    }

    /**
     * Returns the total number of seats in the venue.
     *
     * @return total seats (rows × columns)
     */
    public int getNumberOfSeats() {
        return rows * columns;
    }

    /**
     * Attempts to reserve a seat at the specified row and column.
     *
     * @param row    zero‑based row index
     * @param column zero‑based column index
     * @return true if the seat was successfully reserved, false if it was already reserved
     * @throws IndexOutOfBoundsException if the seat coordinates are invalid
     */
    public boolean reserveSeat(int row, int column) {
        validateSeat(row, column);
        if (seats[row][column]) {
            return false; // already reserved
        }
        seats[row][column] = true;
        return true;
    }

    /**
     * Checks whether a seat is available.
     *
     * @param row    zero‑based row index
     * @param column zero‑based column index
     * @return true if the seat is available, false if it is reserved
     * @throws IndexOutOfBoundsException if the seat coordinates are invalid
     */
    public boolean isSeatAvailable(int row, int column) {
        validateSeat(row, column);
        return !seats[row][column];
    }

    /**
     * Cancels a reservation for the specified seat.
     *
     * @param row    zero‑based row index
     * @param column zero‑based column index
     * @return true if the reservation was successfully cancelled, false if the seat was not reserved
     * @throws IndexOutOfBoundsException if the seat coordinates are invalid
     */
    public boolean cancelReservation(int row, int column) {
        validateSeat(row, column);
        if (!seats[row][column]) {
            return false; // not reserved
        }
        seats[row][column] = false;
        return true;
    }

    /**
     * Returns the number of seats that are currently available.
     *
     * @return count of available seats
     */
    public int getAvailableSeatsCount() {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                if (!seats[i][j]) {
                    count++;
                }
            }
        }
        return count;
    }

    // Helper method to validate seat coordinates
    private void validateSeat(int row, int column) {
        if (row < 0 || row >= rows || column < 0 || column >= columns) {
            throw new IndexOutOfBoundsException(
                "Seat position out of bounds: row=" + row + ", column=" + column);
        }
    }

    // Example usage
    public static void main(String[] args) {
        Venue venue = new Venue(10, 15);
        System.out.println("Total seats: " + venue.getNumberOfSeats());
        System.out.println("Available seats: " + venue.getAvailableSeatsCount());

        // Reserve a seat
        if (venue.reserveSeat(2, 5)) {
            System.out.println("Seat (2,5) reserved.");
        }

        // Check availability
        System.out.println("Seat (2,5) available? " + venue.isSeatAvailable(2, 5));

        // Cancel reservation
        if (venue.cancelReservation(2, 5)) {
            System.out.println("Seat (2,5) reservation cancelled.");
        }

        System.out.println("Available seats after cancellation: " + venue.getAvailableSeatsCount());
    }
}

