import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Represents a message with an identifier and content.
 */
class Message {
    private final String id;
    private final String content;

    public Message(String id, String content) {
        this.id = id;
        this.content = content;
    }

    public String getId() {
        return id;
    }

    public String getContent() {
        return content;
    }
}

/**
 * Enumeration of possible processing statuses.
 */
enum Status {
    SUCCESS,
    FAILURE
}

/**
 * Result of processing a message.
 * Includes status, message id, and optional metadata.
 */
class ProcessingResult {
    private final Status status;
    private final String messageId;
    private final Map<String, Object> metadata;

    public ProcessingResult(Status status, String messageId, Map<String, Object> metadata) {
        this.status = status;
        this.messageId = messageId;
        this.metadata = metadata != null ? new HashMap<>(metadata) : new HashMap<>();
    }

    public Status getStatus() {
        return status;
    }

    public String getMessageId() {
        return messageId;
    }

    public Map<String, Object> getMetadata() {
        return new HashMap<>(metadata);
    }
}

/**
 * Processor that stores messages, tracks counts per destination,
 * and returns a processing result with metadata.
 * All public methods are thread‑safe via the synchronized keyword.
 */
public class EnhancedMessageProcessor {
    private final List<Message> storedMessages = new ArrayList<>();
    private final Map<String, Integer> destinationCounts = new HashMap<>();

    /**
     * Stores the given message, updates destination counts,
     * and returns a success result with totalMessages metadata.
     *
     * @param message     the message to store
     * @param destination the destination string
     * @return a ProcessingResult indicating success
     */
    public synchronized ProcessingResult postMessage(Message message, String destination) {
        // Store the message
        storedMessages.add(message);

        // Update destination count
        destinationCounts.merge(destination, 1, Integer::sum);

        // Prepare metadata
        Map<String, Object> metadata = new HashMap<>();
        metadata.put("totalMessages", storedMessages.size());

        return new ProcessingResult(Status.SUCCESS, message.getId(), metadata);
    }

    /**
     * Returns a copy of the stored messages.
     *
     * @return a list of stored messages
     */
    public synchronized List<Message> getStoredMessages() {
        return new ArrayList<>(storedMessages);
    }

    /**
     * Returns a copy of the destination counts map.
     *
     * @return a map of destination to message count
     */
    public synchronized Map<String, Integer> getDestinationCounts() {
        return new HashMap<>(destinationCounts);
    }
}

