 */
public class EnhancedMessageProcessor {
    private final List<Message> storedMessages = new ArrayList<>();
    private final Map<String, Integer> destinationCounts = new HashMap<>();
    private final Map<String, Message> latestMessagePerDestination = new HashMap<>();
    private final Map<String, List<Message>> destinationToMessages = new HashMap<>();

    /**
     * Stores the given message, updates destination counts,
     * and returns a success result with totalMessages metadata.
     *
     * @param message     the message to store
     * @param destination the destination string
     * @return a ProcessingResult indicating success
     */
    public synchronized ProcessingResult postMessage(Message message, String destination) {
        // Create a new message instance that records the destination
        Message stored = new Message(
                message.getId(),
                message.getContent(),
                destination,
                message.getType()
        );

        // Store the message
        storedMessages.add(stored);

        // Update destination count
        destinationCounts.merge(destination, 1, Integer::sum);

        // Update latest message for the destination
        latestMessagePerDestination.put(destination, stored);

        // Update destination to messages map
        destinationToMessages
                .computeIfAbsent(destination, k -> new ArrayList<>())
                .add(stored);

        // Prepare metadata
        Map<String, Object> metadata = new HashMap<>();
        metadata.put("totalMessages", storedMessages.size());

        return new ProcessingResult(Status.SUCCESS, stored.getId(), metadata);
    }

    /**
     * Retrieves the latest message for the specified destination.
     *
     * @param destination the destination string
     * @return the latest Message for that destination, or null if none exists
     */
    public synchronized Message getMessage(String destination) {
        return latestMessagePerDestination.getOrDefault(destination, null);
    }

    /**
     * Returns all messages that match the given content type.
     * The returned map preserves the insertion order of the messages.
     *
     * @param type the content type to filter by
     * @return a LinkedHashMap of message id to Message
     */
    public synchronized Map<String, Message> getMessagesByType(String type) {
        Map<String, Message> result = new LinkedHashMap<>();
        for (Message msg : storedMessages) {
            if (type != null && type.equals(msg.getType())) {
                result.put(msg.getId(), msg);
            }
        }
        return result;
    }

    /**
     * Removes all messages for the specified destination.
     *
     * @param destination the destination string
     * @return Status.SUCCESS if any messages were removed, otherwise Status.FAILURE
     */
    public synchronized Status clearMessages(String destination) {
        List<Message> toRemove = destinationToMessages.remove(destination);
        if (toRemove == null || toRemove.isEmpty()) {
            return Status.FAILURE;
        }

        // Remove from storedMessages
        storedMessages.removeIf(msg -> destination.equals(msg.getDestination()));

        // Update destination counts
        destinationCounts.remove(destination);

        // Update latest message map
        latestMessagePerDestination.remove(destination);

        return Status.SUCCESS;
    }

    /**
     * Returns a copy of the stored messages.
     *
     * @return a list of stored messages
     */
    public synchronized List<Message> getStoredMessages() {
        return new ArrayList<>(storedMessages);
    }

    /**
     * Returns a copy of the destination counts map.
     *
     * @return a map of destination to message count
     */
    public synchronized Map<String, Integer> getDestinationCounts() {
        return new HashMap<>(destinationCounts);
