import java.util.List;
import java.util.ArrayList;
import java.util.function.IntUnaryOperator;

public class FunctionDemonstrator {

    public List<String> demonstrateFunctionConcepts(int baseValue) {
        List<String> result = new ArrayList<>();

        // 1. Primitive function (square)
        int squared = baseValue * baseValue;
        result.add("Primitive function (square) result: " + squared);

        // 2. Variable assignment (double)
        int doubled = baseValue * 2;
        result.add("Variable assignment result: " + doubled);

        // 3. Parameter passing using method reference
        IntUnaryOperator addFiveOp = this::addFive;
        int paramResult = addFiveOp.applyAsInt(baseValue);
        result.add("Parameter passing result: " + paramResult);

        // 4. Higher‑order function (square then add five)
        IntUnaryOperator squareOp = x -> x * x;
        IntUnaryOperator composed = compose(squareOp, addFiveOp);
        int higherOrderResult = composed.applyAsInt(baseValue);
        result.add("Higher-order function result: " + higherOrderResult);

        // 5. Recursive factorial
        int factorialResult = factorial(baseValue);
        result.add("Recursive factorial result: " + factorialResult);

        return result;
    }

    // Private helper method used via method reference
    private int addFive(int x) {
        return x + 5;
    }

    // Higher‑order function that composes two IntUnaryOperator instances
    private IntUnaryOperator compose(IntUnaryOperator first, IntUnaryOperator second) {
        return first.andThen(second);
    }

    // Private recursive factorial method
    private int factorial(int n) {
        if (n <= 1) {
            return 1;
        }
        return n * factorial(n - 1);
    }
}

