import java.lang.reflect.Array;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class ObjectInspector {

    /**
     * Public entry point that uses a large default depth.
     *
     * @param obj the object to inspect
     * @return a map with inspection results
     */
    public static Map<String, Object> inspectObject(Object obj) {
        return inspectObject(obj, Integer.MAX_VALUE);
    }

    /**
     * Inspects an object and returns a map containing its type and, for simple types
     * or arrays, its value. Recursively inspects array elements up to {@code maxDepth}.
     *
     * @param obj      the object to inspect
     * @param maxDepth maximum recursion depth (0 means no further inspection)
     * @return a map with inspection results
     */
    public static Map<String, Object> inspectObject(Object obj, int maxDepth) {
        Map<String, Object> result = new HashMap<>();

        if (obj == null) {
            result.put("value", null);
            return result;
        }

        Class<?> clazz = obj.getClass();

        // Handle arrays
        if (clazz.isArray()) {
            String componentTypeName = clazz.getComponentType().getSimpleName();
            result.put("type", componentTypeName + "[]");

            if (maxDepth <= 0) {
                result.put("value", null);
                return result;
            }

            int length = Array.getLength(obj);
            List<Object> inspectedElements = new ArrayList<>(length);
            for (int i = 0; i < length; i++) {
                Object element = Array.get(obj, i);
                inspectedElements.add(inspectObject(element, maxDepth - 1));
            }
            result.put("value", inspectedElements);
            return result;
        }

        // Handle simple types
        if (isSimpleType(obj)) {
            result.put("type", clazz.getSimpleName());
            result.put("value", obj);
            return result;
        }

        // For other objects, only provide the type
        result.put("type", clazz.getSimpleName());
        return result;
    }

    /**
     * Checks whether the given object is a simple type: String, Number, Boolean, or Character.
     *
     * @param obj the object to check
     * @return true if the object is a simple type, false otherwise
     */
    private static boolean isSimpleType(Object obj) {
        return obj instanceof String
                || obj instanceof Number
                || obj instanceof Boolean
                || obj instanceof Character;
    }
}

