import java.lang.reflect.Array;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class ObjectInspector {

    /**
     * Public entry point that uses a large default depth.
     *
     * @param obj the object to inspect
     * @return a map with inspection results
     */
    public static Map<String, Object> inspectObject(Object obj) {
        return inspectObject(obj, Integer.MAX_VALUE);
    }

    /**
     * Inspects an object and returns a map containing its type and, for simple types,
     * its value. For arrays and complex objects, the map contains a 'fields' entry
     * with recursively inspected values. Recursion depth is limited by {@code maxDepth}.
     *
     * @param obj      the object to inspect
     * @param maxDepth maximum recursion depth (0 means no further inspection)
     * @return a map with inspection results
     */
    public static Map<String, Object> inspectObject(Object obj, int maxDepth) {
        Map<String, Object> result = new HashMap<>();

        if (obj == null) {
            result.put("value", null);
            return result;
        }

        Class<?> clazz = obj.getClass();

        // Handle arrays
        if (clazz.isArray()) {
            String componentTypeName = clazz.getComponentType().getSimpleName();
            result.put("type", componentTypeName + "[]");

            if (maxDepth <= 0) {
                result.put("value", null);
                return result;
            }

            int length = Array.getLength(obj);
            List<Object> inspectedElements = new ArrayList<>(length);
            for (int i = 0; i < length; i++) {
                Object element = Array.get(obj, i);
                inspectedElements.add(inspectObject(element, maxDepth - 1));
            }
            result.put("value", inspectedElements);
            return result;
        }

        // Handle simple types
        if (isSimpleType(obj)) {
            result.put("type", clazz.getSimpleName());
            result.put("value", obj);
            return result;
        }

        // Handle complex objects
        result.put("type", clazz.getSimpleName());

        if (maxDepth <= 0) {
            result.put("fields", new HashMap<String, Object>());
            return result;
        }

        Map<String, Object> fieldsMap = new HashMap<>();
        for (Field field : getAllFields(clazz)) {
            if (Modifier.isStatic(field.getModifiers())) {
                continue; // skip static fields
            }
            field.setAccessible(true);
            try {
                Object fieldValue = field.get(obj);
                fieldsMap.put(field.getName(), inspectObject(fieldValue, maxDepth - 1));
            } catch (IllegalAccessException e) {
                // If we cannot access the field, store null
                fieldsMap.put(field.getName(), null);
            }
        }
        result.put("fields", fieldsMap);
        return result;
    }

    /**
     * Checks whether the given object is a simple type: String, Number, Boolean, or Character.
     *
     * @param obj the object to check
     * @return true if the object is a simple type, false otherwise
     */
    private static boolean isSimpleType(Object obj) {
        return obj instanceof String
                || obj instanceof Number
                || obj instanceof Boolean
                || obj instanceof Character;
    }

    /**
     * Retrieves all declared fields from the given class and its superclasses (excluding Object).
     *
     * @param clazz the class to inspect
     * @return a list of all fields
     */
    private static List<Field> getAllFields(Class<?> clazz) {
        List<Field> fields = new ArrayList<>();
        while (clazz != null && clazz != Object.class) {
            Field[] declared = clazz.getDeclaredFields();
            for (Field f : declared) {
                fields.add(f);
            }
            clazz = clazz.getSuperclass();
        }
        return fields;
    }
}

