import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Map;
import java.util.HashMap;

/**
 * A minimal thread‑safe P2P address server.
 * <p>
 * The server stores peer information in a {@link ConcurrentHashMap} and keeps a
 * counter of the current number of registered peers. All operations are
 * safe for concurrent use.
 */
class P2PAddressServer {
    private final ConcurrentHashMap<String, PeerInfo> peerRegistry;
    private final int maxPeers;
    private final AtomicInteger currentPeers;

    /* --------------------------------------------------------------------- */
    /* Constructors                                                            */
    /* --------------------------------------------------------------------- */

    /** Default constructor – maximum 100 peers. */
    public P2PAddressServer() {
        this(100);
    }

    /**
     * Parameterised constructor.
     *
     * @param maxPeers maximum number of peers that can be registered
     * @throws IllegalArgumentException if {@code maxPeers} is not in [1, 10000]
     */
    public P2PAddressServer(int maxPeers) {
        if (maxPeers < 1 || maxPeers > 10000) {
            throw new IllegalArgumentException("maxPeers must be between 1 and 10000");
        }
        this.maxPeers = maxPeers;
        this.peerRegistry = new ConcurrentHashMap<>();
        this.currentPeers = new AtomicInteger(0);
    }

    /* --------------------------------------------------------------------- */
    /* Peer registration                                                      */
    /* --------------------------------------------------------------------- */

    /**
     * Registers a peer with the given ID, address and port.
     *
     * @param peerId  unique identifier of the peer
     * @param address network address of the peer
     * @param port    port number of the peer
     * @return {@code true} if the peer was successfully registered,
     *         {@code false} otherwise (duplicate ID, capacity reached,
     *         or invalid input)
     */
    public boolean registerPeer(String peerId, String address, int port) {
        // Input validation
        if (peerId == null || peerId.isEmpty() || port <= 0 || port > 65535) {
            return false;
        }

        // Reserve a spot if capacity allows
        while (true) {
            int current = currentPeers.get();
            if (current >= maxPeers) {
                return false; // capacity reached
            }
            if (!currentPeers.compareAndSet(current, current + 1)) {
                continue; // retry due to race
            }

            // Reserved spot, now try to insert
            PeerInfo info = new PeerInfo(address, port, System.currentTimeMillis());
            PeerInfo existing = peerRegistry.putIfAbsent(peerId, info);
            if (existing == null) {
                return true; // successfully registered
            } else {
                // Duplicate ID, release reserved spot
                currentPeers.decrementAndGet();
                return false;
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /* Peer unregistration                                                    */
    /* --------------------------------------------------------------------- */

    /**
     * Unregisters a peer by its ID.
     *
     * @param peerId the ID of the peer to remove
     * @return {@code true} if the peer existed and was removed,
     *         {@code false} otherwise
     */
    public boolean unregisterPeer(String peerId) {
        if (peerId == null || peerId.isEmpty()) {
            return false;
        }
        PeerInfo removed = peerRegistry.remove(peerId);
        if (removed == null) {
            return false; // peer did not exist
        }
        currentPeers.decrementAndGet();
        return true;
    }

    /* --------------------------------------------------------------------- */
    /* Peer lookup                                                            */
    /* --------------------------------------------------------------------- */

    /**
     * Retrieves the {@link PeerInfo} for the specified peer ID.
     *
     * @param peerId the ID of the peer
