     * @param limit  the maximum number of items to return (must be positive)
     * @param offset the starting index (must be non‑negative)
     * @param <T>    the type of elements in the list
     * @return a new {@link List} containing the requested slice; if {@code offset} is beyond the end of the list,
     * an empty list is returned
     * @throws IllegalArgumentException if {@code items} is {@code null},
     *                                  if {@code limit} is less than or equal to zero,
     *                                  or if {@code offset} is negative
     */
    public static <T> List<T> paginate(List<T> items, int limit, int offset) {
        if (items == null) {
            throw new IllegalArgumentException("items list cannot be null");
        }
        if (limit <= 0) {
            throw new IllegalArgumentException("Limit must be positive");
        }
        if (offset < 0) {
            throw new IllegalArgumentException("Offset cannot be negative");
        }

        int size = items.size();

        if (offset >= size) {
            return new ArrayList<>(); // empty list
        }

        int end = Math.min(offset + limit, size);
        return new ArrayList<>(items.subList(offset, end));
    }

    /**
     * Calculates the total number of pages required to display {@code totalItems} items
     * when each page can contain at most {@code itemsPerPage} items.
     *
     * @param totalItems   the total number of items (must be non‑negative)
     * @param itemsPerPage the maximum number of items per page (must be positive)
     * @return the number of pages needed; returns 0 if {@code totalItems} is 0
     * @throws IllegalArgumentException if {@code itemsPerPage} is less than or equal to zero
     */
    public static int calculateTotalPages(int totalItems, int itemsPerPage) {
        if (itemsPerPage <= 0) {
            throw new IllegalArgumentException("itemsPerPage must be positive");
        }
        if (totalItems == 0) {
            return 0;
        }
        // Ceiling division: (totalItems + itemsPerPage - 1) / itemsPerPage
        return (totalItems + itemsPerPage - 1) / itemsPerPage;
    }
}

