import java.util.HashMap;
import java.util.Map;

public class UriValidator {

    /**
     * Parses a content URI string and returns a map containing
     * validation status, authority, path, and type information.
     *
     * @param uriString the URI string to process
     * @return a map with keys: "isValid", "authority", "path", "type"
     */
    public static Map<String, Object> processContentUri(String uriString) {
        Map<String, Object> result = new HashMap<>();

        if (uriString == null) {
            result.put("isValid", false);
            result.put("authority", "");
            result.put("path", "");
            result.put("type", "UNKNOWN");
            return result;
        }

        // Assume all URIs are valid for now
        result.put("isValid", true);

        String authority = "";
        String path = "";

        // Find the start of the authority part
        int schemeEnd = uriString.indexOf("://");
        int start = 0;
        if (schemeEnd != -1) {
            start = schemeEnd + 3; // skip "://"
        }

        // Find the first '/' after the authority to separate path
        int slashIndex = uriString.indexOf('/', start);
        if (slashIndex != -1) {
            authority = uriString.substring(start, slashIndex);
            path = uriString.substring(slashIndex); // include the leading '/'
        } else {
            authority = uriString.substring(start);
            path = "";
        }

        result.put("authority", authority);
        result.put("path", path);
        result.put("type", "UNKNOWN");

        return result;
    }
}

