     */
    public static Map<String, Object> processContentUri(String uriString) throws URISyntaxException {
        if (uriString == null) {
            throw new URISyntaxException("null", "URI string is null");
        }

        // Parse the URI
        URI uri = new URI(uriString);

        // Ensure the scheme is exactly 'content'
        String scheme = uri.getScheme();
        if (scheme == null || !scheme.equalsIgnoreCase("content")) {
            throw new IllegalArgumentException("URI scheme must be 'content'");
        }

        // Validate authority
        String authority = uri.getAuthority();
        if (authority == null || !authority.equals("com.project.notepad.provider")) {
