     *
     * @param path the path component of the URI (without leading slash)
     * @return a string representing the URI type: "NOTE", "COURSE", or "JOINED"
     * @throws IllegalArgumentException if the path is not one of the supported values
     */
    private static String determineUriType(String path) {
        if ("notes".equalsIgnoreCase(path)) {
            return "NOTE";
        } else if ("courses".equalsIgnoreCase(path)) {
            return "COURSE";
        } else if ("notes_courses_joined".equalsIgnoreCase(path)) {
            return "JOINED";
        } else {
            throw new IllegalArgumentException("Unsupported path: " + path);
