import java.util.ArrayList;
import java.util.Collections;

class CargoOptimizer {

    /**
     * Calculates the maximum number of trips a cargo vehicle can make.
     * <p>
     * A trip can be made in two ways:
     * <ul>
     *   <li>Single item trip: the item's weight is less than or equal to the vehicle capacity.</li>
     *   <li>Group trip: the heaviest item in the group multiplied by the group size is greater than
     *   or equal to the vehicle capacity.</li>
     * </ul>
     * After processing all single‑item trips, the remaining items are used to form groups.
     *
     * @param weights  List of item weights. May be null or empty.
     * @param capacity Vehicle capacity (maximum weight it can carry). Must be positive.
     * @return The maximum number of trips that can be made.
     */
    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        if (weights == null || weights.isEmpty() || capacity <= 0) {
            return 0;
        }

        int trips = 0;
        ArrayList<Integer> remaining = new ArrayList<>();

        // Separate items that can travel alone
        for (int w : weights) {
            if (w <= capacity) {
                trips++;          // single‑item trip
            } else {
                remaining.add(w); // candidate for grouping
            }
        }

        if (remaining.isEmpty()) {
            return trips;
        }

        // Sort remaining items to apply greedy grouping
        Collections.sort(remaining);

        int start = 0;
        int end = remaining.size() - 1;

        while (start <= end) {
            int maxWeight = remaining.get(end);
            // Minimum group size needed to satisfy maxWeight * size >= capacity
            int requiredSize = (int) Math.ceil((double) capacity / maxWeight);

            // Check if we have enough items to form such a group
            if (start + requiredSize - 1 <= end) {
                // Form a group: use the heaviest item and the smallest requiredSize-1 items
                trips++;
                start += requiredSize - 1; // consume smallest items
                end--;                     // consume the heaviest item
            } else {
                // Not enough items left to form a valid group
                break;
            }
        }

        return trips;
    }
}

