public class PathAnalyzer {

    /**
     * Analyzes the given file path and returns a map containing the filename,
     * its extension, the normalized parent directory path, and the depth of
     * the path (number of directory levels, excluding the filename).
     *
     * @param filePath the file path to analyze
     * @return a map with four entries:
     *         - "filename"  -> the filename component
     *         - "extension" -> the file extension (empty string if none)
     *         - "parentDir" -> the normalized parent directory path (empty string if none)
     *         - "depth"     -> the number of directory levels (excluding the filename)
     * @throws IllegalArgumentException if filePath is null or empty
     */
    public static Map<String, Object> analyzePath(String filePath) {
        if (filePath == null || filePath.isEmpty()) {
            throw new IllegalArgumentException("Input filePath cannot be null or empty");
        }

        Path path = Paths.get(filePath);
        Path normalized = path.normalize();

        // Filename
        String filename = normalized.getFileName() != null ? normalized.getFileName().toString() : "";

        // Extension
        String extension = "";
        int lastDot = filename.lastIndexOf('.');
        if (lastDot > 0 && lastDot < filename.length() - 1) {
            extension = filename.substring(lastDot + 1);
        }

        // Parent directory (normalized)
        String parentDir = "";
        Path parent = normalized.getParent();
        if (parent != null) {
            parentDir = parent.toString();
        }

        // Depth (number of directory levels, excluding the filename)
        int depth = Math.max(0, normalized.getNameCount() - 1);

        Map<String, Object> result = new HashMap<>();
        result.put("filename", filename);
        result.put("extension", extension);
        result.put("parentDir", parentDir);
        result.put("depth", depth);
        return result;
    }
}

