import java.util.*;

public class UserInfoManager {

    // Nested class representing a phone contact
    public static class PhoneContact {
        private final String name;
        private final String phoneNumber;

        public PhoneContact(String name, String phoneNumber) {
            this.name = name;
            this.phoneNumber = phoneNumber;
        }

        public String getName() {
            return name;
        }

        public String getPhoneNumber() {
            return phoneNumber;
        }
    }

    // Nested class representing processed user info
    public static class UserInfo {
        private final String name;
        private final String phoneNumber;

        public UserInfo(String name, String phoneNumber) {
            this.name = name;
            this.phoneNumber = phoneNumber;
        }

        public String getName() {
            return name;
        }

        public String getPhoneNumber() {
            return phoneNumber;
        }

        @Override
        public String toString() {
            return "UserInfo{name='" + name + "', phoneNumber='" + phoneNumber + "'}";
        }
    }

    /**
     * Processes a list of PhoneContact objects in batches of 200 and returns a map
     * containing the list of successfully processed UserInfo objects under the key
     * "success" and the total number of batches processed under the key
     * "batchesProcessed".
     *
     * @param contacts List of PhoneContact objects to process.
     * @return Map with keys "success" (List<UserInfo>) and "batchesProcessed" (Integer).
     */
    public Map<String, Object> processContacts(List<PhoneContact> contacts) {
        List<UserInfo> successList = new ArrayList<>();
        int batchesProcessed = 0;
        final int BATCH_SIZE = 200;

        for (int start = 0; start < contacts.size(); start += BATCH_SIZE) {
            int end = Math.min(start + BATCH_SIZE, contacts.size());
            List<PhoneContact> batch = contacts.subList(start, end);

            for (PhoneContact contact : batch) {
                if (isValidPhoneNumber(contact.getPhoneNumber())) {
                    UserInfo userInfo = new UserInfo(contact.getName(), contact.getPhoneNumber());
                    successList.add(userInfo);
                }
                // Invalid contacts are ignored; could be logged or collected separately if needed.
            }

            batchesProcessed++;
        }

        Map<String, Object> result = new HashMap<>();
        result.put("success", successList);
        result.put("batchesProcessed", batchesProcessed);
        return result;
    }

    // Simple phone number validation: non-empty, digits only, length 10-15
    private boolean isValidPhoneNumber(String phoneNumber) {
        if (phoneNumber == null) return false;
        String trimmed = phoneNumber.trim();
        if (trimmed.isEmpty()) return false;
        if (trimmed.length() < 10 || trimmed.length() > 15) return false;
        return trimmed.matches("\\d+");
    }
}

