import java.util.ArrayList;
import java.util.List;

/**
 * Minimal implementation of AirplaneManager, Airplane, and TravelClass.
 * Allows adding airplanes to a fleet without any validation.
 */
public class AirplaneManager {

    private final List<Airplane> fleet = new ArrayList<>();

    /**
     * Adds an airplane to the fleet.
     *
     * @param airplane the airplane to add
     */
    public void addAirplane(Airplane airplane) {
        fleet.add(airplane);
    }

    /**
     * Returns the current fleet of airplanes.
     *
     * @return list of airplanes
     */
    public List<Airplane> getFleet() {
        return new ArrayList<>(fleet);
    }

    // Example usage
    public static void main(String[] args) {
        AirplaneManager manager = new AirplaneManager();

        TravelClass tc1 = new TravelClass(150, 30, 10);
        Airplane a1 = new Airplane("Boeing 737", tc1);
        manager.addAirplane(a1);

        TravelClass tc2 = new TravelClass(200, 40, 20);
        Airplane a2 = new Airplane("Airbus A320", tc2);
        manager.addAirplane(a2);

        for (Airplane a : manager.getFleet()) {
            System.out.println(a);
            System.out.println("Total seats: " + a.getTravelClass().getTotalSeats());
        }
    }
}

/**
 * Represents an airplane with a model and a travel class configuration.
 */
class Airplane {
    private final String model;
    private final TravelClass travelClass;

    public Airplane(String model, TravelClass travelClass) {
        this.model = model;
        this.travelClass = travelClass;
    }

    public String getModel() {
        return model;
    }

    public TravelClass getTravelClass() {
        return travelClass;
    }

    @Override
    public String toString() {
        return "Airplane{" +
                "model='" + model + '\'' +
                ", travelClass=" + travelClass +
                '}';
    }
}

/**
 * Represents the seating configuration for an airplane.
 */
class TravelClass {
    private final int economySeats;
    private final int businessSeats;
    private final int firstClassSeats;

    public TravelClass(int economySeats, int businessSeats, int firstClassSeats) {
        this.economySeats = economySeats;
        this.businessSeats = businessSeats;
        this.firstClassSeats = firstClassSeats;
    }

    public int getEconomySeats() {
        return economySeats;
    }

    public int getBusinessSeats() {
        return businessSeats;
    }

    public int getFirstClassSeats() {
        return firstClassSeats;
    }

    /**
     * Returns the total number of seats across all classes.
     *
     * @return total seats
     */
    public int getTotalSeats() {
        return economySeats + businessSeats + firstClassSeats;
    }

    @Override
    public String toString() {
        return "TravelClass{" +
                "economySeats=" + economySeats +
                ", businessSeats=" + businessSeats +
                ", firstClassSeats=" + firstClassSeats +
                '}';
    }
}

