 * with the largest total seat count.
 */
public class AirplaneManager {

    private final List<Airplane> fleet = new ArrayList<>();

    /**
     * Adds an airplane to the fleet.
     *
     * @param airplane the airplane to add
     */
    public void addAirplane(Airplane airplane) {
        fleet.add(airplane);
    }

    /**
     * Returns the current fleet of airplanes.
