    public List<Airplane> findAirplanesByMinSeats(int minSeats) {
        List<Airplane> result = new ArrayList<>();
        for (Airplane airplane : fleet) {
            if (airplane.getTravelClass().getTotalSeats() >= minSeats) {
                result.add(airplane);
            }
        }
        return result;
