/**
 * Manager responsible for creating, updating, finding, and deleting clients.
 */
class ClientManager {
    private final Map<Long, ClientTO> clients = new HashMap<>();
    private final AtomicLong idGenerator = new AtomicLong(1);

    /**
     * Creates a new client, assigns a unique ID, stores it, and returns the client.
     *
     * @param client the client data (without ID)
     * @return the client with the assigned unique ID
     * @throws IllegalArgumentException if client is null, has a non-null ID,
     *         or if firstName, lastName, or email are null/empty.
     *         Email must contain '@'.
     */
    public ClientTO createClient(ClientTO client) {
        validateForCreate(client);

        long id = idGenerator.getAndIncrement();
        client.setId(id);
        clients.put(id, client);
        return client;
    }

    /**
     * Updates an existing client after validating its attributes.
     *
     * @param client the client data with an existing ID
     * @return the updated client
     * @throws IllegalArgumentException if client is null, ID is null,
     *         client does not exist, or validation fails.
     */
    public ClientTO updateClient(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null.");
        }
        Long id = client.getId();
        if (id == null) {
            throw new IllegalArgumentException("Client ID cannot be null for update.");
        }
        ClientTO existing = clients.get(id);
        if (existing == null) {
            throw new IllegalArgumentException("Client with ID " + id + " does not exist.");
        }

        validateForUpdate(client);

        // Update fields
        existing.setFirstName(client.getFirstName());
        existing.setLastName(client.getLastName());
        existing.setEmail(client.getEmail());
        existing.setPhone(client.getPhone());

        return existing;
    }

    /**
     * Finds a client by its ID.
     *
     * @param id the client's unique ID
     * @return the client if found, otherwise null
     * @throws IllegalArgumentException if id is null
     */
    public ClientTO findClient(Long id) {
        if (id == null) {
            throw new IllegalArgumentException("Client ID cannot be null.");
        }
        return clients.get(id);
    }

    /**
     * Deletes a client by ID.
     *
     * @param id the client's unique ID
     * @return true if the client was deleted, false if not found
     * @throws IllegalArgumentException if id is null
     */
    public boolean deleteClient(Long id) {
        if (id == null) {
            throw new IllegalArgumentException("Client ID cannot be null.");
        }
        return clients.remove(id) != null;
    }

    // Validation helpers
    private void validateForCreate(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null.");
        }
        if (client.getId() != null) {
            throw new IllegalArgumentException("Client ID must be null when creating a new client.");
        }
        if (isNullOrEmpty(client.getFirstName())) {
            throw new IllegalArgumentException("First name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getLastName())) {
            throw new IllegalArgumentException("Last name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getEmail())) {
            throw new IllegalArgumentException("Email cannot be null or empty.");
        }
        if (!client.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'.");
        }
    }

    private void validateForUpdate(ClientTO client) {
        if (isNullOrEmpty(client.getFirstName())) {
            throw new IllegalArgumentException("First name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getLastName())) {
            throw new IllegalArgumentException("Last name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getEmail())) {
            throw new IllegalArgumentException("Email cannot be null or empty.");
        }
        if (!client.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'.");
        }
    }

    private boolean isNullOrEmpty(String s) {
        return s == null || s.trim().isEmpty();
    }
}

/**
 * Example usage of the client management system.
 */
public class Main {
    public static void main(String[] args) {
        ClientManager manager = new ClientManager();

        // Create a client
        ClientTO client = new ClientTO("John", "Doe", "john.doe@example.com", "555-1234");
        ClientTO created = manager.createClient(client);
        System.out.println("Created: " + created);

        // Update the client
        ClientTO updatedInfo = new ClientTO("John", "Doe", "john.doe@newdomain.com", "555-5678");
        updatedInfo.setId(created.getId());
        ClientTO updated = manager.updateClient(updatedInfo);
        System.out.println("Updated: " + updated);

        // Find the client
        ClientTO found = manager.findClient(created.getId());
        System.out.println("Found: " + found);

        // Delete the client
        boolean deleted = manager.deleteClient(created.getId());
        System.out.println("Deleted: " + deleted);

        // Try to find again
        ClientTO afterDelete = manager.findClient(created.getId());
        System.out.println("After delete: " + afterDelete);
    }
