                "Unsupported value type: " + value.getClass().getName());
        }

        // Ensure the inner map for the user is a ConcurrentHashMap
        Map<String, Object> settings =
            userSettings.computeIfAbsent(username, k -> new ConcurrentHashMap<>());

        settings.put(key, value);
    }

    /**
     * Retrieves a setting for a specific user with type safety.
     *
     * @param key      the setting key
     * @param username the user identifier
     * @param type     the expected type of the setting value
     * @param <T>      the generic type parameter
     * @return the setting value cast to the requested type, or {@code null}
     *         if the user or key does not exist
     * @throws ClassCastException if the stored value is not of the requested type
     */
    public <T> T getUserSetting(String key, String username, Class<T> type) {
        Map<String, Object> settings = userSettings.get(username);
        if (settings == null) {
            return null;
        }

        Object value = settings.get(key);
        if (value == null) {
            return null;
        }

        if (!type.isInstance(value)) {
            throw new ClassCastException(
                "Expected type " + type.getName() + " but found " + value.getClass().getName());
        }

        return type.cast(value);
    }
}

