    private Node<D> head;
    private Node<D> tail;
    private int size;

    /** Creates an empty list */
    public LinkedList() {
        head = null;
        tail = null;
        size = 0;
    }

    /**
     * Adds an element to the end of the list.
     *
     * @param data the element to add
     */
    public void add(D data) {
        Node<D> newNode = new Node<>(data);
        if (head == null) {          // list is empty
            head = tail = newNode;
        } else {                     // append after tail
            tail.next = newNode;
            newNode.prev = tail;
            tail = newNode;
        }
        size++;
    }

    /**
     * Returns the number of elements in the list.
     *
     * @return the size of the list
     */
    public int size() {
        return size;
    }

    /**
     * Returns the data at the specified index.
     *
     * @param index the position of the element to retrieve
     * @return the data stored at the given index
     * @throws IndexOutOfBoundsException if the index is out of range
     */
    public D get(int index) {
        return getNode(index).data;
    }

    /**
     * Traverses the list to find the node at the specified index.
     * Traversal starts from the head if the index is in the first half,
     * otherwise it starts from the tail for efficiency.
     *
     * @param index the position of the node to retrieve
     * @return the node at the given index
     * @throws IndexOutOfBoundsException if the index is out of range
     */
    private Node<D> getNode(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException(
                "Index: " + index + ", Size: " + size);
        }

        Node<D> current;
        if (index < size / 2) {          // start from head
            current = head;
            for (int i = 0; i < index; i++) {
                current = current.next;
            }
        } else {                         // start from tail
            current = tail;
            for (int i = size - 1; i > index; i--) {
                current = current.prev;
            }
        }
        return current;
    }

    /** Optional: string representation of the list */
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        Node<D> current = head;
        while (current != null) {
            sb.append(current.data);
            current = current.next;
