                "Index: " + index + ", Size: " + size);
        }

        if (index == size) {          // insertion at the end
            add(data);
            return;
        }

        if (index == 0) {             // insertion at the beginning
            Node<D> newNode = new Node<>(data);
            newNode.next = head;
            if (head != null) {
                head.prev = newNode;
            }
            head = newNode;
            if (size == 0) {          // list was empty
                tail = newNode;
            }
            size++;
            return;
        }

        // insertion in the middle
        Node<D> current = getNode(index);   // node currently at position index
        Node<D> prevNode = current.prev;

        Node<D> newNode = new Node<>(data);
        newNode.prev = prevNode;
        newNode.next = current;
        prevNode.next = newNode;
        current.prev = newNode;

        size++;
    }

    /**
     * Returns the number of elements in the list.
     *
     * @return the size of the list
     */
