        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException(
                "Index: " + index + ", Size: " + size);
        }

        Node<D> toRemove = getNode(index);
        D data = toRemove.data;

        if (size == 1) {          // only one element
            head = tail = null;
        } else if (toRemove == head) {   // first element
            head = head.next;
            head.prev = null;
        } else if (toRemove == tail) {   // last element
            tail = tail.prev;
            tail.next = null;
        } else {                 // middle element
            Node<D> prevNode = toRemove.prev;
            Node<D> nextNode = toRemove.next;
            prevNode.next = nextNode;
            nextNode.prev = prevNode;
        }

        size--;
        return data;
    }

