class MatrixProcessor {

    public MatrixResult processMatrix(int[][] matrix, boolean useSpaceEfficient) {
        // Input validation
        if (matrix == null || matrix.length == 0 || matrix[0] == null || matrix[0].length == 0) {
            throw new IllegalArgumentException("Matrix cannot be null or empty");
        }

        int rows = matrix.length;
        int cols = matrix[0].length;

        // Count zeros in the original matrix
        int zeroCount = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matrix[r][c] == 0) {
                    zeroCount++;
                }
            }
        }

        // Deep copy of the original matrix for the result
        int[][] originalCopy = deepCopy(matrix);

        long startTime = System.nanoTime();

        int[][] processedMatrix;
        String methodUsed;

        if (useSpaceEfficient) {
            processedMatrix = zeroMatrixSpaceEfficient(matrix);
            methodUsed = "Space-Efficient";
        } else {
            processedMatrix = zeroMatrixWithSets(matrix);
            methodUsed = "HashSet-Based";
        }

        long endTime = System.nanoTime();
        long processingTimeMs = (endTime - startTime) / 1_000_000;

        return new MatrixResult(processedMatrix, originalCopy, zeroCount, processingTimeMs, methodUsed);
    }

    // O(n+m) space algorithm using HashSet
    private int[][] zeroMatrixWithSets(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        Set<Integer> zeroRows = new HashSet<>();
        Set<Integer> zeroCols = new HashSet<>();

        // Identify rows and columns that contain zeros
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matrix[r][c] == 0) {
                    zeroRows.add(r);
                    zeroCols.add(c);
                }
            }
        }

        // Create a copy to avoid modifying the input
        int[][] result = deepCopy(matrix);

        // Zero out identified rows
        for (int r : zeroRows) {
            for (int c = 0; c < cols; c++) {
                result[r][c] = 0;
            }
        }

        // Zero out identified columns
        for (int c : zeroCols) {
            for (int r = 0; r < rows; r++) {
                result[r][c] = 0;
            }
        }

        return result;
    }

    // O(1) space algorithm using first row/column as markers
    private int[][] zeroMatrixSpaceEfficient(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        // Create a copy to avoid modifying the input
        int[][] result = deepCopy(matrix);

        boolean firstRowHasZero = false;
        boolean firstColHasZero = false;

        // Check first row
        for (int c = 0; c < cols; c++) {
            if (result[0][c] == 0) {
                firstRowHasZero = true;
                break;
            }
        }

        // Check first column
        for (int r = 0; r < rows; r++) {
            if (result[r][0] == 0) {
                firstColHasZero = true;
                break;
            }
        }

        // Use first row and column as markers
        for (int r = 1; r < rows; r++) {
            for (int c = 1; c < cols; c++) {
                if (result[r][c] == 0) {
                    result[r][0] = 0;
                    result[0][c] = 0;
                }
            }
        }

        // Zero out rows based on markers
        for (int r = 1; r < rows; r++) {
            if (result[r][0] == 0) {
                for (int c = 1; c < cols; c++) {
                    result[r][c] = 0;
                }
            }
        }

        // Zero out columns based on markers
        for (int c = 1; c < cols; c++) {
            if (result[0][c] == 0) {
                for (int r = 1; r < rows; r++) {
                    result[r][c] = 0;
                }
            }
        }

        // Zero out first row if needed
        if (firstRowHasZero) {
            for (int c = 0; c < cols; c++) {
                result[0][c] = 0;
            }
        }

        // Zero out first column if needed
        if (firstColHasZero) {
            for (int r = 0; r < rows; r++) {
                result[r][0] = 0;
            }
        }

        return result;
    }

    // Helper method to create a deep copy of a matrix
    private static int[][] deepCopy(int[][] source) {
        int rows = source.length;
        int[][] copy = new int[rows][];
        for (int r = 0; r < rows; r++) {
            copy[r] = source[r].clone(); // clone creates a new array with the same elements
