// Enhanced product manager with validation, logging, restricted categories and unique ID enforcement
class EnhancedProductManager {
    private final Map<Integer, Product> productDatabase;
    private final LoggerService logger;
    private final Set<Integer> restrictedCategories;

    public EnhancedProductManager(LoggerService logger, List<Integer> restrictedCategories) {
        this.productDatabase = new HashMap<>();
        this.logger = logger;
        this.restrictedCategories = new HashSet<>(
                restrictedCategories != null ? restrictedCategories : Collections.emptyList()
        );
    }

    // Add a product with all validations
    public Map<String, String> addProduct(Product product) {
        Map<String, String> result = new HashMap<>();

        if (product == null) {
            result.put("status", "error");
            result.put("message", "Product cannot be null");
            return result;
        }

        // Validate product name
        String name = product.getName();
        if (name == null || name.trim().isEmpty()) {
            result.put("status", "error");
            result.put("message", "Product name cannot be empty");
            return result;
        }

        // Validate restricted category
        int categoryId = product.getCategoryId();
        if (restrictedCategories.contains(categoryId)) {
            result.put("status", "error");
            result.put("message", "Products in category " + categoryId + " are not allowed");
            return result;
        }

        // Ensure unique ID
        int id = product.getId();
        if (productDatabase.containsKey(id)) {
            result.put("status", "error");
            result.put("message", "Product ID " + id + " already exists");
            return result;
        }

        // Add product
        productDatabase.put(id, product);
        result.put("status", "success");
        result.put("message", "Product added successfully");

        logger.log("Product added: " + product.getName());
        return result;
    }

