    private static int idCounter = 1; // simple incremental ID generator

    public TaskDatabaseManager() {
        this.taskCache = new ArrayList<>();
    }

    /**
     * Inserts a new task into the in-memory cache.
     *
     * @param taskType    the type of the task (e.g., 1 for assignment, 2 for quiz)
