     *         and the number of affected rows (always 1 on success)
     */
    public Map<String, Object> insertTask(int taskType, String taskName, String taskContent,
                                          int studentId, String studentName) {
        Map<String, Object> result = new HashMap<>();

        try {
            // Generate a UUID-based task ID
            String taskId = UUID.randomUUID().toString();

            // Current timestamp in the required format
            String createdAt = LocalDateTime.now()
                    .format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));

            // Create a task record with all required fields
            Map<String, Object> taskRecord = new HashMap<>();
            taskRecord.put("taskId", taskId);
            taskRecord.put("taskType", taskType);
            taskRecord.put("taskName", taskName);
            taskRecord.put("taskContent", taskContent);
            taskRecord.put("studentId", studentId);
            taskRecord.put("studentName", studentName);
            taskRecord.put("createdAt", createdAt);
            taskRecord.put("successCount", 0);
            taskRecord.put("failCount", 0);
            taskRecord.put("score", 0);
            taskRecord.put("status", "pending");

            // Store the task in the cache
            taskCache.add(taskRecord);

            // Prepare success response
            result.put("status", "success");
            result.put("taskId", taskId);
            result.put("affectedRows", 1);
        } catch (Exception e) {
            // In case of any unexpected error, return an error status
            result.put("status", "error");
            result.put("message", e.getMessage());
        }

        return result;
    }

    /**
     * Queries tasks based on the provided criteria and pagination parameters.
     *
     * @param criteria   a map of key-value pairs that tasks must match exactly
     * @param pageNumber the 1‑based page number to retrieve
     * @param pageSize   the number of items per page
     * @return a map containing:
     *         - "tasks": List of task maps for the requested page
     *         - "currentPage": the actual page number returned
     *         - "totalPages": total number of pages available
     *         - "totalItems": total number of items matching the criteria
     */
    public Map<String, Object> queryTasks(Map<String, Object> criteria, int pageNumber, int pageSize) {
        Map<String, Object> result = new HashMap<>();

        // 1. Filter tasks that match all criteria exactly
        List<Map<String, Object>> filtered = new ArrayList<>();
        for (Map<String, Object> task : taskCache) {
            boolean matches = true;
            for (Map.Entry<String, Object> entry : criteria.entrySet()) {
                Object taskValue = task.get(entry.getKey());
                if (taskValue == null || !taskValue.equals(entry.getValue())) {
                    matches = false;
                    break;
                }
            }
            if (matches) {
                filtered.add(task);
            }
        }

        int totalItems = filtered.size();
        int totalPages = (pageSize <= 0) ? 1 : (int) Math.ceil((double) totalItems / pageSize);
        if (totalPages == 0) {
            totalPages = 1; // Ensure at least one page exists even when there are no items
        }

        // Clamp pageNumber to valid range
        if (pageNumber < 1) {
            pageNumber = 1;
        } else if (pageNumber > totalPages) {
            pageNumber = totalPages;
        }

        // 2. Determine sublist for the requested page
        int startIndex = (pageNumber - 1) * pageSize;
        int endIndex = Math.min(startIndex + pageSize, totalItems);
        List<Map<String, Object>> pageTasks = (startIndex < endIndex) ? filtered.subList(startIndex, endIndex) : Collections.emptyList();

        // 3. Build result map
        result.put("tasks", pageTasks);
        result.put("currentPage", pageNumber);
        result.put("totalPages", totalPages);
        result.put("totalItems", totalItems);

        return result;
    }

    /**
     * Updates the statistics of a task identified by {@code taskId}.
     *
     * @param taskId          the UUID of the task to update
     * @param successIncrement amount to add to {@code successCount}
     * @param failIncrement    amount to add to {@code failCount}
     * @param scoreIncrement   amount to add to {@code score}
     * @return a map containing:
     *         - "status": "success" or "error"
     *         - "modifiedFields": list of field names that were changed (only on success)
     *         - "message": error description (only on error)
     */
    public Map<String, Object> updateTaskStats(String taskId, int successIncrement,
                                               int failIncrement, int scoreIncrement) {
        Map<String, Object> result = new HashMap<>();
        List<String> modifiedFields = new ArrayList<>();

        for (Map<String, Object> task : taskCache) {
            if (taskId.equals(task.get("taskId"))) {
                // Update successCount
                if (successIncrement != 0) {
                    int newSuccess = ((Integer) task.get("successCount")) + successIncrement;
                    task.put("successCount", newSuccess);
                    modifiedFields.add("successCount");
                    // Update status if needed
                    if (newSuccess > 0 && !"completed".equals(task.get("status"))) {
                        task.put("status", "completed");
                        modifiedFields.add("status");
                    }
                }

                // Update failCount
                if (failIncrement != 0) {
                    int newFail = ((Integer) task.get("failCount")) + failIncrement;
                    task.put("failCount", newFail);
                    modifiedFields.add("failCount");
                }

                // Update score
                if (scoreIncrement != 0) {
                    int newScore = ((Integer) task.get("score")) + scoreIncrement;
                    task.put("score", newScore);
                    modifiedFields.add("score");
                }

                result.put("status", "success");
                result.put("modifiedFields", modifiedFields);
                return result;
            }
        }

        // Task not found
        result.put("status", "error");
        result.put("message", "Task not found");
        return result;
    }

    // Optional helper method to retrieve all tasks (useful for testing or debugging)
    public List<Map<String, Object>> getAllTasks() {
        return new ArrayList<>(taskCache);
    }
}
