        }
        return false;
    }

    /**
     * Updates the user identified by {@code id}. Only non‑null fields are
     * considered for update. {@code username} and {@code email} must remain
     * unique across all users (excluding the user being updated). If the
     * user is not found, {@link IllegalArgumentException} is thrown.
     *
     * @param id       the ID of the user to update
     * @param username the new username (may be {@code null})
     * @param email    the new email (may be {@code null})
     * @param password the new password (may be {@code null})
     * @return the updated {@link User}
     * @throws IllegalArgumentException if the user is not found or if the
     *                                  new username/email conflicts with
     *                                  another user
     */
    public User updateUser(Long id, String username, String email, String password) {
        User user = findUserById(id)
                .orElseThrow(() -> new IllegalArgumentException("User not found: " + id));

        // Check username uniqueness
        if (username != null && !username.equals(user.getUsername())) {
            boolean usernameTaken = users.stream()
                    .anyMatch(u -> u.getId().equals(id) == false && u.getUsername().equals(username));
            if (usernameTaken) {
                throw new IllegalArgumentException("Username already taken: " + username);
            }
            user.setUsername(username);
        }

        // Check email uniqueness
        if (email != null && !email.equals(user.getEmail())) {
            boolean emailTaken = users.stream()
                    .anyMatch(u -> u.getId().equals(id) == false && u.getEmail().equals(email));
            if (emailTaken) {
                throw new IllegalArgumentException("Email already taken: " + email);
            }
            user.setEmail(email);
        }

        // Update password if provided
        if (password != null) {
            user.setPassword(password);
        }

        return user;
    }

