public class FragmentManager {
    private final Map<String, Fragment> fragments = new HashMap<>();
    private Fragment currentFragment = null;

    /**
     * Adds a fragment with the specified tag.
     *
     * @param tag      the unique tag for the fragment
     * @param fragment the fragment instance to store
     */
    public void addFragment(String tag, Fragment fragment) {
        if (tag == null || fragment == null) {
            throw new IllegalArgumentException("Tag and fragment must not be null");
        }
        fragments.put(tag, fragment);
    }

    /**
     * Switches the current fragment to the one identified by the given tag.
     *
     * @param tag the tag of the fragment to switch to
     * @throws IllegalArgumentException if no fragment exists for the tag
     */
    public void switchFragment(String tag) {
        Fragment target = fragments.get(tag);
        if (target == null) {
            throw new IllegalArgumentException("No fragment found with tag: " + tag);
        }
        currentFragment = target;
    }

    /**
     * Returns the currently active fragment.
     *
     * @return the current fragment, or null if none has been selected
     */
    public Fragment getCurrentFragment() {
        return currentFragment;
    }

