import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class DocumentationValidator {

    // Pattern that matches a backslash character
    public static final Pattern INVALID_CHAR_PATTERN = Pattern.compile("\\\\");

    // Pattern that matches placeholders of the form ${...}
    public static final Pattern PLACEHOLDER_PATTERN = Pattern.compile("\\$\\{([^}]+)\\}");

    // Immutable list of allowed placeholder names
    public static final List<String> ALLOWED_PLACEHOLDERS =
            Collections.unmodifiableList(List.of("method", "class", "param", "return"));

    /**
     * Validates the given documentation string.
     *
     * @param doc           the documentation string to validate
     * @param qualifiedName the fully qualified name of the element being documented
     */
    public static void validateDocumentation(String doc, String qualifiedName) {
        // Return silently if documentation is null
        if (doc == null) {
            return;
        }

        // Throw if documentation is empty or contains only whitespace
        if (doc.trim().isEmpty()) {
            throw new IllegalArgumentException(
                    "Empty documentation string for: " + qualifiedName);
        }

        // Validate that the documentation does not contain backslashes
        if (INVALID_CHAR_PATTERN.matcher(doc).find()) {
            throw new IllegalArgumentException(
                    "Documentation contains invalid characters: " + qualifiedName);
        }

        // Validate placeholder usage
        Matcher matcher = PLACEHOLDER_PATTERN.matcher(doc);
        while (matcher.find()) {
            String placeholderName = matcher.group(1);
            if (!ALLOWED_PLACEHOLDERS.contains(placeholderName)) {
                throw new IllegalArgumentException(
                        "Invalid placeholder '" + placeholderName + "' in documentation for: " + qualifiedName);
            }
        }

        // Validate documentation length
        if (doc.length() > 500) {
            throw new IllegalArgumentException(
                    "Documentation exceeds 500 characters for: " + qualifiedName);
        }
    }

    /**
     * Validates class documentation and the documentation of its methods.
     *
     * @param className   the fully qualified name of the class
     * @param classDoc    the documentation string for the class
     * @param methodDocs  a list of documentation strings for the class's methods
     */
    public static void validateClassDocumentation(String className, String classDoc, List<String> methodDocs) {
        // Validate the class documentation
        validateDocumentation(classDoc, className);

        // Validate each method documentation
        for (int i = 0; i < methodDocs.size(); i++) {
            String methodDoc = methodDocs.get(i);
            String qualifiedMethodName = className + ".method" + (i + 1);
            validateDocumentation(methodDoc, qualifiedMethodName);
        }
    }
}

