        // ---------- Second pass ----------
        // Order nodes by decreasing finishing time
        List<Integer> order = new ArrayList<>(reverseGraph.keySet());
        order.sort((u, v) -> Integer.compare(finishingTimes.get(v), finishingTimes.get(u)));

        visited.clear(); // reuse visited set for second pass

        for (Integer node : order) {
            if (!visited.contains(node)) {
                dfsOriginal(node, node, visited);
            }
        }

        // ---------- Contradiction check ----------
        for (int v : variables) {
            int pos = v;
            int neg = -v;
