import java.util.*;

class TwoSatSolver {
    // Set of all variable indices (positive integers)
    private final Set<Integer> variables;
    // Optional: store the clauses for debugging or future use
    private final List<int[]> clauses;
    // Implication graph: each literal maps to a list of literals it implies
    private final Map<Integer, List<Integer>> graph;
    // Reverse graph: each literal maps to a list of literals that imply it
    private final Map<Integer, List<Integer>> reverseGraph;
    // Finishing times computed during the first pass of Kosaraju
    private final Map<Integer, Integer> finishingTimes;
    // Leader of each node after the second pass
    private final Map<Integer, Integer> leaders;

    public TwoSatSolver() {
        this.variables = new HashSet<>();
        this.clauses = new ArrayList<>();
        this.graph = new HashMap<>();
        this.reverseGraph = new HashMap<>();
        this.finishingTimes = new HashMap<>();
        this.leaders = new HashMap<>();
    }

    /**
     * Adds a clause (a ∨ b) to the solver.
     * @param a first literal (positive for variable, negative for negated variable)
     * @param b second literal
     */
    public void addClause(int a, int b) {
        // Record the variables involved
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        // Store the clause itself (optional)
        clauses.add(new int[]{a, b});

        // Add implication edges: (-a → b) and (-b → a)
        int negA = -a;
        int negB = -b;

        graph.computeIfAbsent(negA, k -> new ArrayList<>()).add(b);
        graph.computeIfAbsent(negB, k -> new ArrayList<>()).add(a);

        // Ensure that the literals a and b also appear in the graph
        graph.computeIfAbsent(a, k -> new ArrayList<>());
        graph.computeIfAbsent(b, k -> new ArrayList<>());

        // Build reverse graph edges
        reverseGraph.computeIfAbsent(b, k -> new ArrayList<>()).add(negA);
        reverseGraph.computeIfAbsent(a, k -> new ArrayList<>()).add(negB);

        // Ensure all literals appear in the reverse graph as well
        reverseGraph.computeIfAbsent(negA, k -> new ArrayList<>());
        reverseGraph.computeIfAbsent(negB, k -> new ArrayList<>());
        reverseGraph.computeIfAbsent(a, k -> new ArrayList<>());
        reverseGraph.computeIfAbsent(b, k -> new ArrayList<>());
    }

    /**
     * Performs both passes of Kosaraju's algorithm and checks for contradictions.
     * Returns true if the current set of clauses is satisfiable, false otherwise.
     */
    public boolean isSatisfiable() {
        // ---------- First pass ----------
        Set<Integer> visited = new HashSet<>();
        int[] time = {0}; // mutable counter for finishing times

        for (Integer node : reverseGraph.keySet()) {
            if (!visited.contains(node)) {
                dfsReverse(node, visited, time);
            }
        }

        // ---------- Second pass ----------
        // Order nodes by decreasing finishing time
        List<Integer> order = new ArrayList<>(reverseGraph.keySet());
        order.sort((u, v) -> Integer.compare(finishingTimes.get(v), finishingTimes.get(u)));

        visited.clear(); // reuse visited set for second pass

        for (Integer node : order) {
            if (!visited.contains(node)) {
                dfsOriginal(node, node, visited);
            }
        }

        // ---------- Contradiction check ----------
        for (int v : variables) {
            int pos = v;
            int neg = -v;
            Integer leaderPos = leaders.get(pos);
            Integer leaderNeg = leaders.get(neg);
            if (leaderPos != null && leaderNeg != null && leaderPos.equals(leaderNeg)) {
                return false; // variable and its negation in the same SCC
            }
        }
        return true;
    }

    // Depth‑first search on the reverse graph (first pass)
    private void dfsReverse(int node, Set<Integer> visited, int[] time) {
        visited.add(node);
        for (Integer neighbor : reverseGraph.getOrDefault(node, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                dfsReverse(neighbor, visited, time);
            }
        }
        finishingTimes.put(node, ++time[0]); // finishing time after exploring all neighbors
    }

    // Depth‑first search on the original graph (second pass)
    private void dfsOriginal(int node, int leader, Set<Integer> visited) {
        visited.add(node);
        leaders.put(node, leader);
        for (Integer neighbor : graph.getOrDefault(node, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                dfsOriginal(neighbor, leader, visited);
            }
        }
    }

    // Optional helper methods for inspection

    public Set<Integer> getVariables() {
        return Collections.unmodifiableSet(variables);
    }

    public List<int[]> getClauses() {
        return Collections.unmodifiableList(clauses);
    }

    public Map<Integer, List<Integer>> getGraph() {
        return Collections.unmodifiableMap(graph);
    }

    public Map<Integer, List<Integer>> getReverseGraph() {
        return Collections.unmodifiableMap(reverseGraph);
    }

    public Map<Integer, Integer> getFinishingTimes() {
        return Collections.unmodifiableMap(finishingTimes);
    }

    public Map<Integer, Integer> getLeaders() {
        return Collections.unmodifiableMap(leaders);
    }
}
