class NeuralNetworkCalculator {
    private final int inputSize;
    private final int hiddenSize;
    private final int outputSize;
    private final double[] weights;
    private final double[][] inputNormalizationParams;
    private final double[][] outputNormalizationParams;

    public NeuralNetworkCalculator(int inputSize, int hiddenSize, int outputSize,
                                   double[] weights,
                                   double[][] inputNormalizationParams,
                                   double[][] outputNormalizationParams) {
        this.inputSize = inputSize;
        this.hiddenSize = hiddenSize;
        this.outputSize = outputSize;
        this.weights = weights;
        this.inputNormalizationParams = inputNormalizationParams;
        this.outputNormalizationParams = outputNormalizationParams;
    }

    /**
     * Performs a forward pass through a simple feed‑forward neural network
     * with one hidden layer. The network uses sigmoid activation in the
     * hidden layer and a linear output. Input and output are normalized
     * using the provided parameters.
     *
     * @param input the raw input vector (length must equal inputSize)
     * @return the denormalized output vector (length equals outputSize)
     * @throws IllegalArgumentException if input length does not match inputSize
     */
    public double[] calculate(double[] input) {
        if (input == null || input.length != inputSize) {
            throw new IllegalArgumentException(
                "Input must be non‑null and of length " + inputSize);
        }

        // 1. Normalize input
        double[] normInput = new double[inputSize];
        for (int i = 0; i < inputSize; i++) {
            double mean = inputNormalizationParams[i][0];
            double std  = inputNormalizationParams[i][1];
            if (std == 0) {
                normInput[i] = input[i] - mean;
            } else {
                normInput[i] = (input[i] - mean) / std;
            }
        }

        // 2. Compute hidden activations
        double[] hidden = new double[hiddenSize];
        int idx = 0; // index in weights array
        for (int h = 0; h < hiddenSize; h++) {
            double sum = 0.0;
            for (int i = 0; i < inputSize; i++) {
                sum += normInput[i] * weights[idx++];
            }
            hidden[h] = sigmoid(sum);
        }

        // 3. Compute raw output (linear)
        double[] rawOutput = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double sum = 0.0;
            for (int h = 0; h < hiddenSize; h++) {
                sum += hidden[h] * weights[idx++];
            }
            rawOutput[o] = sum;
        }

        // 4. Denormalize output
        double[] output = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double mean = outputNormalizationParams[o][0];
            double std  = outputNormalizationParams[o][1];
            output[o] = rawOutput[o] * std + mean;
        }

        return output;
    }

    // Sigmoid activation function
    private static double sigmoid(double x) {
        return 1.0 / (1.0 + Math.exp(-x));
    }
}

