import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class AdvancedDotProductCalculator {

    /**
     * Calculates the dot product of two integer arrays sequentially.
     *
     * @param first  the first array
     * @param second the second array
     * @return the dot product
     * @throws IllegalArgumentException if either array is null or they have different lengths
     */
    public static int calculateDotProduct(int[] first, int[] second) {
        validateArrays(first, second);

        int dotProduct = 0;
        for (int i = 0; i < first.length; i++) {
            dotProduct += first[i] * second[i];
        }
        return dotProduct;
    }

    /**
     * Calculates the dot product of two integer arrays using parallel computation.
     *
     * @param first       the first array
     * @param second      the second array
     * @param threadCount the number of threads to use
     * @return the dot product
     * @throws IllegalArgumentException if either array is null, they have different lengths,
     *                                  or threadCount is not positive
     */
    public static int calculateDotProduct(int[] first, int[] second, int threadCount) {
        validateArrays(first, second);

        if (threadCount <= 0) {
            throw new IllegalArgumentException("Thread count must be positive");
        }

        int length = first.length;
        if (length == 0) {
            return 0;
        }

        ExecutorService executor = Executors.newFixedThreadPool(threadCount);
        List<Future<Integer>> futures = new ArrayList<>();

        int chunkSize = (length + threadCount - 1) / threadCount; // ceil division
        for (int start = 0; start < length; start += chunkSize) {
            final int chunkStart = start;
            final int chunkEnd = Math.min(start + chunkSize, length);

            Callable<Integer> task = () -> {
                int partialSum = 0;
                for (int i = chunkStart; i < chunkEnd; i++) {
                    partialSum += first[i] * second[i];
                }
                return partialSum;
            };
            futures.add(executor.submit(task));
        }

        int dotProduct = 0;
        try {
            for (Future<Integer> future : futures) {
                dotProduct += future.get();
            }
        } catch (InterruptedException | ExecutionException e) {
            // If an exception occurs, wrap it in a RuntimeException
            throw new RuntimeException("Error computing dot product in parallel", e);
        } finally {
            executor.shutdown();
        }

        return dotProduct;
    }

    /**
     * Validates that the input arrays are non-null and of equal length.
     *
     * @param first  the first array
     * @param second the second array
     * @throws IllegalArgumentException if validation fails
     */
    private static void validateArrays(int[] first, int[] second) {
        if (first == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }
        if (second == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }
        if (first.length != second.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }
    }
}

