     * @param availableBandwidths array of available bandwidths
     * @return a Plan containing only valid assignments and channels
     */
    public static Plan createPlan(double[] requiredBandwidths, double[] availableBandwidths) {
        List<FrequencyAssignment> assignments = new ArrayList<>();
        for (double bw : requiredBandwidths) {
            if (bw > 0) {
                assignments.add(new FrequencyAssignment(bw));
            }
        }

        List<Channel> channels = new ArrayList<>();
        for (double bw : availableBandwidths) {
            if (bw > 0) {
                channels.add(new Channel(bw));
            }
        }

        return new Plan(assignments, channels);
    }
}

