import java.util.HashMap;
import java.util.Map;
import java.util.Set;

class RegionTextureManager {
    private final Map<String, TexturePack> regionPacks = new HashMap<>();
    private TexturePack defaultPack;

    public RegionTextureManager(TexturePack defaultPack) {
        if (defaultPack == null) {
            throw new IllegalArgumentException("defaultPack cannot be null");
        }
        this.defaultPack = defaultPack;
    }

    /**
     * Associates a texture pack with a region.
     *
     * @param regionId the unique identifier of the region
     * @param pack     the texture pack to associate
     */
    public void addRegionPack(String regionId, TexturePack pack) {
        if (regionId == null || pack == null) {
            throw new IllegalArgumentException("regionId and pack cannot be null");
        }
        regionPacks.put(regionId, pack);
    }

    /**
     * Retrieves the texture pack for a given region.
     * If no pack is registered for the region, the default pack is returned.
     *
     * @param regionId the unique identifier of the region
     * @return the associated texture pack or the default pack
     */
    public TexturePack getRegionPack(String regionId) {
        TexturePack pack = regionPacks.get(regionId);
        return pack != null ? pack : defaultPack;
    }

    /**
     * Removes the texture pack association for a region.
     *
     * @param regionId the unique identifier of the region
     */
    public void removeRegionPack(String regionId) {
        regionPacks.remove(regionId);
    }

    /**
     * Returns a set of all region identifiers that have a custom pack.
     *
     * @return set of region IDs
     */
    public Set<String> getAllRegionIds() {
        return regionPacks.keySet();
    }

    /**
     * Returns a copy of the map containing all region-to-pack associations.
     *
     * @return map of region IDs to texture packs
     */
    public Map<String, TexturePack> getAllRegionPacks() {
        return new HashMap<>(regionPacks);
    }

    /**
     * Retrieves the default texture pack.
     *
     * @return the default texture pack
     */
    public TexturePack getDefaultPack() {
        return defaultPack;
    }

    /**
     * Sets a new default texture pack.
     *
     * @param defaultPack the new default texture pack
     */
    public void setDefaultPack(TexturePack defaultPack) {
        if (defaultPack == null) {
            throw new IllegalArgumentException("defaultPack cannot be null");
        }
        this.defaultPack = defaultPack;
    }

    /**
     * Checks if a region has a custom texture pack.
     *
     * @param regionId the unique identifier of the region
     * @return true if the region has a custom pack, false otherwise
     */
    public boolean hasCustomPack(String regionId) {
        TexturePack pack = regionPacks.get(regionId);
        return pack != null && pack.isCustom();
    }
}

class TexturePack {
    private final String name;
    private final boolean isCustom;

    public TexturePack(String name, boolean isCustom) {
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("name cannot be null or empty");
        }
        this.name = name;
        this.isCustom = isCustom;
    }

    public String getName() {
        return name;
    }

    public boolean isCustom() {
        return isCustom;
    }

    @Override
    public String toString() {
        return "TexturePack{name='" + name + '\'' + ", isCustom=" + isCustom + '}';
    }
