class HttpRequestSimulator {
    public Map<String, Object> simulateHttpRequest(String url, String method,
                                                   Map<String, String> params,
                                                   Map<String, String> headers) {
        Map<String, Object> response = new HashMap<>();

        // Simulated status code
        response.put("status", 200);

        // Simulated body message
        String body = "Simulated response for " + method + " request to " + url + ".";
        response.put("body", body);

        // Simulated request time in milliseconds (random between 50 and 200 ms)
        int requestTime = ThreadLocalRandom.current().nextInt(50, 201);
        response.put("requestTime", requestTime);

        return response;
    }
}

