import java.util.List;
import java.util.Map;
import java.util.ArrayList;
import java.util.HashMap;

/**
 * Utility class that processes a batch of HTTP request maps sequentially.
 * Each request map must contain the following keys:
 *   - "url"      : String
 *   - "method"   : String ("GET" or "POST")
 *   - "params"   : Map<String, String> (may be null)
 *   - "headers"  : Map<String, String> (may be null)
 *
 * The method returns a list of response maps produced by {@link HttpRequestSimulator}.
 */
public class BatchProcessor {

    private final HttpRequestSimulator simulator = new HttpRequestSimulator();

    /**
     * Processes a list of request maps sequentially and returns a list of response maps.
     *
     * @param requests List of request maps to process.
     * @return List of response maps in the same order as the input requests.
     * @throws IllegalArgumentException if any request map is missing required keys or contains invalid values.
     */
    public List<Map<String, Object>> processBatchRequests(List<Map<String, Object>> requests) {
        if (requests == null) {
            throw new IllegalArgumentException("Request list must not be null.");
        }

        List<Map<String, Object>> responses = new ArrayList<>(requests.size());

        for (Map<String, Object> request : requests) {
            // Validate request map
            if (request == null) {
                throw new IllegalArgumentException("Request map must not be null.");
            }

            // Extract required fields
            Object urlObj = request.get("url");
            Object methodObj = request.get("method");
            @SuppressWarnings("unchecked")
            Map<String, String> params = (Map<String, String>) request.get("params");
            @SuppressWarnings("unchecked")
            Map<String, String> headers = (Map<String, String>) request.get("headers");

            if (!(urlObj instanceof String) || !(methodObj instanceof String)) {
                throw new IllegalArgumentException("Request must contain 'url' and 'method' as strings.");
            }

            String url = (String) urlObj;
            String method = (String) methodObj;

            // Delegate to HttpRequestSimulator
            Map<String, Object> response = simulator.simulateHttpRequest(url, method, params, headers);
            responses.add(response);
        }

        return responses;
    }
}

