import java.util.*;

class MinesweeperSolver {
    private char[][] map;
    private boolean[][] visited;
    private final int[] dirR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private final int[] dirC = {-1, 0, 1, -1, 1, -1, 0, 1};

    /**
     * Calculates the minimum number of clicks required to reveal all safe cells.
     * Each safe cell must be clicked individually (no auto‑reveal).
     *
     * @param boardSize     the size of the board (N x N)
     * @param minePositions a list of strings in the form "r,c" indicating mine locations
     * @return the number of safe cells (i.e., the required clicks)
     */
    public int solveMinesweeper(int boardSize, List<String> minePositions) {
        // Initialize board with padding to avoid bounds checks
        map = new char[boardSize + 2][boardSize + 2];
        visited = new boolean[boardSize + 2][boardSize + 2];

        // Fill board with safe cells
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                map[i][j] = '.';
            }
        }

        // Place mines
        for (String pos : minePositions) {
            String[] parts = pos.split(",");
            int r = Integer.parseInt(parts[0].trim());
            int c = Integer.parseInt(parts[1].trim());
            map[r][c] = '*';
        }

        // Count safe cells
        int safeCells = 0;
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] != '*') {
                    safeCells++;
                }
            }
        }
        return safeCells;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Read board size
        int boardSize = sc.nextInt();
        // Read number of mines
        int mineCount = sc.nextInt();
