public class Vector3 {
    private double x;
    private double y;
    private double z;

    public Vector3() {
        this(0, 0, 0);
    }

    public Vector3(double x, double y, double z) {
        this.x = x;
        this.y = y;
        this.z = z;
    }

    public double getX() {
        return x;
    }

    public void setX(double x) {
        this.x = x;
    }

    public double getY() {
        return y;
    }

    public void setY(double y) {
        this.y = y;
    }

    public double getZ() {
        return z;
    }

    public void setZ(double z) {
        this.z = z;
    }

    /**
     * Returns the length (magnitude) of this vector.
     */
    public double length() {
        return Math.sqrt(x * x + y * y + z * z);
    }

    /**
     * Returns a new vector that is the normalized (unit) version of this vector.
     * If the vector has zero length, the method returns a zero vector.
     */
    public Vector3 normalized() {
        double len = length();
        if (len == 0) {
            return new Vector3(0, 0, 0);
        }
        return new Vector3(x / len, y / len, z / len);
    }

    /**
     * Computes the dot product of this vector with another vector.
     */
    public double dot(Vector3 other) {
        return this.x * other.x + this.y * other.y + this.z * other.z;
    }

    /**
     * Returns a new vector that is the result of subtracting the given vector from this vector.
     */
    public Vector3 sub(Vector3 other) {
        return new Vector3(this.x - other.x, this.y - other.y, this.z - other.z);
    }
}

