public class EnhancedSpotLight extends PointLight {
    private Vector3 direction;
    private double cutoffAngle;
    private double outerCutoffAngle;
    private double falloffExponent;

    public EnhancedSpotLight() {
        this(new Vector3(), 1.0, new Vector3(), 12.5, 17.5, 1.0);
    }

    public EnhancedSpotLight(Vector3 position, double intensity, Vector3 direction,
                             double cutoffAngle, double outerCutoffAngle,
                             double falloffExponent) {
        super(position, intensity);
        setDirection(direction);
        setCutoffAngle(cutoffAngle);
        setOuterCutoffAngle(outerCutoffAngle);
        setFalloffExponent(falloffExponent);
    }

    public Vector3 getDirection() {
        return direction;
    }

    public void setDirection(Vector3 direction) {
        if (direction == null) {
            throw new IllegalArgumentException("Direction cannot be null");
        }
        this.direction = direction;
    }

    public double getCutoffAngle() {
        return cutoffAngle;
    }

    public void setCutoffAngle(double cutoffAngle) {
        if (cutoffAngle < 0 || cutoffAngle > 90) {
            throw new IllegalArgumentException("Cutoff angle must be between 0 and 90 degrees");
        }
        if (this.outerCutoffAngle != 0 && cutoffAngle >= this.outerCutoffAngle) {
            throw new IllegalArgumentException("Cutoff angle must be less than outer cutoff angle");
        }
        this.cutoffAngle = cutoffAngle;
    }

    public double getOuterCutoffAngle() {
        return outerCutoffAngle;
    }

    public void setOuterCutoffAngle(double outerCutoffAngle) {
        if (outerCutoffAngle < 0 || outerCutoffAngle > 90) {
            throw new IllegalArgumentException("Outer cutoff angle must be between 0 and 90 degrees");
        }
        if (this.cutoffAngle != 0 && outerCutoffAngle <= this.cutoffAngle) {
            throw new IllegalArgumentException("Outer cutoff angle must be greater than cutoff angle");
        }
        this.outerCutoffAngle = outerCutoffAngle;
    }

    public double getFalloffExponent() {
        return falloffExponent;
    }

    public void setFalloffExponent(double falloffExponent) {
        if (falloffExponent <= 0) {
            throw new IllegalArgumentException("Falloff exponent must be positive");
        }
        this.falloffExponent = falloffExponent;
    }

    /**
     * Calculates the intensity of the spotlight at a given point.
     * Combines angular attenuation with distance attenuation.
     *
     * @param point The point at which to calculate intensity.
     * @return The attenuated intensity value.
     */
    public double calculateIntensity(Vector3 point) {
        // Vector from light position to point
        Vector3 toPoint = point.sub(getPosition()).normalized();
        // Normalized spotlight direction
        Vector3 dir = getDirection().normalized();

        // Cosine of angle between light direction and vector to point
        double cosTheta = dir.dot(toPoint);

        // Convert cutoff angles to radians and compute their cosines
        double cosCutoff = Math.cos(Math.toRadians(getCutoffAngle()));
        double cosOuter = Math.cos(Math.toRadians(getOuterCutoffAngle()));

        double baseIntensity = getIntensity();

        // Distance attenuation
        double distance = point.sub(getPosition()).length();
        double denom = getConstantAttenuation()
                + getLinearAttenuation() * distance
                + getExponentAttenuation() * distance * distance;
        double distanceAttenuation = denom > 0 ? 1.0 / denom : 0.0;

        if (cosTheta >= cosCutoff) {
            // Inside inner cone
            return baseIntensity * distanceAttenuation;
        } else if (cosTheta <= cosOuter) {
            // Outside outer cone
            return 0.0;
        } else {
            // Between inner and outer cones: smooth falloff
            double factor = (cosTheta - cosOuter) / (cosCutoff - cosOuter);
            factor = Math.pow(factor, getFalloffExponent());
            return baseIntensity * factor * distanceAttenuation;
        }
    }
}
