import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

class DataProcessor {

    public static Map<String, Object> processEcommerceData(String categoriesJson, String cartJson) {
        // Extract category names
        List<String> categoryNames = extractStringValues(categoriesJson, "name");
        int categoryCount = categoryNames.size();

        // Determine if any category name is empty
        boolean hasEmptyCategories = categoryNames.stream().anyMatch(name -> name.isEmpty());

        // Compute lengths of each category name
        List<Integer> categoryNameLengths = new ArrayList<>();
        for (String name : categoryNames) {
            categoryNameLengths.add(name.length());
        }

        // Extract product quantities
        List<Integer> quantities = extractIntValues(cartJson, "quantity");
        int totalCartItems = quantities.stream().mapToInt(Integer::intValue).sum();

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", categoryCount);
        result.put("totalCartItems", totalCartItems);
        result.put("categoryNames", categoryNames);
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", categoryNameLengths);

        return result;
    }

    // Helper method to extract all string values for a given key from a JSON string
    private static List<String> extractStringValues(String json, String key) {
        List<String> values = new ArrayList<>();
        String regex = "\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]*)\"";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(json);
        while (matcher.find()) {
            values.add(matcher.group(1));
        }
        return values;
    }

    // Helper method to extract all integer values for a given key from a JSON string
