import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

class DataProcessor {

    public static Map<String, Object> processEcommerceData(String categoriesJson, String cartJson) {
        // Default result for invalid or missing data
        Map<String, Object> defaultResult = new HashMap<>();
        defaultResult.put("categoryCount", 0);
        defaultResult.put("totalCartItems", 0);
        defaultResult.put("categoryNames", new ArrayList<String>());
        defaultResult.put("hasEmptyCategories", false);
        defaultResult.put("categoryNameLengths", new ArrayList<Integer>());

        // Treat null or empty strings as no data
        if (categoriesJson == null || cartJson == null ||
            categoriesJson.trim().isEmpty() || cartJson.trim().isEmpty()) {
            return defaultResult;
        }

        // Parse categories JSON
        Object catObj;
        try {
            catObj = new JsonParser(categoriesJson).parse();
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Invalid categories JSON format", e);
        }

        // Parse cart JSON
        Object cartObj;
        try {
            cartObj = new JsonParser(cartJson).parse();
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Invalid cart JSON format", e);
        }

        // Extract category names
        List<String> categoryNames = new ArrayList<>();
        if (catObj instanceof List) {
            List<?> catList = (List<?>) catObj;
            for (Object item : catList) {
                if (item instanceof Map) {
                    Map<?, ?> map = (Map<?, ?>) item;
                    Object nameObj = map.get("name");
                    String name = (nameObj instanceof String) ? (String) nameObj : "";
                    if (name == null) name = "";
                    categoryNames.add(name);
                } else {
                    // Non-object items are ignored
                }
            }
        }

        int categoryCount = categoryNames.size();
        boolean hasEmptyCategories = categoryNames.isEmpty() ||
                categoryNames.stream().anyMatch(name -> name.isEmpty());

        List<Integer> categoryNameLengths = new ArrayList<>();
        for (String name : categoryNames) {
            categoryNameLengths.add(name.length());
        }

        // Extract product quantities
        int totalCartItems = 0;
        if (cartObj instanceof List) {
            List<?> cartList = (List<?>) cartObj;
            for (Object item : cartList) {
                if (item instanceof Map) {
                    Map<?, ?> map = (Map<?, ?>) item;
                    Object qtyObj = map.get("quantity");
                    int qty = 0;
                    if (qtyObj instanceof Number) {
                        qty = ((Number) qtyObj).intValue();
                    } else if (qtyObj == null) {
                        qty = 0;
                    } else if (qtyObj instanceof String) {
                        try {
                            qty = Integer.parseInt((String) qtyObj);
                        } catch (NumberFormatException e) {
                            qty = 0;
                        }
                    }
                    totalCartItems += qty;
                } else {
                    // Non-object items are ignored
                }
            }
        }

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", categoryCount);
        result.put("totalCartItems", totalCartItems);
        result.put("categoryNames", categoryNames);
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", categoryNameLengths);

        return result;
    }

    // Simple JSON parser that throws IllegalArgumentException on invalid format
    private static class JsonParser {
        private final String json;
        private int pos;

        JsonParser(String json) {
            this.json = json;
            this.pos = 0;
        }

        Object parse() {
            skipWhitespace();
            Object value = parseValue();
            skipWhitespace();
            if (pos != json.length()) {
                throw new IllegalArgumentException("Unexpected trailing characters");
            }
            return value;
        }

        private void skipWhitespace() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) {
                pos++;
            }
        }

        private Object parseValue() {
            skipWhitespace();
            if (pos >= json.length()) {
                throw new IllegalArgumentException("Unexpected end of input");
            }
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f' || c == 'n') return parseLiteral();
            if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
            throw new IllegalArgumentException("Unexpected character at position " + pos);
        }

        private Map<String, Object> parseObject() {
            Map<String, Object> map = new HashMap<>();
            expectChar('{');
            skipWhitespace();
            if (peekChar() == '}') {
                pos++;
                return map;
            }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                expectChar(':');
                skipWhitespace();
                Object value = parseValue();
                map.put(key, value);
                skipWhitespace();
                char c = nextChar();
                if (c == '}') break;
                if (c != ',') {
                    throw new IllegalArgumentException("Expected ',' or '}' at position " + pos);
                }
            }
            return map;
        }

        private List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            expectChar('[');
            skipWhitespace();
            if (peekChar() == ']') {
                pos++;
                return list;
            }
            while (true) {
                skipWhitespace();
                Object value = parseValue();
                list.add(value);
                skipWhitespace();
                char c = nextChar();
                if (c == ']') break;
                if (c != ',') {
                    throw new IllegalArgumentException("Expected ',' or ']' at position " + pos);
                }
            }
            return list;
        }

        private String parseString() {
            expectChar('"');
            StringBuilder sb = new StringBuilder();
            while (pos < json.length()) {
                char c = json.charAt(pos++);
                if (c == '\\') {
                    if (pos >= json.length()) {
                        throw new IllegalArgumentException("Unexpected end of input in string escape");
                    }
                    char esc = json.charAt(pos++);
                    switch (esc) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (pos + 4 > json.length()) {
                                throw new IllegalArgumentException("Invalid unicode escape");
                            }
                            String hex = json.substring(pos, pos + 4);
                            try {
                                int code = Integer.parseInt(hex, 16);
                                sb.append((char) code);
                            } catch (NumberFormatException e) {
                                throw new IllegalArgumentException("Invalid unicode escape");
                            }
                            pos += 4;
                            break;
                        default:
                            throw new IllegalArgumentException("Invalid escape character");
                    }
                } else if (c == '"') {
                    return sb.toString();
                } else {
                    sb.append(c);
                }
            }
            throw new IllegalArgumentException("Unterminated string");
        }

        private Object parseNumber() {
            int start = pos;
            if (json.charAt(pos) == '-') pos++;
            while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
            if (pos < json.length() && json.charAt(pos) == '.') {
                pos++;
                while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
            }
            if (pos < json.length() && (json.charAt(pos) == 'e' || json.charAt(pos) == 'E')) {
                pos++;
                if (pos < json.length() && (json.charAt(pos) == '+' || json.charAt(pos) == '-')) pos++;
                while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
            }
            String numStr = json.substring(start, pos);
            try {
                if (numStr.contains(".") || numStr.contains("e") || numStr.contains("E")) {
                    return Double.parseDouble(numStr);
                } else {
                    return Long.parseLong(numStr);
                }
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException("Invalid number format");
            }
        }

        private Object parseLiteral() {
            if (json.startsWith("true", pos)) {
                pos += 4;
                return Boolean.TRUE;
            } else if (json.startsWith("false", pos)) {
                pos += 5;
                return Boolean.FALSE;
            } else if (json.startsWith("null", pos)) {
                pos += 4;
                return null;
            } else {
                throw new IllegalArgumentException("Invalid literal at position " + pos);
            }
