    public static Map<String, Object> processEcommerceData(String categoriesJson, String cartJson) {
        // Default result for invalid or missing data
        Map<String, Object> defaultResult = new HashMap<>();
        defaultResult.put("categoryCount", 0);
        defaultResult.put("totalCartItems", 0);
        defaultResult.put("categoryNames", new ArrayList<String>());
        defaultResult.put("hasEmptyCategories", false);
        defaultResult.put("categoryNameLengths", new ArrayList<Integer>());

        // Treat null or empty strings as no data
        if (categoriesJson == null || cartJson == null ||
            categoriesJson.trim().isEmpty() || cartJson.trim().isEmpty()) {
            return defaultResult;
        }

        // Parse categories JSON
        Object catObj;
        try {
            catObj = new JsonParser(categoriesJson).parse();
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Invalid categories JSON format", e);
        }

        // Parse cart JSON
        Object cartObj;
        try {
            cartObj = new JsonParser(cartJson).parse();
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Invalid cart JSON format", e);
        }

        // Extract category names
        List<String> categoryNames = new ArrayList<>();
        if (catObj instanceof List) {
            List<?> catList = (List<?>) catObj;
            for (Object item : catList) {
                if (item instanceof Map) {
                    Map<?, ?> map = (Map<?, ?>) item;
                    Object nameObj = map.get("name");
                    String name = (nameObj instanceof String) ? (String) nameObj : "";
                    if (name == null) name = "";
                    categoryNames.add(name);
                } else {
                    // Non-object items are ignored
                }
            }
        }

        int categoryCount = categoryNames.size();
        boolean hasEmptyCategories = categoryNames.isEmpty() ||
                categoryNames.stream().anyMatch(name -> name.isEmpty());

        List<Integer> categoryNameLengths = new ArrayList<>();
        for (String name : categoryNames) {
            categoryNameLengths.add(name.length());
        }

        // Extract product quantities
        int totalCartItems = 0;
        if (cartObj instanceof List) {
            List<?> cartList = (List<?>) cartObj;
            for (Object item : cartList) {
