            handler.accept(messageData);
            return true;
        } else {
            if (errorLogger != null) {
                errorLogger.accept(messageType, "No handler registered for message type: " + messageType);
            }
            return false;
        }
    }

    // Example usage
    public static void main(String[] args) {
        BiConsumer<String, String> logger = (type, msg) -> System.err.println("ERROR [" + type + "]: " + msg);

        WebSocketMessageHandler handler = new WebSocketMessageHandler(logger);

        handler.addMessageHandler("chat", data -> System.out.println("Chat: " + data));
        handler.addMessageHandler("notification", data -> System.out.println("Notif: " + data));

        Map<String, Object> chatData = new HashMap<>();
        chatData.put("sender", "Alice");
        chatData.put("content", "Hello!");
        handler.processMessage("chat", chatData);

        Map<String, Object> notifData = new HashMap<>();
        notifData.put("title", "Update");
        notifData.put("body", "Profile updated.");
        handler.processMessage("notification", notifData);

        // Invalid cases
        handler.processMessage(null, chatData);          // null type
        handler.processMessage("chat", null);            // null data
        handler.processMessage("", chatData);            // empty type
        handler.processMessage("unknown", chatData);     // unknown type
    }
}

