import java.util.*;
import java.util.function.*;

class WebSocketMessageHandler {
    private final Map<String, Consumer<Map<String, Object>>> messageHandlers;
    private final BiConsumer<String, String> errorLogger;
    private final RateLimiter rateLimiter;

    public WebSocketMessageHandler(BiConsumer<String, String> errorLogger) {
        this.messageHandlers = new HashMap<>();
        this.errorLogger = errorLogger;
        this.rateLimiter = new RateLimiter(100, 1000); // 100 messages per 1000 ms
    }

    /**
     * Registers a handler for a specific message type.
     *
     * @param messageType the type of the message
     * @param handler     the consumer that will process the message data
     */
    public void addMessageHandler(String messageType, Consumer<Map<String, Object>> handler) {
        messageHandlers.put(messageType, handler);
    }

    /**
     * Processes an incoming message by looking up the handler for its type.
     * Validates that the message type is not null/empty and that the data map is not null.
     * Enforces a rate limit of 100 messages per second.
     *
     * @param messageType the type of the message
     * @param messageData the payload of the message
     * @return true if a handler was found and executed, false otherwise
     */
    public boolean processMessage(String messageType, Map<String, Object> messageData) {
        // Rate limiting check
        if (!rateLimiter.allow()) {
            if (errorLogger != null) {
                errorLogger.accept(messageType, "Rate limit exceeded");
            }
            return false;
        }

        // Validation
        if (messageType == null || messageType.isEmpty() || messageData == null) {
            if (errorLogger != null) {
                errorLogger.accept(messageType, "Invalid message: type or data is null/empty");
            }
            return false;
        }

        Consumer<Map<String, Object>> handler = messageHandlers.get(messageType);
        if (handler != null) {
            handler.accept(messageData);
            return true;
        } else {
            if (errorLogger != null) {
                errorLogger.accept(messageType, "No handler registered for message type: " + messageType);
            }
            return false;
        }
    }

    /**
     * Inner class implementing a simple sliding‑window rate limiter.
     */
    private static class RateLimiter {
        private final int maxRequests;
        private final long windowMillis;
        private final Deque<Long> timestamps = new ArrayDeque<>();

        RateLimiter(int maxRequests, long windowMillis) {
            this.maxRequests = maxRequests;
            this.windowMillis = windowMillis;
        }

        /**
         * Determines whether a new request is allowed under the rate limit.
         *
         * @return true if the request is allowed, false otherwise
         */
        synchronized boolean allow() {
            long now = System.currentTimeMillis();
            // Remove timestamps older than the window
            while (!timestamps.isEmpty() && now - timestamps.peekFirst() >= windowMillis) {
                timestamps.pollFirst();
            }
            if (timestamps.size() < maxRequests) {
                timestamps.addLast(now);
                return true;
            }
            return false;
        }
    }

    // Example usage
    public static void main(String[] args) throws InterruptedException {
        BiConsumer<String, String> logger = (type, msg) ->
                System.err.println("ERROR [" + (type == null ? "null" : type) + "]: " + msg);

        WebSocketMessageHandler handler = new WebSocketMessageHandler(logger);

        handler.addMessageHandler("chat", data -> System.out.println("Chat: " + data));
        handler.addMessageHandler("notification", data -> System.out.println("Notif: " + data));

        // Send 105 messages in quick succession to trigger the rate limiter
        for (int i = 0; i < 105; i++) {
            Map<String, Object> data = new HashMap<>();
            data.put("msg", "Message " + i);
            boolean ok = handler.processMessage("chat", data);
            if (!ok) {
                System.out.println("Message " + i + " was rejected (rate limit or validation).");
            }
        }

        // Wait a second to reset the rate limiter
        Thread.sleep(1100);

        // Send a valid message after the window has reset
        Map<String, Object> finalData = new HashMap<>();
        finalData.put("msg", "Final message");
        handler.processMessage("chat", finalData);
    }
}

