import java.util.HashMap;
import java.util.function.Consumer;

class AsyncResponseHandler {
    // Stores callbacks keyed by response type
    private final HashMap<String, Consumer<Object>> callbacks = new HashMap<>();

    // Global error handler for all callbacks
    private Consumer<Exception> errorHandler = e -> {
        // Default no‑op handler; can be overridden by the user
    };

    /**
     * Registers a callback for a specific response type.
     *
     * @param responseType the type of response the callback handles
     * @param callback     the callback to invoke when a response of the given type is received
     * @throws IllegalArgumentException if either argument is {@code null}
     */
    public void registerCallback(String responseType, Consumer<Object> callback) {
        if (responseType == null) {
            throw new IllegalArgumentException("responseType must not be null");
        }
        if (callback == null) {
            throw new IllegalArgumentException("callback must not be null");
        }
        callbacks.put(responseType, callback);
    }

    /**
     * Sets a global error handler that will be invoked whenever a callback throws an exception
     * or when no callback is registered for a response type.
     *
     * @param errorHandler the error handler to use
     * @throws IllegalArgumentException if {@code errorHandler} is {@code null}
     */
    public void setErrorHandler(Consumer<Exception> errorHandler) {
        if (errorHandler == null) {
            throw new IllegalArgumentException("errorHandler must not be null");
        }
        this.errorHandler = errorHandler;
    }

    /**
     * Invokes the callback registered for the given response type, passing the response object.
     * If no callback is registered, the global error handler is invoked with an {@link IllegalStateException}.
     *
     * @param responseType the type of the response
     * @param response     the response object to pass to the callback
     */
    public void handleResponse(String responseType, Object response) {
        Consumer<Object> callback = callbacks.get(responseType);
        if (callback != null) {
            try {
                callback.accept(response);
            } catch (Exception e) {
                errorHandler.accept(e);
            }
        } else {
            errorHandler.accept(new IllegalStateException(
                "No callback registered for response type: " + responseType));
        }
    }
}

