import java.util.Map;
import java.util.Set;
import java.util.HashMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * A thread‑safe key‑value store that tracks access statistics,
 * type distribution, and supports bulk operations.
 *
 * @param <K> the type of keys
 * @param <V> the type of values
 */
public class KeyValueStore<K, V> {

    /* --------------------- Internal Data Structures --------------------- */

    private final ConcurrentHashMap<K, V> store = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, AtomicInteger> accessCounts = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, Long> lastAccessTimes = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<Class<?>, AtomicInteger> typeCounts = new ConcurrentHashMap<>();

    /* --------------------- Basic Operations --------------------- */

    /**
     * Stores the given key‑value pair. If the key already exists, the old value
     * is replaced and the type counts are updated accordingly.
     *
     * @param key   the key to store; must not be null
     * @param value the value associated with the key; may be null
     * @throws IllegalArgumentException if key is null
     */
    public void put(K key, V value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        V oldValue = store.put(key, value);

        // Update type counts for the old value
        if (oldValue != null) {
            decrementTypeCount(oldValue.getClass());
        }

        // Update type counts for the new value
        if (value != null) {
            incrementTypeCount(value.getClass());
        }
    }

    /**
     * Inserts multiple entries into the store. Each entry is processed
     * using {@link #put(Object, Object)} so that type counts are updated.
     *
     * @param entries the map of entries to insert; must not contain null keys
     * @throws IllegalArgumentException if entries is null or contains a null key
     */
    public void putAll(Map<? extends K, ? extends V> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries map cannot be null");
        }
        for (Map.Entry<? extends K, ? extends V> e : entries.entrySet()) {
            put(e.getKey(), e.getValue());
        }
    }

    /**
     * Retrieves the value associated with the given key, increments the access
     * count, and records the last access time.
     *
     * @param key the key whose value is to be retrieved; must not be null
     * @return the value associated with the key, or null if the key is not present
     * @throws IllegalArgumentException if key is null
     */
    public V get(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        // Increment access count atomically
        accessCounts.computeIfAbsent(key, k -> new AtomicInteger(0)).incrementAndGet();

        // Record last access time
        lastAccessTimes.put(key, System.currentTimeMillis());

        return store.get(key);
    }

    /* --------------------- Access Statistics --------------------- */

    /**
     * Returns how many times the specified key has been accessed via {@link #get}.
     *
     * @param key the key whose access count is requested; must not be null
     * @return the number of times the key has been accessed, or 0 if never accessed
     * @throws IllegalArgumentException if key is null
     */
    public int getAccessCount(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        AtomicInteger counter = accessCounts.get(key);
        return counter == null ? 0 : counter.get();
    }

    /**
     * Returns the last access time (in milliseconds since epoch) for the specified key.
     *
     * @param key the key whose last access time is requested; must not be null
     * @return the last access time in milliseconds, or 0 if the key has never been accessed
     * @throws IllegalArgumentException if key is null
     */
    public long getLastAccessTime(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        Long time = lastAccessTimes.get(key);
        return time == null ? 0L : time;
    }

    /* --------------------- Type Tracking --------------------- */

    /**
     * Increments the count for the specified type.
     *
     * @param clazz the class of the value being added
     */
    private void incrementTypeCount(Class<?> clazz) {
        typeCounts.computeIfAbsent(clazz, c -> new AtomicInteger(0)).incrementAndGet();
    }

    /**
     * Decrements the count for the specified type. If the count reaches zero,
     * the entry is removed from the map.
     *
     * @param clazz the class of the value being removed
     */
    private void decrementTypeCount(Class<?> clazz) {
        typeCounts.computeIfPresent(clazz, (c, counter) -> {
            int newVal = counter.decrementAndGet();
            return newVal > 0 ? counter : null; // remove if zero
        });
    }

    /**
     * Returns the number of values currently stored in the map that are of the
     * specified type.
     *
     * @param type the class whose count is requested; must not be null
     * @return the number of stored values of the given type, or 0 if none
     * @throws IllegalArgumentException if type is null
     */
    public int getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
        AtomicInteger counter = typeCounts.get(type);
        return counter == null ? 0 : counter.get();
    }

    /**
     * Returns all keys whose associated values are of the specified type.
     *
     * @param type the class to match; must not be null
     * @return a set of keys whose values are of the given type
     * @throws IllegalArgumentException if type is null
     */
    public Set<K> findKeysByType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
        Set<K> result = ConcurrentHashMap.newKeySet();
        for (Map.Entry<K, V> entry : store.entrySet()) {
            V value = entry.getValue();
            if (value != null && value.getClass() == type) {
                result.add(entry.getKey());
            }
        }
        return result;
    }

    /* --------------------- Statistics --------------------- */

    /**
     * Computes a snapshot of various statistics about the store.
     *
     * @return a {@link Statistics} object containing the computed data
     */
    public Statistics computeStatistics() {
        int totalEntries = store.size();

        // Find key with maximum access count
        K keyWithMaxAccess = null;
        int maxAccess = -1;
        for (Map.Entry<K, AtomicInteger> e : accessCounts.entrySet()) {
            int count = e.getValue().get();
            if (count > maxAccess) {
                maxAccess = count;
                keyWithMaxAccess = e.getKey();
            }
        }

        // Copy type distribution
        Map<Class<?>, Integer> typeDistribution = new HashMap<>(typeCounts.size());
        for (Map.Entry<Class<?>, AtomicInteger> e : typeCounts.entrySet()) {
            typeDistribution.put(e.getKey(), e.getValue().get());
        }

        // Rough estimate of memory usage (bytes)
        long estimatedMemoryUsage = totalEntries * 64L; // 64 bytes per entry is a rough guess

        return new Statistics(totalEntries, keyWithMaxAccess, typeDistribution, estimatedMemoryUsage);
    }

    /**
     * Clears all data from the store, including access statistics and type counts.
     */
    public void clear() {
        store.clear();
        accessCounts.clear();
        lastAccessTimes.clear();
        typeCounts.clear();
    }

    /* --------------------- Statistics Data Class --------------------- */

    /**
     * Immutable snapshot of store statistics.
     */
    public static class Statistics {
        private final int totalEntries;
        private final Object keyWithMaxAccess;
        private final Map<Class<?>, Integer> typeDistribution;
        private final long estimatedMemoryUsage;

        public Statistics(int totalEntries, Object keyWithMaxAccess,
                          Map<Class<?>, Integer> typeDistribution,
                          long estimatedMemoryUsage) {
            this.totalEntries = totalEntries;
            this.keyWithMaxAccess = keyWithMaxAccess;
            this.typeDistribution = new HashMap<>(typeDistribution);
            this.estimatedMemoryUsage = estimatedMemoryUsage;
        }

        public int getTotalEntries() {
            return totalEntries;
        }

        public Object getKeyWithMaxAccess() {
            return keyWithMaxAccess;
        }

        public Map<Class<?>, Integer> getTypeDistribution() {
            return new HashMap<>(typeDistribution);
        }

        public long getEstimatedMemoryUsage() {
            return estimatedMemoryUsage;
        }

        @Override
        public String toString() {
            return "Statistics{" +
                    "totalEntries=" + totalEntries +
                    ", keyWithMaxAccess=" + keyWithMaxAccess +
                    ", typeDistribution=" + typeDistribution +
                    ", estimatedMemoryUsage=" + estimatedMemoryUsage +
                    '}';
        }
    }

    /* --------------------- Demo --------------------- */

    public static void main(String[] args) throws InterruptedException {
        KeyValueStore<String, Object> kv = new KeyValueStore<>();

        // Basic put/get
        kv.put("intKey", 42);
        kv.put("strKey", "hello");
        kv.put("doubleKey", 3.14);

        // Bulk insert
        Map<String, Object> bulk = new HashMap<>();
        bulk.put("boolKey", true);
        bulk.put("nullKey", null);
        kv.putAll(bulk);

        // Access statistics
        kv.get("intKey");
        kv.get("intKey");
        kv.get("strKey");

        // Type distribution
        System.out.println("int count: " + kv.getTypeCount(Integer.class));   // 1
        System.out.println("String count: " + kv.getTypeCount(String.class)); // 1
        System.out.println("Double count: " + kv.getTypeCount(Double.class)); // 1
        System.out.println("Boolean count: " + kv.getTypeCount(Boolean.class)); // 1

        // Find keys by type
        System.out.println("Keys with Integer values: " + kv.findKeysByType(Integer.class));

        // Compute statistics
        System.out.println(kv.computeStatistics());

        // Clear store
        kv.clear();
        System.out.println("After clear, total entries: " + kv.computeStatistics().getTotalEntries());
    }
}

