    // Optional getters for internal structures
    public Set<String> getRequiredOptions() {
        return Collections.unmodifiableSet(requiredOptions);
    }

    public Map<String, Object> getDefaultOptions() {
        return Collections.unmodifiableMap(defaultOptions);
    }

    public Map<String, List<String>> getOptionDependencies() {
        return Collections.unmodifiableMap(optionDependencies);
    }
}

