import java.util.*;

public class EnhancedOptions {
    private final Map<String, Object> options = new HashMap<>();
    private final Set<String> requiredOptions = new HashSet<>();
    private final Map<String, Object> defaultOptions = new HashMap<>();
    private final Map<String, List<String>> optionDependencies = new HashMap<>();

    public EnhancedOptions() {
        // Default options
        defaultOptions.put("header_footer", true);
        defaultOptions.put("compact", false);
        defaultOptions.put("safe", 0);

        // Required options
        requiredOptions.add("backend");
        requiredOptions.add("doctype");

        // Option dependencies
        optionDependencies.put("template_engine", Collections.singletonList("template_dirs"));
    }

    /**
     * Stores an option value. Rejects null values.
     *
     * @param key   the option name
     * @param value the option value
     * @throws IllegalArgumentException if value is null
     */
    public void setOption(String key, Object value) {
        if (value == null) {
            throw new IllegalArgumentException("Option value for '" + key + "' cannot be null");
        }
        options.put(key, value);
    }

    /**
     * Retrieves the value of an option. If the option has not been explicitly set,
     * the default value is returned. If no default exists, null is returned.
     *
     * @param key the option name
     * @return the option value or default value, or null if none
     */
    public Object getOption(String key) {
        if (options.containsKey(key)) {
            return options.get(key);
        }
        return defaultOptions.getOrDefault(key, null);
    }

    // Optional getters for internal structures
    public Set<String> getRequiredOptions() {
        return Collections.unmodifiableSet(requiredOptions);
    }

    public Map<String, Object> getDefaultOptions() {
        return Collections.unmodifiableMap(defaultOptions);
    }

    public Map<String, List<String>> getOptionDependencies() {
        return Collections.unmodifiableMap(optionDependencies);
