import java.util.HashMap;
import java.util.Map;

public class AuthenticationService {
    private final Map<String, String> credentials = new HashMap<>();

    /**
     * Registers a new user with the given username and password.
     *
     * @param username the username to register
     * @param password the password for the user
     * @return true if registration succeeded, false if the username already exists or inputs are invalid
     */
    public boolean registerUser(String username, String password) {
        if (username == null || password == null) {
            return false;
        }
        if (credentials.containsKey(username)) {
            return false; // user already exists
        }
        credentials.put(username, password);
        return true;
    }

    /**
     * Authenticates a user with the given username and password.
     *
     * @param username the username to authenticate
     * @param password the password to verify
     * @return true if authentication succeeds, false otherwise
     */
    public boolean authenticate(String username, String password) {
        if (username == null || password == null) {
            return false;
        }
        String storedPassword = credentials.get(username);
        return password.equals(storedPassword);
    }

    // Optional main method for quick demonstration
    public static void main(String[] args) {
        AuthenticationService auth = new AuthenticationService();

        System.out.println(auth.registerUser("alice", "password123")); // true
        System.out.println(auth.registerUser("alice", "newpass"));     // false
        System.out.println(auth.authenticate("alice", "password123")); // true
        System.out.println(auth.authenticate("alice", "wrong"));       // false
        System.out.println(auth.authenticate("bob", "any"));           // false
    }
}

