/**
 * A simple authentication service that supports user registration,
 * authentication, and default user initialization.
 */
public class AuthenticationService {
    /** Stores usernames and their corresponding passwords. */
    private final Map<String, String> userCredentials;

    /**
     * Constructs the service and initializes default users.
     */
    public AuthenticationService() {
        this.userCredentials = new HashMap<>();
        initializeDefaultUsers();
    }

    /**
     * Registers a new user after validating the input and password.
     *
     * @param username the username to register
     * @param password the password for the user
     * @return RegistrationResult indicating success or failure
     */
    public RegistrationResult registerUser(String username, String password) {
        // Reject null or empty inputs
        if (isNullOrEmpty(username)) {
            return new RegistrationResult(false, "Username cannot be null or empty.");
        }
        if (isNullOrEmpty(password)) {
            return new RegistrationResult(false, "Password cannot be null or empty.");
        }

        // Validate password length
        if (!PasswordValidator.validate(password)) {
            return new RegistrationResult(false,
                    "Password must be at least 8 characters long.");
        }

        // Check for existing user
        if (userCredentials.containsKey(username)) {
            return new RegistrationResult(false, "User already exists.");
        }

        userCredentials.put(username, password);
        return new RegistrationResult(true, "User registered successfully.");
    }

    /**
     * Authenticates a user against stored credentials.
     *
     * @param username the username to authenticate
     * @param password the password to verify
     * @return AuthenticationResult indicating success or failure
     */
    public AuthenticationResult authenticate(String username, String password) {
        // Reject null or empty inputs
        if (isNullOrEmpty(username)) {
            return new AuthenticationResult(false, "Username cannot be null or empty.");
        }
        if (isNullOrEmpty(password)) {
            return new AuthenticationResult(false, "Password cannot be null or empty.");
        }

        String storedPassword = userCredentials.get(username);
        if (storedPassword == null) {
            return new AuthenticationResult(false, "User does not exist.");
        }

        if (storedPassword.equals(password)) {
            return new AuthenticationResult(true, "Authentication successful.");
        } else {
            return new AuthenticationResult(false, "Invalid credentials.");
        }
    }

    /**
     * Initializes the system with two default users:
     * - Om with password "imagine"
     * - Chinmay with password "IMAGINE"
     */
    private void initializeDefaultUsers() {
        // Default users are added only if they don't already exist
        if (!userCredentials.containsKey("Om")) {
            userCredentials.put("Om", "imagine");
        }
        if (!userCredentials.containsKey("Chinmay")) {
            userCredentials.put("Chinmay", "IMAGINE");
        }
    }

    /**
     * Utility method to check for null or empty strings.
     *
     * @param s the string to check
     * @return true if s is null or empty, false otherwise
     */
    private static boolean isNullOrEmpty(String s) {
        return s == null || s.isEmpty();
    }

    /**
     * Nested class responsible for password validation.
     */
    private static class PasswordValidator {
        /**
         * Checks if the password meets the minimum length requirement.
         *
         * @param password the password to validate
         * @return true if password length >= 8, false otherwise
         */
        public static boolean validate(String password) {
            return password != null && password.length() >= 8;
        }
    }

    // Demo main method
    public static void main(String[] args) {
        AuthenticationService authService = new AuthenticationService();

        // Test default users
        AuthenticationResult authDefault1 = authService.authenticate("Om", "imagine");
        System.out.println(authDefault1.isSuccess() + " - " + authDefault1.getMessage()); // true

        AuthenticationResult authDefault2 = authService.authenticate("Chinmay", "IMAGINE");
        System.out.println(authDefault2.isSuccess() + " - " + authDefault2.getMessage()); // true

        // Attempt to register with short password
        RegistrationResult regShort = authService.registerUser("Alice", "short");
        System.out.println(regShort.isSuccess() + " - " + regShort.getMessage()); // false

        // Successful registration
        RegistrationResult regSuccess = authService.registerUser("Alice", "strongPass");
        System.out.println(regSuccess.isSuccess() + " - " + regSuccess.getMessage()); // true

        // Duplicate registration
        RegistrationResult regDuplicate = authService.registerUser("Alice", "anotherPass");
        System.out.println(regDuplicate.isSuccess() + " - " + regDuplicate.getMessage()); // false

        // Authentication tests
        AuthenticationResult authAlice = authService.authenticate("Alice", "strongPass");
        System.out.println(authAlice.isSuccess() + " - " + authAlice.getMessage()); // true

        AuthenticationResult authWrong = authService.authenticate("Alice", "wrongPass");
        System.out.println(authWrong.isSuccess() + " - " + authWrong.getMessage()); // false

        AuthenticationResult authNonExistent = authService.authenticate("Bob", "any");
        System.out.println(authNonExistent.isSuccess() + " - " + authNonExistent.getMessage()); // false

        // Null or empty input tests
        RegistrationResult regNull = authService.registerUser(null, "validPass");
        System.out.println(regNull.isSuccess() + " - " + regNull.getMessage()); // false

        AuthenticationResult authEmpty = authService.authenticate("", "somePass");
        System.out.println(authEmpty.isSuccess() + " - " + authEmpty.getMessage()); // false
    }
}

