            shipPositions.remove(coordinate);
            if (shipPositions.isEmpty()) {
                gameOver = true;
                winner = "Opponent";
                notifyStateChange(EventType.SUNK, coordinate);
                notifyStateChange(EventType.GAME_OVER, winner);
                return HitResult.SUNK;
            }
            notifyStateChange(EventType.HIT, coordinate);
            return HitResult.HIT;
        }

        notifyStateChange(EventType.MISS, coordinate);
