    /**
     * Returns the in-order successor of the given node.
     * Handles both cases:
     * 1. Node has a right child – successor is the leftmost node in the right subtree.
     * 2. Node has no right child – successor is the first ancestor for which the node
     *    lies in the left subtree.
     *
     * @param node the node whose successor is to be found
     * @return the in-order successor node, or null if none exists
     * @throws IllegalArgumentException if the input node is null
     */
    public static BinaryTreeNode findNextNode(BinaryTreeNode node) {
        if (node == null) {
            throw new IllegalArgumentException("Input node cannot be null");
