        // Case 1: Node has a right child – go to the leftmost node in that subtree.
        if (node.right != null) {
            BinaryTreeNode current = node.right;
            while (current.left != null) {
                current = current.left;
            }
            return current;
        }

        // Case 2: No right child – climb up using parent pointers.
        BinaryTreeNode current = node;
        while (current.parent != null) {
            if (current.parent.left == current) {
                return current.parent; // Found the first ancestor where node is in left subtree.
            }
            current = current.parent;
        }

        // No successor found (node is the rightmost node in the tree).
        return null;
    }
}

