import java.util.*;

public class AdditionChainFinder {

    /**
     * Finds the shortest addition chain that starts with 1 and ends with the given target.
     * Each element after the first is the sum of two (not necessarily distinct) previous elements.
     *
     * @param target the final value of the addition chain (must be >= 1)
     * @return a list of integers representing the shortest addition chain
     */
    public List<Integer> findShortestAdditionChain(int target) {
        if (target <= 1) {
            return Collections.singletonList(1);
        }

        // Iterative deepening: try increasing chain lengths until a solution is found
        for (int maxDepth = 1; ; maxDepth++) {
            int[] chain = new int[maxDepth + 1];
            chain[0] = 1;
            if (dfs(chain, 0, maxDepth, target)) {
                List<Integer> result = new ArrayList<>(maxDepth + 1);
                for (int i = 0; i <= maxDepth; i++) {
                    result.add(chain[i]);
                }
                return result;
            }
        }
    }

    /**
     * Depth‑first search with pruning to find a chain of a given maximum depth.
     *
     * @param chain    the current chain (array of length maxDepth+1)
     * @param depth    the current depth (index of the last filled element)
     * @param maxDepth the maximum allowed depth
     * @param target   the desired final value
     * @return true if a valid chain was found, false otherwise
     */
    private boolean dfs(int[] chain, int depth, int maxDepth, int target) {
        if (depth == maxDepth) {
            return chain[depth] == target;
        }

        int currentMax = chain[depth];
        int remaining = maxDepth - depth;

        // Prune if even doubling the current maximum each step cannot reach the target
        if ((long) currentMax << remaining < target) {
            return false;
        }

        // Generate all possible next values (sum of two previous numbers)
        // Use a set to avoid duplicate candidates
        Set<Integer> candidates = new HashSet<>();
        for (int i = depth; i >= 0; i--) {
            for (int j = i; j >= 0; j--) {
                int sum = chain[i] + chain[j];
                if (sum > currentMax && sum <= target) {
                    candidates.add(sum);
                }
            }
        }

        // Try larger sums first to reach the target faster
        List<Integer> sorted = new ArrayList<>(candidates);
        sorted.sort(Collections.reverseOrder());

        for (int val : sorted) {
            chain[depth + 1] = val;
            if (dfs(chain, depth + 1, maxDepth, target)) {
                return true;
            }
        }
        return false;
    }
}

