import java.util.*;

class GraphAnalyzer {
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        int n = graph.length;
        int[] distances = new int[n];
        int[] prev = new int[n];
        boolean[] visited = new boolean[n];

        Arrays.fill(distances, Integer.MAX_VALUE);
        Arrays.fill(prev, -1);
        distances[source] = 0;

        PriorityQueue<Vertex> pq = new PriorityQueue<>();
        pq.add(new Vertex(source, 0));

        while (!pq.isEmpty()) {
            Vertex v = pq.poll();
            if (visited[v.index]) continue;
            visited[v.index] = true;

            for (int j = 0; j < n; j++) {
                int weight = graph[v.index][j];
                if (weight > 0 && !visited[j]) {
                    int newDist = distances[v.index] + weight;
                    if (newDist < distances[j]) {
                        distances[j] = newDist;
                        prev[j] = v.index;
                        pq.add(new Vertex(j, newDist));
                    }
                }
            }
        }

        // Reconstruct paths
        List<List<Integer>> paths = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            if (i == source) {
                paths.add(Collections.singletonList(source));
            } else {
                paths.add(buildPath(prev, source, i));
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("distances", distances);
        result.put("paths", paths);
        return result;
    }

    private static List<Integer> buildPath(int[] prev, int source, int target) {
        if (target == source) {
            return Collections.singletonList(source);
        }
        List<Integer> path = new ArrayList<>();
        int current = target;
        while (current != -1 && current != source) {
            path.add(current);
            current = prev[current];
        }
        if (current == -1) {
            return Collections.emptyList(); // unreachable
        }
        path.add(source);
        Collections.reverse(path);
        return path;
    }

    private static class Vertex implements Comparable<Vertex> {
        int index;
        int distance;

        Vertex(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }

        @Override
        public int compareTo(Vertex other) {
            return Integer.compare(this.distance, other.distance);
        }
    }
}

