public class StringProcessor {

    /**
     * Processes the input string by removing all non-letter characters and
     * converting the result to title case (first letter uppercase, rest lowercase).
     *
     * @param input the string to process
     * @return the processed string, or an empty string if input is null, empty,
     *         or contains no letters
     */
    public static String processString(String input) {
        if (input == null || input.isEmpty()) {
            return "";
        }

        // Build a string containing only letters
        StringBuilder lettersOnly = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            if (Character.isLetter(ch)) {
                lettersOnly.append(ch);
            }
        }

        if (lettersOnly.length() == 0) {
            return "";
        }

        // Convert to title case: first letter uppercase, rest lowercase
        char[] chars = lettersOnly.toString().toCharArray();
        chars[0] = Character.toUpperCase(chars[0]);
        for (int i = 1; i < chars.length; i++) {
            chars[i] = Character.toLowerCase(chars[i]);
        }

        return new String(chars);
    }
}

