public class StringProcessor {

    /**
     * Processes the input string by:
     * 1. Removing all non-letter characters.
     * 2. Converting the result to title case (first letter uppercase, rest lowercase).
     * 3. If the resulting string has more than 5 characters, reversing it.
     * 4. Applying length‑based markers:
     *    • Empty string → "Empty"
     *    • Length < 3 → prepend "Short_"
     *    • Length 3–5 → append "_Medium"
     *    • Length ≥ 6 → prepend "Long_" and append "_Processed"
     *
     * @param input the string to process
     * @return the processed string with markers applied
     */
    public static String processString(String input) {
        if (input == null || input.isEmpty()) {
            return "Empty";
        }

        // Keep only letters
        StringBuilder lettersOnly = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            if (Character.isLetter(ch)) {
                lettersOnly.append(ch);
            }
        }

        if (lettersOnly.length() == 0) {
            return "Empty";
        }

        // Convert to title case
        char[] chars = lettersOnly.toString().toCharArray();
        chars[0] = Character.toUpperCase(chars[0]);
        for (int i = 1; i < chars.length; i++) {
            chars[i] = Character.toLowerCase(chars[i]);
        }

        String result = new String(chars);

        // Reverse if length > 5
        if (result.length() > 5) {
            result = new StringBuilder(result).reverse().toString();
        }

        // Apply length-based markers
        int len = result.length();
        if (len == 0) {
            return "Empty";
        } else if (len < 3) {
            return "Short_" + result;
        } else if (len <= 5) {
            return result + "_Medium";
        } else { // len >= 6
            return "Long_" + result + "_Processed";
        }
    }
}

