public class NumberComparator {

    public static String analyzeNumbers(List<Integer> numbers) {
        // Check for null or empty list
        if (numbers == null || numbers.isEmpty()) {
            return "Error: No numbers provided.";
        }

        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        Set<Integer> seen = new HashSet<>();

        for (Integer num : numbers) {
            // Null element check
            if (num == null) {
                throw new NullPointerException("List must not contain null elements");
            }

            // Duplicate check
            if (!seen.add(num)) {
                return "Error: All input numbers must be unique. Found duplicates.";
            }

            // Update min and max
            if (num < min) {
                min = num;
            }
            if (num > max) {
                max = num;
            }
        }

        // Range calculation (not used in the returned string)
        int range = max - min;

        return "Analysis results:";
    }
}

