import java.util.*;

public class ChatMessageProcessor {
    // Map to store messages for each user
    private final Map<String, List<String>> userMessages = new HashMap<>();

    // List to maintain active users
    private final List<String> activeUsers = new ArrayList<>();

    /**
     * Adds a user to the active users list.
     *
     * @param username the username of the user joining
     * @return an empty list of notifications (no other users to notify)
     */
    public List<String> userJoins(String username) {
        // Avoid duplicate entries
        if (!activeUsers.contains(username)) {
            activeUsers.add(username);
            // Initialize message list for the new user
            userMessages.putIfAbsent(username, new ArrayList<>());
        }
        // No notifications to send when the user joins
        return Collections.emptyList();
    }

    // Optional helper methods (not required by the problem statement)

    /**
     * Sends a message from one user to another.
     *
     * @param from   sender's username
     * @param to     recipient's username
     * @param message the message content
     */
    public void sendMessage(String from, String to, String message) {
        if (!activeUsers.contains(to)) {
            throw new IllegalArgumentException("Recipient not active: " + to);
        }
        userMessages.computeIfAbsent(to, k -> new ArrayList<>()).add(from + ": " + message);
    }

    /**
     * Retrieves all messages for a user.
     *
     * @param username the username
     * @return list of messages
     */
    public List<String> getMessages(String username) {
        return userMessages.getOrDefault(username, Collections.emptyList());
    }

    /**
     * Returns the list of currently active users.
     *
     * @return list of active usernames
     */
    public List<String> getActiveUsers() {
        return new ArrayList<>(activeUsers);
    }
}

