        // For the right subtree, all values must be > node.value
        Integer newUpper = node.value; // left subtree upper bound
        Integer newLower = (node.value == Integer.MAX_VALUE) ? null : node.value + 1; // right subtree lower bound

        return isValidBST(node.left, lower, newUpper) &&
               isValidBST(node.right, newLower, upper);
