import java.awt.*;
import java.util.List;
import java.util.Map;
import java.util.HashMap;

class EnhancedLayoutManager {
    private List<Component> components;
    private List<LayoutConstraint> constraints;
    private boolean respectAspectRatio;
    private double aspectRatio;

    public EnhancedLayoutManager(List<Component> components, List<LayoutConstraint> constraints,
                                 boolean respectAspectRatio, double aspectRatio) {
        this.components = components;
        this.constraints = constraints;
        this.respectAspectRatio = respectAspectRatio;
        this.aspectRatio = aspectRatio;
    }

    public Map<Component, Rectangle> calculateLayout(int containerWidth, int containerHeight) {
        Map<Component, Rectangle> result = new HashMap<>();
        int totalFixedWidth = 0;
        int totalFixedHeight = 0;

        int count = Math.min(components.size(), constraints.size());

        // 1. Place fixed-size components and sum their dimensions
        for (int i = 0; i < count; i++) {
            Component comp = components.get(i);
            LayoutConstraint lc = constraints.get(i);

            if (lc.isFixedSize()) {
                Rectangle rect = new Rectangle(lc.getX(), lc.getY(), lc.getWidth(), lc.getHeight());
                result.put(comp, rect);
                totalFixedWidth += lc.getWidth();
                totalFixedHeight += lc.getHeight();
            }
        }

        int remainingWidth = containerWidth - totalFixedWidth;
        int remainingHeight = containerHeight - totalFixedHeight;

        // 2. Compute total weight of flexible components
        double totalWeight = 0.0;
        for (int i = 0; i < count; i++) {
            LayoutConstraint lc = constraints.get(i);
            if (!lc.isFixedSize()) {
                totalWeight += lc.getWeight();
            }
        }

        // 3. Distribute remaining space among flexible components
        if (totalWeight > 0) {
            for (int i = 0; i < count; i++) {
                Component comp = components.get(i);
                LayoutConstraint lc = constraints.get(i);

                if (!lc.isFixedSize()) {
                    // Proportional allocation
                    int width = (int) Math.round(remainingWidth * lc.getWeight() / totalWeight);
                    int height = (int) Math.round(remainingHeight * lc.getWeight() / totalWeight);

                    // Adjust to respect aspect ratio if required
                    if (respectAspectRatio && width > 0 && height > 0) {
                        double currentRatio = (double) width / height;
                        if (currentRatio > aspectRatio) {
                            // Width too large, reduce it
                            width = (int) Math.round(height * aspectRatio);
                        } else {
                            // Height too large, reduce it
                            height = (int) Math.round(width / aspectRatio);
                        }
                        // Ensure we do not exceed the allocated size
                        if (width > remainingWidth) width = remainingWidth;
                        if (height > remainingHeight) height = remainingHeight;
                    }

                    Rectangle rect = new Rectangle(lc.getX(), lc.getY(), width, height);
                    result.put(comp, rect);
                }
            }
        }

        return result;
    }

    public static class LayoutConstraint {
        private int x;
        private int y;
        private int width;
        private int height;
        private double weight;
        private boolean fixedSize;

        public LayoutConstraint(int x, int y, int width, int height, double weight, boolean fixedSize) {
            this.x = x;
            this.y = y;
            this.width = width;
            this.height = height;
            this.weight = weight;
