public class PianoOctaveManager {
    private int currentOctave;
    private final int minOctave;
    private final int maxOctave;

    /**
     * Creates a PianoOctaveManager with the specified initial octave and bounds.
     *
     * @param initialOctave the octave to start with
     * @param minOctave     the minimum allowed octave
     * @param maxOctave     the maximum allowed octave
     * @throws IllegalArgumentException if minOctave is greater than maxOctave
     */
    public PianoOctaveManager(int initialOctave, int minOctave, int maxOctave) {
        if (minOctave > maxOctave) {
            throw new IllegalArgumentException("minOctave cannot be greater than maxOctave");
        }
        this.minOctave = minOctave;
        this.maxOctave = maxOctave;
        this.currentOctave = clamp(initialOctave, minOctave, maxOctave);
    }

    /**
     * Returns the current octave.
     *
     * @return the current octave
     */
    public int getCurrentOctave() {
        return currentOctave;
    }

    /**
     * Sets the current octave, clamping it to the allowed range.
     *
     * @param newOctave the octave to set
     */
    public void setCurrentOctave(int newOctave) {
        this.currentOctave = clamp(newOctave, minOctave, maxOctave);
    }

    /**
     * Utility method to clamp a value between a minimum and maximum.
     *
     * @param value the value to clamp
     * @param min   the minimum allowed value
     * @param max   the maximum allowed value
     * @return the clamped value
     */
    private static int clamp(int value, int min, int max) {
        if (value < min) {
            return min;
        }
        if (value > max) {
            return max;
        }
        return value;
    }

    // Optional main method for quick demonstration
    public static void main(String[] args) {
        PianoOctaveManager manager = new PianoOctaveManager(3, 1, 5);
        System.out.println("Initial octave: " + manager.getCurrentOctave()); // 3

        manager.setCurrentOctave(6);
        System.out.println("After setting to 6 (clamped): " + manager.getCurrentOctave()); // 5

        manager.setCurrentOctave(0);
        System.out.println("After setting to 0 (clamped): " + manager.getCurrentOctave()); // 1
    }
}

