            // Existing user authenticated
            status = "authenticated";
        }

        Map<String, Object> result = new HashMap<>();
        result.put("status", status);
        result.put("user", user);
        result.put("provider", provider);
        return result;
    }

    /**
     * Creates a new User instance with the supplied attributes.
     * The user is enabled and assigned the default ROLE_USER role.
     */
    private User registerNewUser(String email,
                                 String provider,
                                 Map<String, Object> userAttributes,
                                 Set<Role> availableRoles) {
        // Username derived from email prefix and provider
        String username = generateUsername(email, provider);

        // Extract name and lastname, defaulting to empty strings
        String name = getStringAttribute(userAttributes, "given_name");
        String lastname = getStringAttribute(userAttributes, "family_name");

        User user = new User(email, username);
        user.setName(name);
        user.setLastname(lastname);
        user.setEnabled(true);

        // Assign default ROLE_USER if present
        Role defaultRole = null;
        for (Role r : availableRoles) {
            if ("ROLE_USER".equals(r.getName())) {
                defaultRole = r;
                break;
            }
        }
        if (defaultRole != null) {
            user.setRoles(new HashSet<>(Collections.singletonList(defaultRole)));
        }

        return user;
    }

    private String generateUsername(String email, String provider) {
        int atIndex = email.indexOf('@');
        String prefix = (atIndex > 0) ? email.substring(0, atIndex) : email;
        return prefix + "_" + provider;
    }

    private String getStringAttribute(Map<String, Object> attrs, String key) {
        Object val = attrs.get(key);
        return (val instanceof String) ? (String) val : "";
    }
