import java.util.*;
import java.util.concurrent.*;

class MessageProducer {
    private final BlockingQueue<String> messageQueue;
    private final List<String> sentMessages;
    private final int maxRetries;
    private final long retryDelayMillis;

    // Custom constructor
    public MessageProducer(BlockingQueue<String> queue, int maxRetries, long retryDelayMillis) {
        this.messageQueue = queue;
        this.sentMessages = new ArrayList<>();
        this.maxRetries = maxRetries;
        this.retryDelayMillis = retryDelayMillis;
    }

    // Default constructor delegating to the custom one
    public MessageProducer() {
        this(new LinkedBlockingQueue<>(), 3, 100);
    }

    public void sendMessages(String prefix, int count) {
        for (int i = 1; i <= count; i++) {
            String message = prefix + " " + i;
            boolean offered = false;
            int attempts = 0;

            while (!offered && attempts <= maxRetries) {
                try {
                    offered = messageQueue.offer(message, 100, TimeUnit.MILLISECONDS);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException("Thread interrupted while offering message", e);
                }

                if (!offered) {
                    attempts++;
                    if (attempts > maxRetries) {
                        break;
                    }
                    try {
                        Thread.sleep(retryDelayMillis);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        throw new RuntimeException("Thread interrupted during retry delay", e);
                    }
                }
            }

            // Record the message regardless of whether it was successfully queued
            sentMessages.add(message);
        }
    }

    public BlockingQueue<String> getMessageQueue() {
        return this.messageQueue;
    }

