import java.util.List;
import java.util.ArrayList;

public class PaginationService {
    /**
     * Paginates the given list of items, optionally filtering them by a case‑insensitive key.
     *
     * @param items       the list of items to paginate
     * @param page        the 1‑based page number
     * @param rowsPerPage the number of rows per page
     * @param key         optional filter key; if null or empty, no filtering is applied
     * @param <T>         the type of items in the list
     * @return a PaginatedResult containing the sliced items and the total count after filtering
     */
    public static <T> PaginatedResult<T> paginate(List<T> items, int page, int rowsPerPage, String key) {
        if (items == null) {
            throw new IllegalArgumentException("Items list cannot be null");
        }
        if (page < 1 || rowsPerPage < 1) {
            throw new IllegalArgumentException("Page and rowsPerPage must be positive");
        }

        List<T> filtered = (key != null && !key.isEmpty()) ? filterItems(items, key) : items;
        int total = filtered.size();

        int startIndex = (page - 1) * rowsPerPage;
        if (startIndex >= total) {
            return new PaginatedResult<>(new ArrayList<>(), total);
        }

        int endIndex = Math.min(startIndex + rowsPerPage, total);
        List<T> pageItems = filtered.subList(startIndex, endIndex);
        return new PaginatedResult<>(pageItems, total);
    }

    /**
     * Filters the list of items by checking if the string representation of each item
     * contains the given key, case‑insensitively.
     *
     * @param items the list of items to filter
     * @param key   the filter key
     * @param <T>   the type of items in the list
     * @return a new list containing only items that match the filter
     */
    private static <T> List<T> filterItems(List<T> items, String key) {
        List<T> result = new ArrayList<>();
        String lowerKey = key.toLowerCase();
        for (T item : items) {
            if (item != null && item.toString().toLowerCase().contains(lowerKey)) {
                result.add(item);
            }
        }
        return result;
    }

    public static class PaginatedResult<T> {
        private final List<T> items;
        private final int total;

        public PaginatedResult(List<T> items, int total) {
            this.items = items;
            this.total = total;
        }

        public List<T> getItems() {
            return items;
        }

        public int getTotal() {
            return total;
        }
    }
}
</code>
