import java.util.HashMap;
import java.util.Map;

class PostCreator {
    public Map<String, Object> createPost(
            String title, String description, String price,
            String country, String stateProvince, String city,
            String contactEmail, Object imageData) {

        // Collect validation errors
        Map<String, String> errors = new HashMap<>();

        // Title validation
        if (title == null || title.trim().isEmpty()) {
            errors.put("title", "Title cannot be empty");
        } else if (title.length() > 100) {
            errors.put("title", "Title must be at most 100 characters");
        }

        // Description validation
        if (description == null || description.trim().isEmpty()) {
            errors.put("description", "Description cannot be empty");
        }

        // Price validation (optional field)
        if (price != null && !price.trim().isEmpty()) {
            try {
                double value = Double.parseDouble(price.trim());
                if (value < 0) {
                    errors.put("price", "Price must be a non‑negative number");
                }
            } catch (NumberFormatException e) {
                errors.put("price", "Price must be a valid number");
            }
        }

        // If any validation errors exist, return them
        if (!errors.isEmpty()) {
            Map<String, Object> errorResponse = new HashMap<>();
            errorResponse.put("success", false);
            errorResponse.put("errors", errors);
            return errorResponse;
        }

        // Build successful response
        Map<String, Object> postData = new HashMap<>();
        postData.put("title", title);
        postData.put("description", description);
        postData.put("price", price);
