class DateUtils {
    private static final String[] DAYS_OF_WEEK = {
        "SUNDAY", "MONDAY", "TUESDAY", "WEDNESDAY",
        "THURSDAY", "FRIDAY", "SATURDAY"
    };

    /**
     * Determines whether the specified year is a leap year according to the
     * Gregorian calendar rules: a year is a leap year if it is divisible by 4,
     * except for years divisible by 100 unless they are also divisible by 400.
     *
     * @param year the year to test
     * @return true if the year is a leap year, false otherwise
     */
    private static boolean isLeapYear(int year) {
        if (year % 4 != 0) {
            return false;
        }
        if (year % 100 != 0) {
            return true;
        }
        return year % 400 == 0;
    }

    /**
     * Returns the number of days in the specified month of the specified year.
     * February has 29 days in a leap year and 28 days otherwise.
     *
     * @param month the month (1‑12)
     * @param year  the year
     * @return the number of days in the month
     */
    private static int getDaysInMonth(int month, int year) {
        switch (month) {
            case 1:  // January
            case 3:  // March
            case 5:  // May
            case 7:  // July
            case 8:  // August
            case 10: // October
            case 12: // December
                return 31;
            case 4:  // April
            case 6:  // June
            case 9:  // September
            case 11: // November
                return 30;
            case 2:  // February
                return isLeapYear(year) ? 29 : 28;
            default:
                // This case should never be reached because month is validated elsewhere
                return 0;
        }
    }

    /**
     * Validates a complete date. The year must be greater than or equal to 1,
     * the month must be between 1 and 12 inclusive, and the day must be within
     * the valid range for the given month and year.
     *
     * @param day   the day of the month
     * @param month the month of the year
     * @param year  the year
     * @return true if the date is valid, false otherwise
     */
    private static boolean isValidDate(int day, int month, int year) {
        if (year < 1) {
            return false;
        }
        if (month < 1 || month > 12) {
            return false;
        }
        int daysInMonth = getDaysInMonth(month, year);
        return day >= 1 && day <= daysInMonth;
    }

    /**
     * Analyzes the given date and returns an empty map. If the date is not
     * valid, an IllegalArgumentException with the message "Invalid date" is thrown.
     *
     * @param day   the day of the month
