import java.util.*;

public class DataMatcher {

    /**
     * Performs an enhanced match between two datasets based on the specified strategy and key indices.
     *
     * @param dataset1     the first list of string arrays
     * @param dataset2     the second list of string arrays
     * @param matchStrategy the matching strategy (currently only 1 = exact match is supported)
     * @param keyIndices   the indices of the fields to use for matching
     * @return a map containing three entries:
     *         "matched"   -> list of concatenated matched records,
     *         "unmatched1" -> list of records from dataset1 that had no match,
     *         "unmatched2" -> list of records from dataset2 that had no match
     */
    public Map<String, List<String[]>> enhancedMatch(
            List<String[]> dataset1,
            List<String[]> dataset2,
            int matchStrategy,
            int[] keyIndices) {

        Map<String, List<String[]>> result = new HashMap<>();
        List<String[]> matched = new ArrayList<>();
        List<String[]> unmatched1 = new ArrayList<>();
        List<String[]> unmatched2 = new ArrayList<>();

        // Only exact matching is implemented for now
        if (matchStrategy != 1) {
            unmatched1.addAll(dataset1);
            unmatched2.addAll(dataset2);
            result.put("matched", matched);
            result.put("unmatched1", unmatched1);
            result.put("unmatched2", unmatched2);
            return result;
        }

        // Build a lookup map for dataset2 based on the key
        Map<String, List<String[]>> map2 = new HashMap<>();
        for (String[] record : dataset2) {
            String key = buildKey(record, keyIndices);
            map2.computeIfAbsent(key, k -> new ArrayList<>()).add(record);
        }

        // Iterate over dataset1 and try to find matches in dataset2
        for (String[] record1 : dataset1) {
            String key = buildKey(record1, keyIndices);
            List<String[]> candidates = map2.get(key);

            if (candidates != null && !candidates.isEmpty()) {
                // Take the first matching record from dataset2
                String[] record2 = candidates.remove(0);

                // Concatenate the two records
                String[] combined = new String[record1.length + record2.length];
                System.arraycopy(record1, 0, combined, 0, record1.length);
                System.arraycopy(record2, 0, combined, record1.length, record2.length);
                matched.add(combined);

                // Remove the key from the map if no more candidates remain
                if (candidates.isEmpty()) {
                    map2.remove(key);
                }
            } else {
                unmatched1.add(record1);
            }
        }

        // Remaining records in map2 are unmatched from dataset2
        for (List<String[]> remaining : map2.values()) {
            unmatched2.addAll(remaining);
        }

        result.put("matched", matched);
        result.put("unmatched1", unmatched1);
        result.put("unmatched2", unmatched2);
        return result;
    }

    /**
     * Builds a composite key string from the specified indices of a record.
     * Trims each field and uses a separator to avoid ambiguity.
     *
     * @param record     the record array
     * @param keyIndices the indices to include in the key
     * @return a string representing the composite key
     */
    private static String buildKey(String[] record, int[] keyIndices) {
        StringBuilder sb = new StringBuilder();
        for (int idx : keyIndices) {
            if (idx >= 0 && idx < record.length) {
                String value = record[idx];
                sb.append(value == null ? "" : value.trim());
            } else {
                sb.append("");
            }
            sb.append("|"); // separator
        }
        return sb.toString();
    }
}

