public class TreeAnalyzer {

    /**
     * Analyzes the given binary tree and returns a map containing:
     * - "nodeCount": total number of nodes in the tree
     * - "maxDiff": maximum absolute difference between any ancestor and descendant values
     *
     * @param root the root of the binary tree (may be null)
     * @return a map with the analysis results
     */
    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();

        if (root == null) {
            result.put("nodeCount", 0);
            result.put("maxDiff", 0);
            return result;
        }

        int[] maxDiff = {0};
        int nodeCount = countNodesAndDiff(root, root.val, root.val, maxDiff);

        result.put("nodeCount", nodeCount);
        result.put("maxDiff", maxDiff[0]);
        return result;
    }

    /**
     * Recursively counts nodes and updates the maximum ancestor–descendant difference.
     *
     * @param node    current node
     * @param minVal  minimum value seen on the path from the root to this node
     * @param maxVal  maximum value seen on the path from the root to this node
     * @param maxDiff array of size 1 holding the current maximum difference
     * @return number of nodes in the subtree rooted at {@code node}
     */
    private int countNodesAndDiff(TreeNode node, int minVal, int maxVal, int[] maxDiff) {
        if (node == null) {
            return 0;
        }

        // Update min and max values for the current path
        int newMin = Math.min(minVal, node.val);
        int newMax = Math.max(maxVal, node.val);

        // Update maximum difference using the current node and the extremes of its ancestors
        int diffWithMin = Math.abs(node.val - minVal);
        int diffWithMax = Math.abs(node.val - maxVal);
        maxDiff[0] = Math.max(maxDiff[0], Math.max(diffWithMin, diffWithMax));

        // Recurse on children
        int leftCount = countNodesAndDiff(node.left, newMin, newMax, maxDiff);
        int rightCount = countNodesAndDiff(node.right, newMin, newMax, maxDiff);

        return 1 + leftCount + rightCount;
    }

    /**
     * Definition for a binary tree node.
     */
    public static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        public TreeNode(int val) {
            this.val = val;
        }
    }
}

