import java.util.Map;
import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;

public class TreeAnalyzer {

    /**
     * Analyzes the binary tree rooted at {@code root} and returns a map containing:
     * - "nodeCount": total number of nodes in the tree
     * - "maxDiff": maximum absolute difference between any ancestor and descendant values
     * - "minDiff": minimum absolute difference between any ancestor and descendant values
     * - "avgDiff": floor of (sum of all ancestor differences / total node count)
     *
     * @param root the root of the binary tree (may be null)
     * @return a map with the analysis results
     */
    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();

        if (root == null) {
            result.put("nodeCount", 0);
            result.put("maxDiff", 0);
            result.put("minDiff", 0);
            result.put("avgDiff", 0);
            return result;
        }

        // Global accumulators
        long sumDiff = 0;
        int nodeCount = 0;
        int maxDiff = 0;
        int minDiff = Integer.MAX_VALUE;

        // List to keep track of ancestor values
        List<Integer> ancestors = new ArrayList<>();

        // Depth‑first traversal
        java.util.Deque<TreeNode> stack = new java.util.ArrayDeque<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            nodeCount++;

            // Compute differences with all ancestors
            int nodeMinDiff = Integer.MAX_VALUE;
            int nodeMaxDiff = 0;
            long nodeSumDiff = 0;

            for (int ancVal : ancestors) {
                int diff = Math.abs(node.val - ancVal);
                nodeSumDiff += diff;
                if (diff < nodeMinDiff) nodeMinDiff = diff;
                if (diff > nodeMaxDiff) nodeMaxDiff = diff;
            }

            sumDiff += nodeSumDiff;
            if (nodeMinDiff < minDiff) minDiff = nodeMinDiff;
            if (nodeMaxDiff > maxDiff) maxDiff = nodeMaxDiff;

            // Push current node onto ancestors list
            ancestors.add(node.val);

            // Push children onto stack (postorder not required)
            if (node.right != null) stack.push(node.right);
            if (node.left != null) stack.push(node.left);

            // After processing children, remove current node from ancestors
            // We need to ensure removal after children are processed.
            // Since we use a stack, we can process removal after children are popped.
            // To handle this, we use a separate stack to track nodes to remove.
            // However, simpler approach: use recursion.
        }

        // The above iterative approach does not correctly remove ancestors after children.
        // To keep the solution simple and correct, we revert to a recursive DFS.

