import java.util.*;

class MessageSystemSimulator {
    private final Map<String, ServiceNode> nodes = new HashMap<>();
    private final Map<String, String> addressMap = new HashMap<>();

    /**
     * Registers a service with a unique address.
     *
     * @param serviceType the type/name of the service
     * @param handler     the handler that will process incoming messages
     * @return the generated unique address for the service
     */
    public String registerService(String serviceType, MessageHandler handler) {
        // If the service type is already registered, return its address
        if (addressMap.containsKey(serviceType)) {
            return addressMap.get(serviceType);
        }

        // Generate a unique address
        String address = UUID.randomUUID().toString();

        // Create and store the service node
        ServiceNode node = new ServiceNode(address, handler);
        nodes.put(address, node);
        addressMap.put(serviceType, address);

        return address;
    }

    /**
     * Sends a message from one service to another.
     *
     * @param fromAddress   the address of the sender
     * @param toServiceType the type of the recipient service
     * @param messageContent the content of the message
     * @return true if the message was delivered and processed successfully,
     *         false otherwise
     */
    public boolean sendMessage(String fromAddress, String toServiceType, String messageContent) {
        // Validate sender
        if (!nodes.containsKey(fromAddress)) {
            return false; // unknown sender
        }

        // Resolve recipient address
        String toAddress = addressMap.get(toServiceType);
        if (toAddress == null) {
            return false; // unknown recipient type
        }

        // Build the message
        Message msg = new Message(fromAddress, toAddress, messageContent);

        // Deliver to the recipient's handler
        ServiceNode recipientNode = nodes.get(toAddress);
        if (recipientNode == null) {
            return false; // should not happen, but guard anyway
        }

        return recipientNode.handler.process(msg);
    }

    // --------------------------------------------------------------------
    // Supporting classes and interfaces
    // --------------------------------------------------------------------

    static class ServiceNode {
        private final String address;
        private final MessageHandler handler;

        public ServiceNode(String address, MessageHandler handler) {
            this.address = address;
            this.handler = handler;
        }
    }

    interface MessageHandler {
        /**
         * Processes an incoming message.
         *
         * @param message the message to process
         * @return true if the message was processed successfully
         */
        boolean process(Message message);
    }

    static class Message {
        private final String from;
        private final String to;
        private final String content;

        public Message(String from, String to, String content) {
            this.from = from;
            this.to = to;
            this.content = content;
        }

        public String getFrom() {
            return from;
        }

        public String getTo() {
            return to;
        }

        public String getContent() {
            return content;
        }
    }
}

