    /**
     * Returns a string representation of the tree's level-order traversal.
     * Format: [val1,val2,...,valn] where null represents missing nodes.
     * Trailing nulls are omitted.
     *
     * @param root the root of the binary tree
     * @return the level-order traversal string
     */
    public String levelOrder(TreeNode root) {
        if (root == null) {
            return "[]";
        }

        Queue<TreeNode> queue = new LinkedList<>();
        List<String> values = new ArrayList<>();

        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();

            if (node != null) {
                values.add(String.valueOf(node.val));
                queue.offer(node.left);
                queue.offer(node.right);
            } else {
                values.add("null");
            }
        }

        // Remove trailing "null" values
        int i = values.size() - 1;
        while (i >= 0 && values.get(i).equals("null")) {
            i--;
        }

        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int j = 0; j <= i; j++) {
            if (j > 0) sb.append(',');
            sb.append(values.get(j));
        }
        sb.append(']');

        return sb.toString();
