import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class PaginationProcessor<T> {

    private final List<T> dataset;
    private final int defaultPageSize;

    /**
     * Constructs a PaginationProcessor with the given dataset and default page size.
     *
     * @param dataset          the list of items to paginate; if null, an empty list is used
     * @param defaultPageSize  the default number of items per page; if <= 0, defaults to 10
     */
    public PaginationProcessor(List<T> dataset, int defaultPageSize) {
        this.dataset = dataset != null ? dataset : Collections.emptyList();
        this.defaultPageSize = defaultPageSize > 0 ? defaultPageSize : 10;
    }

    /**
     * Returns a paginated result for the specified page number and items per page.
     *
     * @param pageNumber   the 1‑based page number to retrieve; must be >= 1
     * @param itemsPerPage the number of items per page; if null, the default page size is used;
     *                     if not null, must be >= 1
     * @return a Result object containing the page data and metadata
     * @throws IllegalArgumentException if pageNumber < 1 or itemsPerPage != null && itemsPerPage < 1
     */
    public Result<T> getPaginatedData(int pageNumber, Integer itemsPerPage) {
        if (pageNumber < 1) {
            throw new IllegalArgumentException("Page number must be at least 1");
        }
        if (itemsPerPage != null && itemsPerPage < 1) {
            throw new IllegalArgumentException("Items per page must be at least 1");
        }

        int effectiveItemsPerPage = itemsPerPage != null ? itemsPerPage : defaultPageSize;

        // Handle empty dataset explicitly
        if (dataset.isEmpty()) {
            return new Result<>(Collections.emptyList(), pageNumber, effectiveItemsPerPage, 0, 0);
        }

        int totalItems = dataset.size();
        int totalPages = (int) Math.ceil((double) totalItems / effectiveItemsPerPage);
        if (totalPages == 0) {
            totalPages = 1; // Ensure at least one page exists when dataset is non‑empty
        }

        int currentPage = pageNumber;
        if (currentPage > totalPages) {
            currentPage = totalPages; // Return last page if requested page exceeds total pages
        }

        int startIndex = (currentPage - 1) * effectiveItemsPerPage;
        int endIndex = Math.min(startIndex + effectiveItemsPerPage, totalItems);
        List<T> pageData = startIndex < endIndex
                ? dataset.subList(startIndex, endIndex)
                : Collections.emptyList();

        return new Result<>(pageData, currentPage, effectiveItemsPerPage, totalPages, totalItems);
    }

    /**
     * Result object that holds the paginated data and metadata.
     */
    public static class Result<T> {
        private final List<T> pageData;
        private final int currentPage;
        private final int itemsPerPage;
        private final int totalPages;
        private final int totalItems;

        public Result(List<T> pageData, int currentPage, int itemsPerPage, int totalPages, int totalItems) {
            this.pageData = pageData;
            this.currentPage = currentPage;
            this.itemsPerPage = itemsPerPage;
            this.totalPages = totalPages;
            this.totalItems = totalItems;
        }

        public List<T> getPageData() {
            return pageData;
        }

        public int getCurrentPage() {
            return currentPage;
        }

        public int getItemsPerPage() {
            return itemsPerPage;
        }

        public int getTotalPages() {
            return totalPages;
        }

        public int getTotalItems() {
            return totalItems;
        }
    }

    // Example usage
    public static void main(String[] args) {
        List<Integer> data = IntStream.rangeClosed(1, 25).boxed().collect(Collectors.toList());
        PaginationProcessor<Integer> processor = new PaginationProcessor<>(data, 10);

        // Retrieve page 2 with 5 items per page
        Result<Integer> result = processor.getPaginatedData(2, 5);

        System.out.println("Current Page: " + result.getCurrentPage());
        System.out.println("Items Per Page: " + result.getItemsPerPage());
        System.out.println("Total Pages: " + result.getTotalPages());
        System.out.println("Total Items: " + result.getTotalItems());
        System.out.println("Page Data: " + result.getPageData());

        // Requesting a page beyond the total pages returns the last page
        Result<Integer> lastPage = processor.getPaginatedData(10, 5);
        System.out.println("\nRequested Page 10 (beyond total pages):");
        System.out.println("Current Page: " + lastPage.getCurrentPage());
        System.out.println("Page Data: " + lastPage.getPageData());

        // Empty dataset example
        PaginationProcessor<String> emptyProcessor = new PaginationProcessor<>(Collections.emptyList(), 5);
        Result<String> emptyResult = emptyProcessor.getPaginatedData(1, 5);
        System.out.println("\nEmpty dataset result:");
        System.out.println("Current Page: " + emptyResult.getCurrentPage());
        System.out.println("Items Per Page: " + emptyResult.getItemsPerPage());
        System.out.println("Total Pages: " + emptyResult.getTotalPages());
        System.out.println("Total Items: " + emptyResult.getTotalItems());
        System.out.println("Page Data: " + emptyResult.getPageData());
