 *     dfa.setFinal(q1);          // q1 is an accepting state
 *
 *     // Define transitions
 *     dfa.addTransition(q0, 'a', q1);
 *     dfa.addTransition(q0, 'b', q0);
 *     dfa.addTransition(q1, 'a', q1);
 *     dfa.addTransition(q1, 'b', q0);
 *
 *     // Test strings
 *     System.out.println(dfa.accepts("a"));      // true
 *     System.out.println(dfa.accepts("b"));      // false
 *     System.out.println(dfa.accepts("ba"));     // true
 *
 *     // Alphabet
 *     System.out.println("Alphabet: " + dfa.getAlphabet()); // [a, b]
 * </pre>
 */
public class DFA {

    /** Represents a state in the DFA. */
    public static class State {
        private final String name;
        private final Map<Character, State> transitions = new HashMap<>();

        public State(String name) {
            this.name = Objects.requireNonNull(name, "State name cannot be null");
        }

        /** Adds a transition for a given input symbol. */
        public void addTransition(char symbol, State target) {
            transitions.put(symbol, Objects.requireNonNull(target, "Target state cannot be null"));
        }

        /** Retrieves the target state for a given input symbol, or null if none. */
        public State getTransition(char symbol) {
            return transitions.get(symbol);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof State)) return false;
            State state = (State) o;
            return name.equals(state.name);
        }

        @Override
        public int hashCode() {
            return Objects.hash(name);
        }

        @Override
        public String toString() {
            return name;
        }
    }

    private final List<State> states = new ArrayList<>();
    private final Set<State> finalStates = new HashSet<>();
    private State initialState = null;
    private final Set<Character> alphabet = new HashSet<>();

    /** Adds a state to the DFA. The first added state becomes the initial state. */
    public void addState(State state) {
        Objects.requireNonNull(state, "State cannot be null");
        if (!states.contains(state)) {
            states.add(state);
            if (initialState == null) {
                initialState = state;
            }
        }
    }

    /** Marks a state as an accepting (final) state. */
    public void setFinal(State state) {
        Objects.requireNonNull(state, "State cannot be null");
        if (!states.contains(state)) {
            throw new IllegalArgumentException("State must be added to the DFA before marking it final");
        }
        finalStates.add(state);
    }

    /** Adds a transition from one state to another on a given input symbol. */
    public void addTransition(State from, char symbol, State to) {
        Objects.requireNonNull(from, "From state cannot be null");
        Objects.requireNonNull(to, "To state cannot be null");
        if (!states.contains(from) || !states.contains(to)) {
            throw new IllegalArgumentException("Both states must be added to the DFA before adding a transition");
        }
        from.addTransition(symbol, to);
        alphabet.add(symbol); // automatically build alphabet
    }

    /** Simulates the DFA on the given input string. Returns true if the string is accepted. */
    public boolean accepts(String input) {
        if (initialState == null) {
            throw new IllegalStateException("DFA has no initial state");
        }
        State current = initialState;
        for (char c : input.toCharArray()) {
            State next = current.getTransition(c);
            if (next == null) {
                return false; // No valid transition
            }
            current = next;
        }
        return finalStates.contains(current);
    }

    /** Returns the initial state of the DFA. */
    public State getInitialState() {
        return initialState;
    }

    /** Returns an unmodifiable view of all states. */
    public List<State> getStates() {
        return Collections.unmodifiableList(states);
    }

    /** Returns an unmodifiable view of all final states. */
    public Set<State> getFinalStates() {
        return Collections.unmodifiableSet(finalStates);
    }

    /** Returns an unmodifiable view of the alphabet (all symbols used in transitions). */
    public Set<Character> getAlphabet() {
        return Collections.unmodifiableSet(alphabet);
    }

    // Example usage
    public static void main(String[] args) {
        // Create states
        State q0 = new State("q0");
        State q1 = new State("q1");

        // Build DFA
        DFA dfa = new DFA();
        dfa.addState(q0);          // first added state becomes the initial state
        dfa.addState(q1);
        dfa.setFinal(q1);          // q1 is an accepting state

        // Define transitions
        dfa.addTransition(q0, 'a', q1);
        dfa.addTransition(q0, 'b', q0);
        dfa.addTransition(q1, 'a', q1);
        dfa.addTransition(q1, 'b', q0);

