import java.util.List;
import java.util.ArrayList;

public class PaginationManager {

    /**
     * Calculates pagination details based on total items, page size, and current page.
     *
     * @param totalItems  the total number of items
     * @param pageSize    the number of items per page (must be > 0)
     * @param currentPage the requested page number (1‑based)
     * @return a PaginationResult containing all pagination information
     */
    public PaginationResult calculatePagination(int totalItems, int pageSize, int currentPage) {
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be greater than 0");
        }

        // Compute total number of pages
        int totalPages = (int) Math.ceil((double) totalItems / pageSize);
        if (totalPages == 0) {
            totalPages = 1; // Ensure at least one page exists
        }

        // Clamp currentPage to valid range
        int current = currentPage;
        if (current < 1) {
            current = 1;
        } else if (current > totalPages) {
            current = totalPages;
        }

        // Determine start and end item indices (1‑based)
        int startItem = (current - 1) * pageSize + 1;
        int endItem = Math.min(startItem + pageSize - 1, totalItems);
        if (totalItems == 0) {
            startItem = 0;
            endItem = 0;
        }

        // Build list of visible page numbers
        List<Integer> visiblePages = new ArrayList<>(totalPages);
        for (int i = 1; i <= totalPages; i++) {
            visiblePages.add(i);
        }

        return new PaginationResult(
                totalItems,
                pageSize,
                current,
                totalPages,
                startItem,
                endItem,
                visiblePages
        );
    }
}

class PaginationResult {
    public final int totalItems;
    public final int pageSize;
    public final int currentPage;
    public final int totalPages;
    public final int startItem;
    public final int endItem;
    public final List<Integer> visiblePages;

    public PaginationResult(int totalItems, int pageSize, int currentPage, int totalPages,
                            int startItem, int endItem, List<Integer> visiblePages) {
        this.totalItems = totalItems;
        this.pageSize = pageSize;
        this.currentPage = currentPage;
        this.totalPages = totalPages;
        this.startItem = startItem;
        this.endItem = endItem;
        this.visiblePages = visiblePages;
    }
}

