import java.util.ArrayList;
import java.util.List;

// Observer interface
interface Observer {
    void takeAction(String msg);
}

// Observable subject
class ObservableSubject {
    private final List<Observer> observers = new ArrayList<>();

    public void addObserver(Observer observer) {
        if (observer != null && !observers.contains(observer)) {
            observers.add(observer);
        }
    }

    public void removeObserver(Observer observer) {
        observers.remove(observer);
    }

    public void notifyObservers(String msg) {
        for (Observer observer : observers) {
            observer.takeAction(msg);
        }
    }
}

// Concrete observer implementation
class ConcreteObserver implements Observer {
    private final String name;

    public ConcreteObserver(String name) {
        this.name = name;
    }

    @Override
    public void takeAction(String msg) {
        System.out.println(name + " received: " + msg);
    }
}

// Demo
public class ObserverPatternDemo {
    public static void main(String[] args) {
        ObservableSubject subject = new ObservableSubject();

        Observer obs1 = new ConcreteObserver("Observer1");
        Observer obs2 = new ConcreteObserver("Observer2");

        subject.addObserver(obs1);
        subject.addObserver(obs2);

        subject.notifyObservers("First notification");

        subject.removeObserver(obs1);

        subject.notifyObservers("Second notification");
    }
}

