        Observer obs1 = new ConcreteObserver("Observer1");
        Observer obs2 = new ConcreteObserver("Observer2");

        subject.addObserver(obs1);
        subject.addObserver(obs2);

        subject.setState("First state change");
        subject.setState("Second state change");

        subject.removeObserver(obs1);

        subject.setState("Third state change");
    }
}
