    private static final int DEFAULT_CAPACITY = 16;
    private Object[] heap;
    private int[] vertex1;
    private int[] vertex2;
    private int size;
    private final boolean isMinHeap;

    /* ----------------- Constructors ----------------- */

    /** Default constructor – creates a min‑heap with default capacity. */
    public EnhancedBinaryHeap() {
