        }
        this.isMinHeap = isMinHeap;
        this.heap = new Object[initialCapacity];
        this.vertex1 = new int[initialCapacity];
        this.vertex2 = new int[initialCapacity];
        this.size = 0;
    }

    /** Creates a heap of the specified type with default capacity. */
    public EnhancedBinaryHeap(boolean isMinHeap) {
        this(isMinHeap, DEFAULT_CAPACITY);
    }

    /* ----------------- Public API ----------------- */

    /**
     * Inserts an element into the heap together with its vertex association.
     *
     * @param element the element to insert
     * @param v1      first vertex of the association
     * @param v2      second vertex of the association
     */
    public void insert(T element, int v1, int v2) {
        if (element == null) {
            throw new IllegalArgumentException("Null elements not allowed");
        }
        ensureCapacity();
        heap[size] = element;
        vertex1[size] = v1;
        vertex2[size] = v2;
        siftUp(size);
        size++;
    }

    /** Removes and returns the root element (minimum or maximum). Returns null if heap is empty. */
    @SuppressWarnings("unchecked")
    public T deleteRoot() {
        if (isEmpty()) {
            return null;
        }
        T root = (T) heap[0];
        size--;
        if (size > 0) {
            heap[0] = heap[size];
            vertex1[0] = vertex1[size];
            vertex2[0] = vertex2[size];
            siftDown(0);
        }
        heap[size] = null; // Help GC
        vertex1[size] = 0;
        vertex2[size] = 0;
        return root;
    }

    /** Returns the root element without removing it. Returns null if heap is empty. */
    @SuppressWarnings("unchecked")
    public T peekRoot() {
        if (isEmpty()) {
            return null;
        }
        return (T) heap[0];
    }

    /** Returns the vertex pair of the root element as an int array. Returns null if heap is empty. */
    public int[] peekRootVertices() {
        if (isEmpty()) {
            return null;
        }
        return new int[]{vertex1[0], vertex2[0]};
    }

    /** Returns true if the heap contains no elements. */
    public boolean isEmpty() {
        return size == 0;
    }

    /** Returns the number of elements in the heap. */
    public int size() {
        return size;
    }

    /** Removes all elements from the heap. */
    public void makeEmpty() {
        for (int i = 0; i < size; i++) {
            heap[i] = null;
            vertex1[i] = 0;
            vertex2[i] = 0;
        }
        size = 0;
    }

    /* ----------------- Internal helper methods ----------------- */

    /** Ensures the internal array has enough capacity to store new elements. */
    private void ensureCapacity() {
        if (size >= heap.length) {
            int newCapacity = heap.length * 2;
            Object[] newHeap = new Object[newCapacity];
            int[] newV1 = new int[newCapacity];
            int[] newV2 = new int[newCapacity];
            System.arraycopy(heap, 0, newHeap, 0, heap.length);
            System.arraycopy(vertex1, 0, newV1, 0, vertex1.length);
            System.arraycopy(vertex2, 0, newV2, 0, vertex2.length);
            heap = newHeap;
            vertex1 = newV1;
            vertex2 = newV2;
        }
    }

    /** Compares two elements according to the heap type. */
    @SuppressWarnings("unchecked")
    private int compare(T a, T b) {
        int cmp = a.compareTo(b);
        return isMinHeap ? cmp : -cmp;
    }

    /** Restores the heap property by moving the element at index up. */
    @SuppressWarnings("unchecked")
    private void siftUp(int index) {
        T element = (T) heap[index];
        int v1 = vertex1[index];
        int v2 = vertex2[index];
        while (index > 0) {
            int parentIndex = (index - 1) >>> 1;
            T parent = (T) heap[parentIndex];
            if (compare(element, parent) >= 0) {
                break;
            }
            heap[index] = parent;
            vertex1[index] = vertex1[parentIndex];
            vertex2[index] = vertex2[parentIndex];
            index = parentIndex;
        }
        heap[index] = element;
        vertex1[index] = v1;
        vertex2[index] = v2;
    }

    /** Restores the heap property by moving the element at index down. */
    @SuppressWarnings("unchecked")
    private void siftDown(int index) {
        T element = (T) heap[index];
        int v1 = vertex1[index];
        int v2 = vertex2[index];
        int half = size >>> 1; // Nodes beyond this are leaves
        while (index < half) {
            int leftChild = (index << 1) + 1;
            int rightChild = leftChild + 1;
            int chosenChildIndex = leftChild;
            T chosenChild = (T) heap[leftChild];
            int chosenV1 = vertex1[leftChild];
            int chosenV2 = vertex2[leftChild];

            if (rightChild < size) {
                T right = (T) heap[rightChild];
                if (compare(right, chosenChild) < 0) {
                    chosenChildIndex = rightChild;
                    chosenChild = right;
                    chosenV1 = vertex1[rightChild];
                    chosenV2 = vertex2[rightChild];
                }
            }

            if (compare(element, chosenChild) <= 0) {
                break;
            }

            heap[index] = chosenChild;
            vertex1[index] = chosenV1;
            vertex2[index] = chosenV2;
            index = chosenChildIndex;
        }
        heap[index] = element;
        vertex1[index] = v1;
        vertex2[index] = v2;
    }
