    public EnhancedBinaryHeap() {
        this(true, DEFAULT_CAPACITY);
    }

    /** Creates a heap with the specified type and capacity. */
    public EnhancedBinaryHeap(boolean isMinHeap, int initialCapacity) {
        if (initialCapacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive");
        }
        this.isMinHeap = isMinHeap;
        this.heap = new Object[initialCapacity];
        this.vertex1 = new int[initialCapacity];
        this.vertex2 = new int[initialCapacity];
        this.size = 0;
    }

    /** Creates a heap of the specified type with default capacity. */
    public EnhancedBinaryHeap(boolean isMinHeap) {
        this(isMinHeap, DEFAULT_CAPACITY);
    }

    /**
     * Builds a heap from an existing array of Comparable items.
     * The heap is constructed in O(n) time using the buildHeap method.
     *
     * @param items    the array of items to heapify
     * @param isMinHeap true for a min‑heap, false for a max‑heap
     */
    public EnhancedBinaryHeap(T[] items, boolean isMinHeap) {
        if (items == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        this.isMinHeap = isMinHeap;
        this.size = items.length;
        this.heap = new Object[size];
        this.vertex1 = new int[size];
        this.vertex2 = new int[size];
        for (int i = 0; i < size; i++) {
            heap[i] = items[i];
            vertex1[i] = 0; // no vertex association for this constructor
            vertex2[i] = 0;
        }
        buildHeap();
    }

    /* ----------------- Public API ----------------- */

    /**
     * Inserts an element into the heap together with its vertex association.
     *
     * @param element the element to insert
     * @param v1      first vertex of the association
     * @param v2      second vertex of the association
     */
    public void insert(T element, int v1, int v2) {
        if (element == null) {
            throw new IllegalArgumentException("Null elements not allowed");
        }
        ensureCapacity();
        heap[size] = element;
        vertex1[size] = v1;
        vertex2[size] = v2;
        siftUp(size);
        size++;
    }

    /** Removes and returns the root element (minimum or maximum). */
    @SuppressWarnings("unchecked")
    public T deleteRoot() {
        if (isEmpty()) {
            throw new NoSuchElementException("Heap is empty");
        }
        T root = (T) heap[0];
        size--;
        if (size > 0) {
            heap[0] = heap[size];
            vertex1[0] = vertex1[size];
            vertex2[0] = vertex2[size];
            siftDown(0);
        }
        heap[size] = null; // Help GC
        vertex1[size] = 0;
        vertex2[size] = 0;
        return root;
    }

    /** Returns the root element without removing it. */
    @SuppressWarnings("unchecked")
    public T peekRoot() {
        if (isEmpty()) {
            throw new NoSuchElementException("Heap is empty");
        }
        return (T) heap[0];
    }

    /** Returns the vertex pair of the root element as an int array. */
    public int[] peekRootVertices() {
        if (isEmpty()) {
            throw new NoSuchElementException("Heap is empty");
        }
        return new int[]{vertex1[0], vertex2[0]};
    }

    /** Returns true if the heap contains no elements. */
    public boolean isEmpty() {
        return size == 0;
    }

    /** Returns the number of elements in the heap. */
    public int size() {
        return size;
    }

    /** Removes all elements from the heap. */
    public void makeEmpty() {
        for (int i = 0; i < size; i++) {
            heap[i] = null;
            vertex1[i] = 0;
            vertex2[i] = 0;
        }
        size = 0;
    }

    /**
     * Performs heap sort on the current heap.
     * The heap is destroyed in the process.
     *
     * @return an array containing the elements in sorted order
     */
    @SuppressWarnings("unchecked")
    public T[] heapSort() {
        int originalSize = size;
        T[] sorted = (T[]) new Comparable[originalSize];
        for (int i = 0; i < originalSize; i++) {
            sorted[i] = deleteRoot();
        }
        return sorted;
    }

    /**
     * Validates that the heap property holds for all nodes.
     *
     * @return true if the heap property is satisfied, false otherwise
     */
    public boolean validateHeap() {
        for (int i = 0; i < size; i++) {
            int left = (i << 1) + 1;
            int right = left + 1;
            if (left < size && compare((T) heap[i], (T) heap[left]) > 0) {
                return false;
            }
            if (right < size && compare((T) heap[i], (T) heap[right]) > 0) {
                return false;
            }
        }
        return true;
    }

    /* ----------------- Internal helper methods ----------------- */

    /** Ensures the internal array has enough capacity to store new elements. */
    private void ensureCapacity() {
        if (size >= heap.length) {
            int newCapacity = heap.length * 2;
            Object[] newHeap = new Object[newCapacity];
            int[] newV1 = new int[newCapacity];
            int[] newV2 = new int[newCapacity];
            System.arraycopy(heap, 0, newHeap, 0, heap.length);
            System.arraycopy(vertex1, 0, newV1, 0, vertex1.length);
            System.arraycopy(vertex2, 0, newV2, 0, vertex2.length);
            heap = newHeap;
            vertex1 = newV1;
            vertex2 = newV2;
        }
    }

    /** Builds the heap in O(n) time using the siftDown method. */
    private void buildHeap() {
        for (int i = (size >>> 1) - 1; i >= 0; i--) {
            siftDown(i);
        }
    }

    /** Compares two elements according to the heap type. */
    @SuppressWarnings("unchecked")
    private int compare(T a, T b) {
        int cmp = a.compareTo(b);
        return isMinHeap ? cmp : -cmp;
    }

    /** Restores the heap property by moving the element at index up. */
    @SuppressWarnings("unchecked")
    private void siftUp(int index) {
        T element = (T) heap[index];
        int v1 = vertex1[index];
        int v2 = vertex2[index];
