            }
            heap[index] = parent;
            vertex1[index] = vertex1[parentIndex];
            vertex2[index] = vertex2[parentIndex];
            index = parentIndex;
        }
        heap[index] = element;
        vertex1[index] = v1;
        vertex2[index] = v2;
    }

    /** Restores the heap property by moving the element at index down. */
    @SuppressWarnings("unchecked")
    private void siftDown(int index) {
        T element = (T) heap[index];
        int v1 = vertex1[index];
        int v2 = vertex2[index];
        int half = size >>> 1; // Nodes beyond this are leaves
        while (index < half) {
