        for (User existing : users) {
            if (existing.getUsername().equalsIgnoreCase(user.getUsername())) {
                result.put("success", false);
                result.put("message", "Username already exists.");
                return result;
            }
        }

        // All checks passed; register user
        users.add(user);
        result.put("success", true);
        result.put("message", "User registered successfully.");
        return result;
    }

    public Map<String, Object> loginUser(String username, String password) {
        Map<String, Object> response = new HashMap<>();
        if (username == null || username.trim().isEmpty()
                || password == null || password.trim().isEmpty()) {
            response.put("success", false);
            response.put("message", "Username and password cannot be empty.");
            response.put("attemptsRemaining", 0);
            return response;
        }

        String key = username.toLowerCase();
        User foundUser = null;
        for (User u : users) {
            if (u.getUsername().equalsIgnoreCase(username)) {
                foundUser = u;
                break;
            }
        }

        // If user not found, treat as failed attempt
        if (foundUser == null) {
            int attempts = failedAttempts.getOrDefault(key, 0) + 1;
            failedAttempts.put(key, attempts);
            if (attempts >= 3) {
                lockedAccounts.add(key);
                response.put("success", false);
                response.put("message", "Account locked due to too many failed attempts.");
                response.put("attemptsRemaining", 0);
            } else {
                response.put("success", false);
                response.put("message", "Invalid credentials. Attempts remaining: " + (3 - attempts));
                response.put("attemptsRemaining", 3 - attempts);
            }
            return response;
        }

        // Check if account is locked
        if (lockedAccounts.contains(key)) {
            response.put("success", false);
            response.put("message", "Account is locked.");
            response.put("attemptsRemaining", 0);
            return response;
        }

        // Verify password
        if (foundUser.getPassword().equals(password)) {
            // Successful login: reset attempts
            failedAttempts.remove(key);
            lockedAccounts.remove(key);
            response.put("success", true);
            response.put("message", "Login successful.");
            response.put("user", foundUser);
            return response;
        } else {
            // Failed attempt
            int attempts = failedAttempts.getOrDefault(key, 0) + 1;
            failedAttempts.put(key, attempts);
