import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;

class TimeDifferenceCalculator {
    private static final String DEFAULT_DATETIME_PATTERN = "yyyy-MM-dd HH:mm:ss";

    public static Map<String, Object> calculateDetailedTimeDifference(String earlierTime, String laterTime)
            throws ParseException {
        SimpleDateFormat sdf = new SimpleDateFormat(DEFAULT_DATETIME_PATTERN);
        Date earlierDate = sdf.parse(earlierTime);
        Date laterDate = sdf.parse(laterTime);

        long diffMillis = laterDate.getTime() - earlierDate.getTime();
        boolean negative = diffMillis < 0;
        diffMillis = Math.abs(diffMillis);

        long totalSeconds = diffMillis / 1000;
        long seconds = totalSeconds % 60;

        long totalMinutes = diffMillis / (60 * 1000);
        long minutes = totalMinutes % 60;

        long totalHours = diffMillis / (60 * 60 * 1000);
        long hours = totalHours % 24;

        long totalDays = diffMillis / (24 * 60 * 60 * 1000);
        long days = totalDays % 7;

        long weeks = totalDays / 7;

        Map<String, Object> result = new HashMap<>();
        result.put("seconds", seconds);
        result.put("minutes", minutes);
        result.put("hours", hours);
        result.put("days", days);
        result.put("weeks", weeks);

        StringBuilder humanReadable = new StringBuilder();
        if (negative) {
            humanReadable.append("-");
        }
        humanReadable.append(weeks).append(" weeks, ")
                     .append(days).append(" days, ")
                     .append(hours).append(" hours, ")
                     .append(minutes).append(" minutes, ")
                     .append(seconds).append(" seconds");

        result.put("humanReadable", humanReadable.toString());

        return result;
    }
}

