/**
 * PathFinder.java
 *
 * This class provides a method to compute the number of unique paths
 * from the top-left corner to the bottom-right corner of a rectangular grid.
 * Movement is restricted to only right or down steps.
 *
 * The method returns a PathResult object that contains the total number
 * of unique paths. The implementation uses dynamic programming to
 * efficiently compute the result for grids of any size.
 */

public class PathFinder {

    /**
     * Result object that holds the total number of unique paths.
     */
    public static class PathResult {
        private final long totalPaths;

        public PathResult(long totalPaths) {
            this.totalPaths = totalPaths;
        }

        public long getTotalPaths() {
            return totalPaths;
        }

        @Override
        public String toString() {
            return "Total unique paths: " + totalPaths;
        }
    }

    /**
     * Computes the number of unique paths from the top-left corner to the
     * bottom-right corner of the given grid. Movement is allowed only to the
     * right or down.
     *
     * @param grid a 2D integer array representing the grid (dimensions m x n)
     * @return a PathResult object containing the total number of unique paths
     */
    public PathResult findUniquePathsWithAnalysis(int[][] grid) {
        // Validate input
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathResult(0);
        }

        int m = grid.length;        // number of rows
        int n = grid[0].length;     // number of columns

        // dp[i][j] represents the number of unique paths to reach cell (i, j)
        long[][] dp = new long[m][n];

        // Starting point
        dp[0][0] = 1;

        // Fill first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1];
        }

        // Fill first column (can only come from above)
        for (int i = 1; i < m; i++) {
            dp[i][0] = dp[i - 1][0];
        }

        // Fill the rest of the grid
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
            }
        }

        return new PathResult(dp[m - 1][n - 1]);
    }

    // Example usage (uncomment to test)
    // public static void main(String[] args) {
    //     PathFinder finder = new PathFinder();
    //     int[][] grid = new int[3][3]; // 3x3 grid
    //     PathResult result = finder.findUniquePathsWithAnalysis(grid);
    //     System.out.println(result); // Should print 6
    // }
}

