import java.util.ArrayList;
import java.util.List;

/**
 * PathFinder computes the number of unique paths from the top-left corner
 * to the bottom-right corner of a rectangular grid, where movement is
 * restricted to right or down steps. It also provides analysis of the
 * paths such as maximum/minimum path length and a sample path.
 */
public class PathFinder {

    /**
     * Inner class that holds detailed analysis of the paths.
     */
    public static class PathAnalysis {
        public final long totalPaths;
        public final int maxPathLength;
        public final int minPathLength;
        public final List<String> samplePath;

        public PathAnalysis(long totalPaths, int maxPathLength, int minPathLength,
                            List<String> samplePath) {
            this.totalPaths = totalPaths;
            this.maxPathLength = maxPathLength;
            this.minPathLength = minPathLength;
            this.samplePath = new ArrayList<>(samplePath);
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            sb.append("Total Paths: ").append(totalPaths).append('\n');
            sb.append("Max Path Length: ").append(maxPathLength).append('\n');
            sb.append("Min Path Length: ").append(minPathLength).append('\n');
            sb.append("Sample Path: ").append(samplePath);
            return sb.toString();
        }
    }

    /**
     * Computes the unique path analysis for the given grid.
     *
     * @param grid a 2D integer array representing the grid (dimensions m x n)
     * @return a PathAnalysis object containing total paths, path lengths,
     *         and a sample path
     */
    public PathAnalysis findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
        }

        int m = grid.length;        // number of rows
        int n = grid[0].length;     // number of columns

        // DP table for counting paths
        long[][] dp = new long[m][n];
        dp[0][0] = 1;

        // First row
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1];
        }

        // First column
        for (int i = 1; i < m; i++) {
            dp[i][0] = dp[i - 1][0];
        }

        // Remaining cells
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
            }
        }

        long totalPaths = dp[m - 1][n - 1];
        int pathLength = (m - 1) + (n - 1); // all paths have same length

        // Build a sample path: all rights followed by all downs
        List<String> samplePath = new ArrayList<>(pathLength);
        for (int i = 0; i < n - 1; i++) {
            samplePath.add("Right");
        }
        for (int i = 0; i < m - 1; i++) {
            samplePath.add("Down");
        }

        return new PathAnalysis(totalPaths, pathLength, pathLength, samplePath);
    }

    // Example usage (uncomment to test)
    // public static void main(String[] args) {
