public class EnhancedTrie {

    /** Root node of the Trie (does not hold a character). */
    private final TrieNode root;

    public EnhancedTrie() {
        root = new TrieNode('\0');
    }

    /**
     * Adds a word to the Trie.
     *
     * @param item the word to insert
     * @throws IllegalArgumentException if the word contains non‑lowercase letters
     */
    public void add(String item) {
        if (item == null) {
            throw new IllegalArgumentException("Word cannot be null");
        }
        TrieNode current = root;
        for (char ch : item.toCharArray()) {
            if (ch < 'a' || ch > 'z') {
                throw new IllegalArgumentException("Only lowercase a-z allowed");
            }
            int idx = ch - 'a';
            if (current.children[idx] == null) {
                current.children[idx] = new TrieNode(ch);
            }
            current = current.children[idx];
        }
        current.isWord = true;
    }

    /**
     * Checks whether a word exists in the Trie.
     *
     * @param item the word to search for
     * @return true if the word is present, false otherwise
     */
    public boolean contains(String item) {
        if (item == null) {
            return false;
        }
        TrieNode current = root;
        for (char ch : item.toCharArray()) {
            if (ch < 'a' || ch > 'z') {
                return false;
            }
            int idx = ch - 'a';
            if (current.children[idx] == null) {
                return false;
            }
            current = current.children[idx];
        }
        return current.isWord;
    }

    /** Node used internally by the Trie. */
    private static class TrieNode {
        final char value;
        boolean isWord;
        final TrieNode[] children;

        TrieNode(char value) {
            this.value = value;
            this.isWord = false;
            this.children = new TrieNode[26]; // for 'a' to 'z'
        }
    }
}

