        Integer[] left = Arrays.copyOfRange(array, 0, mid);
        Integer[] right = Arrays.copyOfRange(array, mid, array.length);

        left = sortIntegers(left);
        right = sortIntegers(right);

        return merge(left, right);
    }

    /* Generic merge sort method */
    public <T> T[] sort(T[] array, Comparator<? super T> comparator, boolean ascending) {
        if (array == null) {
            throw new IllegalArgumentException("Array must not be null");
        }
        if (comparator == null) {
            throw new IllegalArgumentException("Comparator must not be null");
        }
        return mergeSort(array, comparator, ascending);
    }

    /* Recursive merge sort for generic types */
    private <T> T[] mergeSort(T[] array, Comparator<? super T> comp, boolean ascending) {
        if (array.length <= 1) {
            return array;
        }

        int mid = array.length / 2;
        T[] left = Arrays.copyOfRange(array, 0, mid);
        T[] right = Arrays.copyOfRange(array, mid, array.length);

        left = mergeSort(left, comp, ascending);
        right = mergeSort(right, comp, ascending);

        return merge(left, right, comp, ascending);
    }

    /* Merge two sorted halves for generic types */
    private <T> T[] merge(T[] left, T[] right, Comparator<? super T> comp, boolean ascending) {
        @SuppressWarnings("unchecked")
        T[] result = (T[]) Array.newInstance(left.getClass().getComponentType(),
                                            left.length + right.length);
        int i = 0, j = 0, k = 0;

        while (i < left.length && j < right.length) {
            int cmp = comp.compare(left[i], right[j]);

            if (ascending) {
                if (cmp <= 0) {
                    result[k++] = left[i++];
                } else {
                    result[k++] = right[j++];
