            } else { // descending
                if (cmp >= 0) {
                    result[k++] = left[i++];
                } else {
                    result[k++] = right[j++];
                }
            }
        }

        while (i < left.length) {
            result[k++] = left[i++];
        }
        while (j < right.length) {
            result[k++] = right[j++];
        }

        return result;
    }

    /* Merge two sorted halves for Integer type */
    private Integer[] merge(Integer[] left, Integer[] right) {
        Integer[] result = new Integer[left.length + right.length];
