import java.util.ArrayList;
import java.util.List;
import java.util.function.Supplier;

/**
 * Utility class providing enhanced test helpers.
 */
public final class EnhancedTestUtils {

    // Private constructor to prevent instantiation
    private EnhancedTestUtils() {}

    /**
     * Creates a list containing {@code count} elements generated by the supplied {@link Supplier}.
     *
     * @param count    the number of elements to generate; must be non‑negative
     * @param supplier the supplier used to generate each element; must not be {@code null}
     * @param <T>      the type of elements in the resulting list
     * @return a {@link List} containing {@code count} elements produced by {@code supplier}
     * @throws IllegalArgumentException if {@code count} is negative
     * @throws NullPointerException     if {@code supplier} is {@code null}
     */
    public static <T> List<T> createEnhancedList(int count, Supplier<T> supplier) {
        if (count < 0) {
            throw new IllegalArgumentException("Count must be non‑negative, but was: " + count);
        }
        if (supplier == null) {
            throw new NullPointerException("Supplier must not be null");
        }

        List<T> result = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            result.add(supplier.get());
        }
        return result;
    }
}

