    public boolean hasCycle() {
        Set<String> visited = new HashSet<>();

        if (directed) {
            Set<String> recStack = new HashSet<>();
            for (String node : adjacencyList.keySet()) {
                if (!visited.contains(node)) {
                    if (dfsDirected(node, visited, recStack)) {
                        return true;
                    }
                }
            }
        } else {
            for (String node : adjacencyList.keySet()) {
                if (!visited.contains(node)) {
                    if (dfsUndirected(node, visited, null)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean dfsDirected(String node, Set<String> visited, Set<String> recStack) {
        visited.add(node);
        recStack.add(node);

        for (Edge e : adjacencyList.get(node)) {
            String neighbor = e.destination;
            if (!visited.contains(neighbor)) {
                if (dfsDirected(neighbor, visited, recStack)) {
                    return true;
                }
            } else if (recStack.contains(neighbor)) {
                return true; // back edge found
            }
        }

        recStack.remove(node);
        return false;
    }

    private boolean dfsUndirected(String node, Set<String> visited, String parent) {
        visited.add(node);

        for (Edge e : adjacencyList.get(node)) {
            String neighbor = e.destination;
            if (!visited.contains(neighbor)) {
                if (dfsUndirected(neighbor, visited, node)) {
                    return true;
                }
            } else if (!neighbor.equals(parent)) {
                return true; // cycle detected
            }
        }
        return false;
    }

    /**
     * Finds the shortest path between {@code start} and {@code end}
     * using Dijkstra's algorithm. If the graph is unweighted, each
     * edge is treated as having weight 1.
     *
     * @param start the starting node
     * @param end   the destination node
     * @return a list of node names representing the shortest path,
     *         or an empty list if no path exists
     * @throws IllegalArgumentException if either node does not exist
     */
    public List<String> findShortestPath(String start, String end) {
        if (!adjacencyList.containsKey(start)) {
            throw new IllegalArgumentException("Start node does not exist: " + start);
        }
        if (!adjacencyList.containsKey(end)) {
            throw new IllegalArgumentException("End node does not exist: " + end);
        }

        // Dijkstra's algorithm
        Map<String, Integer> dist = new HashMap<>();
        Map<String, String> prev = new HashMap<>();
        PriorityQueue<NodeDist> pq = new PriorityQueue<>(Comparator.comparingInt(nd -> nd.dist));

        for (String node : adjacencyList.keySet()) {
            dist.put(node, Integer.MAX_VALUE);
        }
        dist.put(start, 0);
        pq.offer(new NodeDist(start, 0));

        while (!pq.isEmpty()) {
            NodeDist current = pq.poll();
            if (current.dist > dist.get(current.node)) {
                continue; // stale entry
            }
            if (current.node.equals(end)) {
                break; // reached destination
            }

            for (Edge e : adjacencyList.get(current.node)) {
                int weight = weighted ? e.weight : 1;
                int alt = current.dist + weight;
                if (alt < dist.get(e.destination)) {
                    dist.put(e.destination, alt);
                    prev.put(e.destination, current.node);
                    pq.offer(new NodeDist(e.destination, alt));
                }
            }
        }

        // Reconstruct path
        List<String> path = new ArrayList<>();
        if (dist.get(end) == Integer.MAX_VALUE) {
            return path; // no path
        }

        for (String at = end; at != null; at = prev.get(at)) {
            path.add(at);
        }
        Collections.reverse(path);
        return path;
    }

    // Optional: method to retrieve adjacency list for inspection
    public Map<String, List<Edge>> getAdjacencyList() {
        return adjacencyList;
    }

    // Optional: simple string representation of the graph
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, List<Edge>> entry : adjacencyList.entrySet()) {
            sb.append(entry.getKey()).append(" -> ");
            List<Edge> edges = entry.getValue();
