    public int getImageId() { return imageId; }
    public void setImageId(int imageId) { this.imageId = imageId; }

    public int getHardwareProfileId() { return hardwareProfileId; }
    public void setHardwareProfileId(int hardwareProfileId) { this.hardwareProfileId = hardwareProfileId; }

    public Map<String, Boolean> getApprovalStatus() { return approvalStatus; }
}

