import java.util.*;
import java.net.URLEncoder;
import java.io.UnsupportedEncodingException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

class SecurePaymentProcessor {

    /**
     * Generates a secure payment URL by appending the provided parameters
     * in alphabetical order. The method validates the base URL and secret,
     * and computes a signature using the secret for future use.
     *
     * @param baseUrl    the base URL to which parameters will be appended
     * @param secret     a secret key used for signature generation
     * @param parameters a map of query parameters to include in the URL
     * @return the fully constructed URL with encoded parameters
     * @throws IllegalArgumentException if baseUrl or secret is null or empty
     */
    public String generateSecurePaymentUrl(String baseUrl, String secret, Map<String, String> parameters) {
        // Input validation
        if (baseUrl == null || baseUrl.isEmpty()) {
            throw new IllegalArgumentException("baseUrl cannot be null or empty");
        }
        if (secret == null || secret.isEmpty()) {
            throw new IllegalArgumentException("secret cannot be null or empty");
        }

        // Compute a signature (currently not appended to the URL)
        String signature = computeSignature(secret, parameters);

        // Build the URL with sorted, encoded parameters
        if (parameters == null || parameters.isEmpty()) {
            return baseUrl;
        }

        List<String> keys = new ArrayList<>(parameters.keySet());
        Collections.sort(keys);

        StringBuilder urlBuilder = new StringBuilder(baseUrl);
        boolean hasQuery = baseUrl.contains("?");

        for (String key : keys) {
            if (hasQuery) {
                urlBuilder.append('&');
            } else {
                urlBuilder.append('?');
                hasQuery = true;
            }

            try {
                urlBuilder.append(URLEncoder.encode(key, "UTF-8"));
                urlBuilder.append('=');
                urlBuilder.append(URLEncoder.encode(parameters.get(key), "UTF-8"));
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException("UTF-8 encoding not supported", e);
            }
        }

        // The signature is computed for future use (e.g., to be appended later)
        // Currently it is not part of the URL output.
        // For demonstration, we simply ignore it here.

        return urlBuilder.toString();
    }

    /**
     * Computes a base64-encoded SHA-256 signature of the secret concatenated
     * with the sorted parameter string. This method is a placeholder for
     * future use where the signature might be appended to the URL.
     *
     * @param secret     the secret key
     * @param parameters the parameters to include in the signature
     * @return the base64-encoded signature string
     */
    private String computeSignature(String secret, Map<String, String> parameters) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            StringBuilder data = new StringBuilder(secret);

            if (parameters != null && !parameters.isEmpty()) {
                List<String> keys = new ArrayList<>(parameters.keySet());
                Collections.sort(keys);
                for (String key : keys) {
                    data.append(key).append('=').append(parameters.get(key)).append('&');
                }
            }

            byte[] hash = digest.digest(data.toString().getBytes(StandardCharsets.UTF_8));
            return Base64.getEncoder().encodeToString(hash);
        } catch (NoSuchAlgorithmException e) {
            // SHA-256 is guaranteed to be available; rethrow as unchecked
            throw new RuntimeException("SHA-256 algorithm not available", e);
        }
    }
}

