import java.util.ArrayList;

class PatternGenerator {
    public static List<String> generateSandClock(int size, boolean reverse, boolean useLetters) {
        if (size <= 0) {
            throw new IllegalArgumentException("Size must be positive");
        }

        List<String> pattern = new ArrayList<>();

        // Upper half (including the middle line)
        for (int line = 1; line <= size; line++) {
            pattern.add(buildLine(line, reverse, useLetters));
        }

        // Lower half (mirrored, excluding the middle line)
        for (int line = size - 1; line >= 1; line--) {
            pattern.add(buildLine(line, reverse, useLetters));
        }

        return pattern;
    }

    private static String buildLine(int line, boolean reverse, boolean useLetters) {
        StringBuilder sb = new StringBuilder();

        // Indentation: two spaces per level (line-1)
        for (int i = 0; i < (line - 1) * 2; i++) {
            sb.append(' ');
        }

        int start, end, step;
        if (reverse) {
            start = line;
            end = 1;
            step = -1;
        } else {
            start = 1;
            end = line;
            step = 1;
        }

        for (int i = start; (step > 0) ? i <= end : i >= end; i += step) {
            if (useLetters) {
                char c = (char) ('A' + i - 1);
                sb.append(c);
            } else {
                sb.append(i);
            }

            // Append separator if not the last element
            if ((step > 0 && i < end) || (step < 0 && i > end)) {
                sb.append("---");
            }
        }

        return sb.toString();
    }
}

