     * @param level   the severity level of the alert (e.g., "INFO", "WARN", "ERROR")
     * @param message the alert message
     */
    public void triggerAlert(String level, String message) {
        if (level == null || message == null) {
            throw new IllegalArgumentException("Level and message must not be null");
        }

        // Increment count atomically, initializing to zero if absent
        alertCounts.computeIfAbsent(level, k -> new AtomicInteger(0)).incrementAndGet();

        // Update last message atomically
        lastAlertMessages.put(level, message);

        // Notify listeners for this level
        String levelSuffix = ":" + level;
        listeners.forEach((key, callback) -> {
            if (key.endsWith(levelSuffix)) {
                try {
                    callback.accept(message);
                } catch (Exception e) {
                    // Handle listener exceptions without affecting other listeners
                    System.err.println("Listener " + key + " threw an exception: " + e.getMessage());
                }
            }
        });
    }

    /**
     * Registers a listener callback for a specific alert level.
     * The alert level is automatically initialized in {@code alertCounts} if it
     * has not been seen before.
     *
     * @param listenerId a unique identifier for the listener
     * @param level      the alert level the listener is interested in
     * @param callback   the callback to invoke when an alert of the specified level occurs
     */
    public void addAlertListener(String listenerId, String level, Consumer<String> callback) {
        if (listenerId == null || level == null || callback == null) {
            throw new IllegalArgumentException("Listener ID, level, and callback must not be null");
        }

        // Ensure the level is initialized in alertCounts
        alertCounts.computeIfAbsent(level, k -> new AtomicInteger(0));

        String key = listenerId + ":" + level;
        listeners.put(key, callback);
    }

    /**
     * Unregisters a listener for a specific alert level.
     * If no such listener exists, the method does nothing.
     *
     * @param listenerId the unique identifier of the listener to remove
     * @param level      the alert level the listener was registered for
     */
    public void removeAlertListener(String listenerId, String level) {
        if (listenerId == null || level == null) {
            return; // silently ignore invalid arguments
        }
        String key = listenerId + ":" + level;
        listeners.remove(key);
    }

    /**
     * Returns the number of alerts that have been triggered for the specified level.
     *
     * @param level the severity level
     * @return the alert count, or 0 if no alerts have been recorded for this level
     */
    public int getAlertCount(String level) {
        AtomicInteger counter = alertCounts.get(level);
        return counter == null ? 0 : counter.get();
    }

    /**
     * Retrieves the most recent alert message for the specified level.
     *
     * @param level the severity level
     * @return the last alert message, or null if no alert has been recorded for this level
     */
    public String getLastAlertMessage(String level) {
        return lastAlertMessages.get(level);
    }

    /**
     * Resets all alert statistics, clearing counts and last messages.
     */
    public void resetStatistics() {
        alertCounts.clear();
        lastAlertMessages.clear();
    }

    // Optional: main method for quick manual testing
    public static void main(String[] args) {
        AlertingService service = new AlertingService();

        // Register listeners
        service.addAlertListener("listener1", "INFO", msg -> System.out.println("[Listener1] INFO: " + msg));
        service.addAlertListener("listener2", "WARN", msg -> System.out.println("[Listener2] WARN: " + msg));
        service.addAlertListener("listener3", "INFO", msg -> System.out.println("[Listener3] INFO: " + msg));

        // Trigger alerts
        service.triggerAlert("INFO", "System started");
        service.triggerAlert("WARN", "Low disk space");
        service.triggerAlert("INFO", "User logged in");

        // Remove a listener
        service.removeAlertListener("listener3", "INFO");

        // Trigger another INFO alert to see that listener3 is no longer notified
        service.triggerAlert("INFO", "Another info message");

        // Retrieve stats
        System.out.println("INFO count: " + service.getAlertCount("INFO")); // 3
        System.out.println("WARN count: " + service.getAlertCount("WARN")); // 1
        System.out.println("INFO last message: " + service.getLastAlertMessage("INFO")); // Another info message

        // Reset statistics
        service.resetStatistics();
        System.out.println("INFO count after reset: " + service.getAlertCount("INFO")); // 0
    }
}
