import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;

/**
 * A simple configuration manager that allows registering and retrieving beans by name.
 */
public class ConfigManager {

    // Thread-safe map to store beans
    private final Map<String, Object> beanRegistry = new ConcurrentHashMap<>();

    /**
     * Registers a bean under the given name. The bean is created lazily using the supplied Supplier.
     *
     * @param name     the unique name of the bean
     * @param supplier a Supplier that provides the bean instance
     * @throws IllegalArgumentException if the name is null or empty, or if a bean with the same name already exists
     */
    public void registerBean(String name, Supplier<?> supplier) {
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("Bean name must not be null or empty");
        }
        if (supplier == null) {
            throw new IllegalArgumentException("Supplier must not be null");
        }
        // putIfAbsent ensures that we don't overwrite an existing bean
        Object previous = beanRegistry.putIfAbsent(name, supplier.get());
        if (previous != null) {
            throw new IllegalArgumentException("A bean with name '" + name + "' is already registered");
        }
    }

    /**
     * Retrieves a bean by its name.
     *
     * @param name the name of the bean to retrieve
     * @return the bean instance, or null if no bean is registered under that name
     */
    public Object getBean(String name) {
        return beanRegistry.get(name);
    }

    /**
     * Retrieves a bean by its name and casts it to the desired type.
     *
     * @param name the name of the bean to retrieve
     * @param <T>  the expected type of the bean
     * @return the bean instance cast to type T, or null if no bean is registered under that name
     * @throws ClassCastException if the bean cannot be cast to the requested type
     */
    @SuppressWarnings("unchecked")
    public <T> T getBean(String name, Class<T> type) {
        Object bean = beanRegistry.get(name);
        if (bean == null) {
            return null;
        }
        return (T) bean;
    }
}

