import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;

/**
 * A simple configuration manager that supports bean registration and
 * simulated loading of properties files.
 */
public class ConfigManager {

    /* ---------- Bean registry ---------- */
    private final Map<String, Object> beanRegistry = new ConcurrentHashMap<>();

    /**
     * Registers a bean under the given name. The bean is created lazily using the supplied Supplier.
     *
     * @param name     the unique name of the bean
     * @param supplier a Supplier that provides the bean instance
     * @throws IllegalArgumentException if the name is null/empty or a bean with the same name already exists
     */
    public void registerBean(String name, Supplier<?> supplier) {
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("Bean name must not be null or empty");
        }
        if (supplier == null) {
            throw new IllegalArgumentException("Supplier must not be null");
        }
        Object previous = beanRegistry.putIfAbsent(name, supplier.get());
        if (previous != null) {
            throw new IllegalArgumentException("A bean with name '" + name + "' is already registered");
        }
    }

    /**
     * Retrieves a bean by its name.
     *
     * @param name the name of the bean to retrieve
     * @return the bean instance, or {@code null} if no bean is registered under that name
     */
    public Object getBean(String name) {
        return beanRegistry.get(name);
    }

    /* ---------- Properties handling ---------- */
    private final List<String> configFiles = new ArrayList<>();
    private final Properties properties = new Properties();

    /**
     * Simulates loading a properties file. The file path is stored in the list of configuration files.
     * If the path contains {@code "config.properties"} dummy properties are added.
     *
     * @param path the path of the properties file to load
     * @throws IllegalArgumentException if the path is null or empty
     */
    public void loadProperties(String path) {
