    /**
     * Result class holds whether all courses can be finished and an ordering of courses.
     */
    public static class Result {
        public final boolean canFinish;
        public final int[] order;

        public Result(boolean canFinish, int[] order) {
            this.canFinish = canFinish;
            this.order = order;
        }
    }

    /**
     * Determines if all courses can be finished given prerequisites.
     * For now, assumes no cycles and always returns true with a simple ordering.
     *
     * @param numCourses    total number of courses
     * @param prerequisites array of prerequisite pairs [course, prerequisite]
     * @return Result object containing canFinish flag and course order
     */
    public Result scheduleCourses(int numCourses, int[][] prerequisites) {
        // Since we assume no cycles, we can always finish all courses.
        boolean canFinish = true;

        // Simple ordering: 0, 1, 2, ..., numCourses-1
        int[] order = new int[numCourses];
        for (int i = 0; i < numCourses; i++) {
            order[i] = i;
        }

        return new Result(canFinish, order);
    }
}

