import java.util.*;

public class CourseScheduler {

    /**
     * Result class holds whether all courses can be finished and an ordering of courses.
     */
    public static class Result {
        public final boolean canFinish;
        public final int[] order;

        public Result(boolean canFinish, int[] order) {
            this.canFinish = canFinish;
            this.order = order;
        }
    }

    /**
     * Determines if all courses can be finished given prerequisites.
     * Builds a graph, computes in-degrees, and performs a topological sort.
     *
     * @param numCourses    total number of courses
     * @param prerequisites array of prerequisite pairs [course, prerequisite]
     * @return Result object containing canFinish flag and course order
     */
    public Result scheduleCourses(int numCourses, int[][] prerequisites) {
        // Build adjacency list and compute in-degrees
        List<Integer>[] graph = new ArrayList[numCourses];
        for (int i = 0; i < numCourses; i++) {
            graph[i] = new ArrayList<>();
        }
        int[] indegree = new int[numCourses];

        for (int[] pair : prerequisites) {
            int course = pair[0];
            int prereq = pair[1];
            graph[prereq].add(course);
            indegree[course]++;
        }

        // Queue for courses with no prerequisites (in-degree 0)
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) {
            if (indegree[i] == 0) {
                queue.offer(i);
            }
        }

        // Perform Kahn's algorithm for topological sorting
        List<Integer> orderList = new ArrayList<>();
        while (!queue.isEmpty()) {
            int curr = queue.poll();
            orderList.add(curr);
            for (int next : graph[curr]) {
                indegree[next]--;
                if (indegree[next] == 0) {
                    queue.offer(next);
                }
            }
        }

        boolean canFinish = (orderList.size() == numCourses);
        int[] order = orderList.stream().mapToInt(Integer::intValue).toArray();

        return new Result(canFinish, order);
    }
}

