    public void setAllowedRoles(String roles) {
        List<String> list = stringToList(roles);
        if (strictMode && !areRolesValid(list)) {
            throw new IllegalArgumentException("Invalid roles in allowedRoles: " + list);
        }
        this.allowedRoles = list;
    }

    /**
     * Sets disallowed roles from a comma‑separated string.
     * In strict mode, all roles must be valid.
     */
    public void setDisallowedRoles(String roles) {
        List<String> list = stringToList(roles);
        if (strictMode && !areRolesValid(list)) {
            throw new IllegalArgumentException("Invalid roles in disallowedRoles: " + list);
        }
        this.disallowedRoles = list;
    }

    /**
     * Returns true only if every role in the list is present in validRoles.
     */
    public boolean areRolesValid(List<String> roles) {
        for (String role : roles) {
            if (!validRoles.contains(role)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Helper: converts a comma‑separated string to a trimmed list.
     * Handles null or empty strings by returning an empty list.
     */
    private List<String> stringToList(String val) {
        if (val == null || val.trim().isEmpty()) {
            return new ArrayList<>();
        }
        String[] parts = val.split(",");
        List<String> list = new ArrayList<>(parts.length);
        for (String part : parts) {
            String trimmed = part.trim();
            if (!trimmed.isEmpty()) {
                list.add(trimmed);
            }
        }
        return list;
    }

    // Optional helper methods
    public void addAllowedRole(String role) {
        if (validRoles.contains(role)) {
            allowedRoles.add(role);
        }
    }

    public void addDisallowedRole(String role) {
        if (validRoles.contains(role)) {
            disallowedRoles.add(role);
        }
    }

