     * Returns a copy of the set of contracts associated with the given tariff ID.
     *
     * @param tariffId the ID of the tariff
     * @return a copy of the set of contracts
     * @throws IllegalArgumentException if the tariff ID does not exist
     */
    public Set<Contract> getContractsByTariff(int tariffId) {
        Set<Contract> contracts = tariffContracts.get(tariffId);
        if (contracts == null) {
            throw new IllegalArgumentException("Tariff ID not found: " + tariffId);
        }
        return new HashSet<>(contracts); // return a copy
    }

