     * @throws IllegalArgumentException if the contract is null or if the tariff ID does not exist
     */
    public void subscribeContractToTariff(int tariffId, Contract contract) {
        if (contract == null) {
            throw new IllegalArgumentException("Contract cannot be null");
        }
        Set<Contract> contracts = tariffContracts.get(tariffId);
        if (contracts == null) {
            throw new IllegalArgumentException("Tariff ID not found: " + tariffId);
        }
        if (!contracts.add(contract)) {
            throw new IllegalArgumentException("Contract with ID " + contract.getId() + " is already subscribed to tariff " + tariffId + ".");
        }
    }

    /**
     * Retrieves a tariff by its ID.
     *
     * @param tariffId the ID of the tariff
     * @return the Tariff object
     * @throws NoSuchElementException if the tariff does not exist
     */
    public Tariff getTariff(int tariffId) {
        Tariff tariff = tariffs.get(tariffId);
        if (tariff == null) {
            throw new NoSuchElementException("Tariff with ID " + tariffId + " does not exist.");
        }
        return tariff;
    }

    /**
     * Returns a copy of the set of contracts associated with the given tariff ID.
     *
     * @param tariffId the ID of the tariff
     * @return a copy of the set of contracts
     * @throws IllegalArgumentException if the tariff ID does not exist
     */
    public Set<Contract> getContractsByTariff(int tariffId) {
        Set<Contract> contracts = tariffContracts.get(tariffId);
        if (contracts == null) {
            throw new IllegalArgumentException("Tariff ID not found: " + tariffId);
        }
        return new HashSet<>(contracts); // return a copy
    }

    /**
     * Returns the tariff with the highest number of subscribed contracts.
     *
     * @return the most popular Tariff, or null if no tariffs exist
     */
    public Tariff getMostPopularTariff() {
        if (tariffs.isEmpty()) {
            return null;
        }
        Tariff mostPopular = null;
        int maxCount = -1;
        for (Map.Entry<Integer, Tariff> entry : tariffs.entrySet()) {
            int tariffId = entry.getKey();
            Set<Contract> contracts = tariffContracts.get(tariffId);
            int count = contracts != null ? contracts.size() : 0;
            if (count > maxCount) {
                maxCount = count;
                mostPopular = entry.getValue();
            }
        }
        return mostPopular;
    }

    /**
     * Returns all tariffs managed by this system.
     *
     * @return a collection of all tariffs
     */
    public Collection<Tariff> getAllTariffs() {
        return Collections.unmodifiableCollection(tariffs.values());
    }
}

