import java.util.ArrayList;
import java.util.List;

/**
 * Basic Employee class with id, name and salary.
 */
class Employee {
    private String id;
    private String name;
    private double salary;

    public Employee(String name, double salary) {
        this.name = name;
        this.salary = salary;
    }

    // Getters and setters
    public String getId() { return id; }
    public void setId(String id) { this.id = id; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public double getSalary() { return salary; }
    public void setSalary(double salary) { this.salary = salary; }

    @Override
    public String toString() {
        return "Employee{id='" + id + "', name='" + name + "', salary=" + salary + "}";
    }
}

/**
 * Manager extends Employee and manages a list of subordinates.
 */
class Manager extends Employee {
    private final List<Employee> subordinates;

    public Manager(String name, double salary) {
        super(name, salary);
        this.subordinates = new ArrayList<>();
    }

    public void addSubordinate(Employee employee) {
        if (employee != null) {
            subordinates.add(employee);
        }
    }

    public List<Employee> getSubordinates() {
        return new ArrayList<>(subordinates);
    }

    public int getTeamSize() {
        return subordinates.size();
    }
}

/**
 * Company class implemented as a Singleton.
 */
public class Company {
    // Single instance of Company
    private static Company instance;

    // List to track all employees
    private final List<Employee> employees;

    // Counter for assigning unique employee IDs
    private int employeeCounter;

    // Private constructor to prevent direct instantiation
    private Company() {
        employees = new ArrayList<>();
        employeeCounter = 1;
    }

    /**
     * Returns the single instance of Company.
     *
     * @return the Company instance
     */
    public static synchronized Company getInstance() {
        if (instance == null) {
            instance = new Company();
        }
        return instance;
    }

    /**
     * Adds an employee to the company, assigning a unique ID.
     *
     * @param employee the employee to add
     */
    public void addEmployee(Employee employee) {
        if (employee != null) {
            employee.setId(String.valueOf(employeeCounter++));
            employees.add(employee);
        }
    }

    /**
     * Returns a copy of the list of all employees.
     *
     * @return list of employees
     */
    public List<Employee> getEmployees() {
        return new ArrayList<>(employees);
    }

    /**
     * Returns the current employee counter value.
     *
     * @return the employee counter
     */
    public int getEmployeeCounter() {
        return employeeCounter;
    }
}

