import java.util.List;

/**
 * Represents a permission with a URI pattern and an HTTP method.
 */
public class PermissionInfo {
    private final String uri;
    private final String method;

    public PermissionInfo(String uri, String method) {
        this.uri = uri;
        this.method = method;
    }

    public String getUri() {
        return uri;
    }

    public String getMethod() {
        return method;
    }

    @Override
    public String toString() {
        return "PermissionInfo{uri='" + uri + "', method='" + method + "'}";
    }
}

/**
 * Validates whether a request matches any of the provided permissions.
 * Supports the `{*}` wildcard in permission URIs, which matches exactly
 * one non‑empty alphanumeric segment.
 */
public class PermissionValidator {

    /**
     * Checks if the request URI and method match any permission in the list.
     *
     * @param permissions   list of permissions to validate against (may be null or empty)
     * @param requestUri    the request URI to check
     * @param requestMethod the request HTTP method to check
     * @return true if any permission matches the URI and method (method comparison is case‑insensitive);
     *         false if the list is null, empty, or no match is found
     */
    public boolean hasPermission(List<PermissionInfo> permissions, String requestUri, String requestMethod) {
        if (permissions == null || permissions.isEmpty()) {
            return false;
        }
        for (PermissionInfo permission : permissions) {
            if (permission == null) {
                continue; // skip null entries
            }
            if (uriMatches(permission.getUri(), requestUri)
                    && permission.getMethod().equalsIgnoreCase(requestMethod)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines whether a permission URI pattern matches a request URI.
     * The pattern may contain the `{*}` wildcard, which matches exactly one
     * non‑empty alphanumeric segment.
     *
     * @param permUri    the permission URI pattern
     * @param requestUri the request URI
     * @return true if the pattern matches the request URI; false otherwise
     */
    private boolean uriMatches(String permUri, String requestUri) {
        if (permUri == null || requestUri == null) {
            return false;
        }

        // Remove leading slash for consistent splitting
        if (permUri.startsWith("/")) {
            permUri = permUri.substring(1);
        }
        if (requestUri.startsWith("/")) {
            requestUri = requestUri.substring(1);
        }

        // Split by '/' to compare segments
        String[] permSegments = permUri.split("/");
        String[] reqSegments = requestUri.split("/");

        if (permSegments.length != reqSegments.length) {
            return false;
        }

        for (int i = 0; i < permSegments.length; i++) {
            String permSeg = permSegments[i];
            String reqSeg = reqSegments[i];

            if ("{*}".equals(permSeg)) {
                // Wildcard must match a non‑empty alphanumeric segment
                if (!reqSeg.matches("[A-Za-z0-9]+")) {
                    return false;
                }
            } else {
                if (!permSeg.equals(reqSeg)) {
                    return false;
                }
            }
        }

        return true;
    }
}

