class LoopAnalyzer {
    private int loopCounter;
    private final List<Integer> breakLabels;
    private final List<Integer> continueLabels;

    public LoopAnalyzer() {
        this.loopCounter = 0;
        this.breakLabels = new ArrayList<>();
        this.continueLabels = new ArrayList<>();
    }

    /**
     * Generates intermediate code for a simple for-loop.
     *
     * @param initVar        the loop variable name
     * @param initValue      the initial value of the loop variable
     * @param conditionVar   the variable used in the loop condition
     * @param conditionValue the value to compare against in the condition
     * @param stepValue      the increment step for the loop variable
     * @return a list of strings representing the intermediate code
     */
    public List<String> generateForLoop(String initVar, int initValue,
                                        String conditionVar, int conditionValue,
                                        int stepValue) {
        List<String> intermediateCode = new ArrayList<>();
        loopCounter++;

        // Labels for the loop
        int headLabel = loopCounter * 1000 + 1;   // start of the loop
        int tailLabel = loopCounter * 1000 + 2;   // break target
        int continueLabel = loopCounter * 1000 + 3; // continue target

        // Track break and continue labels for nested loops
        breakLabels.add(tailLabel);
        continueLabels.add(continueLabel);

        // Generate the intermediate code
        intermediateCode.add(initVar + " = " + initValue);
        intermediateCode.add("L" + headLabel + ":");
        intermediateCode.add("if " + conditionVar + " > " + conditionValue + " goto L" + tailLabel);
        intermediateCode.add("// Loop body goes here");
        intermediateCode.add(initVar + " = " + initVar + " + " + stepValue);
        intermediateCode.add("goto L" + continueLabel);
        intermediateCode.add("L" + continueLabel + ":");
        intermediateCode.add("goto L" + headLabel);
        intermediateCode.add("L" + tailLabel + ":");

        return intermediateCode;
    }

    // Optional getters for the label lists (useful for break/continue handling)
    public List<Integer> getBreakLabels() {
        return breakLabels;
    }

    public List<Integer> getContinueLabels() {
        return continueLabels;
    }
}

