import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

class SystemShutdownManager {
    private final Map<String, Service> services;
    private final long timeout;
    private final TimeUnit timeoutUnit;
    private final AtomicBoolean isShuttingDown = new AtomicBoolean(false);

    public SystemShutdownManager(Map<String, Service> services, long timeout, TimeUnit timeoutUnit) {
        this.services = new ConcurrentHashMap<>(services);
        this.timeout = timeout;
        this.timeoutUnit = timeoutUnit;
    }

    public boolean shutdownAll() {
        // Ensure only one shutdown can proceed at a time
        if (isShuttingDown.getAndSet(true)) {
            // A shutdown is already in progress
            return false;
        }

        boolean allStopped = true;
        final long timeoutMs = timeoutUnit.toMillis(timeout);
        final long startTime = System.currentTimeMillis();

        try {
            for (Map.Entry<String, Service> entry : services.entrySet()) {
                String serviceName = entry.getKey();

                // Abort if the timeout has been exceeded
                if (System.currentTimeMillis() - startTime > timeoutMs) {
                    System.out.println("Shutdown timeout exceeded for service: " + serviceName);
                    return false;
                }

                System.out.println("Initiating shutdown for service: " + serviceName);
                long serviceStart = System.currentTimeMillis();
                try {
                    entry.getValue().stop();
                    long elapsed = System.currentTimeMillis() - serviceStart;
                    System.out.println("Successfully stopped service " + serviceName + " in " + elapsed + "ms");
                } catch (Exception e) {
                    allStopped = false;
                    System.out.println("Failed to stop service " + serviceName + ": " + e.getMessage());
                }
            }
        } finally {
            // Reset the flag so that future shutdowns can proceed
            isShuttingDown.set(false);
        }

        return allStopped;
    }

    public interface Service {
        void stop() throws Exception;
    }
}
