            urlBuilder.append(String.join("&", queryParams));
        }

        String url = urlBuilder.toString();

        // Simulate the HTTP request (currently unused, but added as requested)
        String response = simulateHttpRequest(url);

        // For now, return an empty list
        return new ArrayList<>();
    }

    private String simulateHttpRequest(String urlString) {
        if (urlString.contains("/schema")) {
            return "<xs:element name=\"Openbravo\">";
        } else if (urlString.contains("/dal")) {
            return "<Types>";
        } else if (urlString.contains("/ADColumn")) {
            // Parse query parameters
            int firstResult = 0;
            int maxResults = 0;
            int totalAvailable = 50; // maximum items available

            int queryIndex = urlString.indexOf('?');
            if (queryIndex != -1 && queryIndex < urlString.length() - 1) {
                String query = urlString.substring(queryIndex + 1);
                String[] pairs = query.split("&");
                for (String pair : pairs) {
                    String[] kv = pair.split("=", 2);
                    if (kv.length == 2) {
                        String key = kv[0];
                        String value = kv[1];
                        try {
                            if ("firstResult".equalsIgnoreCase(key)) {
                                firstResult = Integer.parseInt(value);
                            } else if ("maxResults".equalsIgnoreCase(key)) {
                                maxResults = Integer.parseInt(value);
                            }
                        } catch (NumberFormatException ignored) {
                        }
                    }
                }
            }

            // Clamp values
            if (firstResult < 0) firstResult = 0;
            if (maxResults < 0) maxResults = 0;
            if (firstResult >= totalAvailable) {
                return ""; // no items to return
            }
            int end = Math.min(firstResult + maxResults, totalAvailable);

            StringBuilder sb = new StringBuilder();
            for (int i = firstResult; i < end; i++) {
                sb.append("<ADColumn id=\"").append(i).append("\">Column").append(i).append("</ADColumn>");
                if (i < end - 1) sb.append("\n");
            }
            return sb.toString();
        } else {
            throw new IllegalArgumentException("Unknown endpoint: " + urlString);
        }
    }
