import java.util.*;

public class ScenarioAnalyzer {

    /**
     * Assigns unique indices to each node in the tree in breadth-first order
     * starting from 0 for the root, and returns a map with a 'nodeIndices'
     * entry mapping node names to their indices.
     *
     * @param root the root node of the scenario tree
     * @return a map containing the nodeIndices mapping
     */
    public static Map<String, Object> analyzeScenario(Node root) {
        Map<String, Integer> nodeIndices = new LinkedHashMap<>();
        Queue<Node> queue = new LinkedList<>();
        int index = 0;

        if (root == null) {
            return Collections.singletonMap("nodeIndices", nodeIndices);
        }

        queue.add(root);
        while (!queue.isEmpty()) {
            Node current = queue.poll();
            nodeIndices.put(current.getName(), index++);
            for (Node child : current.getChildren()) {
                queue.add(child);
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("nodeIndices", nodeIndices);
        return result;
    }

    // Example usage (optional)
    public static void main(String[] args) {
        Node root = new Node("root");
        Node child1 = new Node("child1");
        Node child2 = new Node("child2");
        root.addChild(child1);
        root.addChild(child2);
        child1.addChild(new Node("grandchild1"));
        child2.addChild(new Node("grandchild2"));

        Map<String, Object> analysis = analyzeScenario(root);
        System.out.println(analysis);
    }
}

class Node {
    private final String name;
    private final List<Node> children = new ArrayList<>();

    public Node(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public List<Node> getChildren() {
        return children;
    }

    public void addChild(Node child) {
        children.add(child);
    }
}

