import java.util.*;

/**
 * Basic scenario analyzer that assigns unique breadth‑first indices to each node
 * and detects synchronous request‑response pairs.
 */
public class ScenarioAnalyzer {

    /**
     * Assigns unique indices to each node in the tree in breadth‑first order
     * starting from 0 for the root, detects synchronous request‑response pairs,
     * and returns a map containing the node indices and sync pairs.
     *
     * @param root the root node of the scenario tree
     * @return a map with keys "nodeIndices" and "syncPairs"
     */
    public static Map<String, Object> analyzeScenario(Node root) {
        Map<String, Integer> nodeIndices = new LinkedHashMap<>();
        Map<Node, String> parentServerName = new HashMap<>();
        Queue<Node> queue = new LinkedList<>();
        int index = 0;

        if (root == null) {
            return Map.of(
                    "nodeIndices", nodeIndices,
                    "syncPairs", Collections.emptyMap()
            );
        }

        // Breadth‑first traversal to assign indices and record parent server names
        queue.add(root);
        parentServerName.put(root, null); // root has no parent
        while (!queue.isEmpty()) {
            Node current = queue.poll();
            nodeIndices.put(current.getName(), index++);
            for (Node child : current.getChildren()) {
                queue.add(child);
                parentServerName.put(child, current.getServerName());
            }
        }

        // Detect synchronous request‑response pairs
        Map<Integer, Integer> syncPairs = new LinkedHashMap<>();
        for (Node node : nodeIndices.keySet().stream()
                .map(name -> findNodeByName(root, name))
                .filter(Objects::nonNull)
                .toList()) {

            if (!node.isSync()) {
                continue;
            }

            String parentServer = parentServerName.get(node);
            if (parentServer == null) {
                continue; // root cannot be a sync request
            }

            for (Node child : node.getChildren()) {
                if (parentServer.equals(child.getServerName())) {
                    int requestIdx = nodeIndices.get(node.getName());
                    int responseIdx = nodeIndices.get(child.getName());
                    syncPairs.put(requestIdx, responseIdx);
                    break; // assume at most one matching child
                }
            }
        }

        return Map.of(
                "nodeIndices", nodeIndices,
                "syncPairs", syncPairs
        );
    }

    /**
     * Helper method to locate a node by its name in the tree.
     */
    private static Node findNodeByName(Node root, String name) {
        if (root == null) return null;
        if (root.getName().equals(name)) return root;
        for (Node child : root.getChildren()) {
            Node found = findNodeByName(child, name);
            if (found != null) return found;
        }
        return null;
    }

    // Example usage
    public static void main(String[] args) {
        Node root = new Node("root", "ServerA", false);
        Node req1 = new Node("req1", "ServerB", true);
        Node resp1 = new Node("resp1", "ServerA", false);
        Node req2 = new Node("req2", "ServerC", true);
        Node resp2 = new Node("resp2", "ServerC", false);

        root.addChild(req1);
        root.addChild(req2);
        req1.addChild(resp1);
        req2.addChild(resp2);

        Map<String, Object> result = analyzeScenario(root);
        System.out.println(result);
    }
}

/**
 * Simple node representation for the scenario tree.
 */
class Node {
    private final String name;
    private final String serverName;
