     *   - "nodeIndices": Map<String,Integer> mapping node names to indices
     *   - "syncPairs":   Map<Integer,List<Integer>> mapping request indices to
     *                     lists of response indices
     *   - "warnings":    List<String> of warning messages
     * @throws IllegalArgumentException if {@code rootNode} is {@code null}
     */
    public static Map<String, Object> analyzeScenario(Node rootNode) {
        if (rootNode == null) {
            throw new IllegalArgumentException("rootNode cannot be null");
        }

        // Data structures
        Map<String, Integer> nodeIndices = new LinkedHashMap<>();
        Map<Node, String> parentServerName = new HashMap<>();
        Map<String, Node> nodeMap = new HashMap<>();
        Queue<Node> queue = new LinkedList<>();
        int index = 0;

        // Breadth‑first traversal: assign indices, record parent server names,
        // and keep a map from node name to node instance.
        queue.add(rootNode);
        parentServerName.put(rootNode, null); // root has no parent
        while (!queue.isEmpty()) {
            Node current = queue.poll();
            nodeIndices.put(current.getName(), index++);
            nodeMap.put(current.getName(), current);
            for (Node child : current.getChildren()) {
                queue.add(child);
                parentServerName.put(child, current.getServerName());
            }
        }

        // Detect synchronous request‑response pairs
        Map<Integer, List<Integer>> syncPairs = new LinkedHashMap<>();
        for (Node node : nodeMap.values()) {
            if (!node.isSync()) {
                continue;
            }

            String parentServer = parentServerName.get(node);
            if (parentServer == null) {
                continue; // root cannot be a sync request
            }

            int requestIdx = nodeIndices.get(node.getName());
            boolean foundResponse = false;
            for (Node child : node.getChildren()) {
                if (parentServer.equals(child.getServerName())) {
                    int responseIdx = nodeIndices.get(child.getName());
                    syncPairs.computeIfAbsent(requestIdx, k -> new ArrayList<>()).add(responseIdx);
                    foundResponse = true;
                }
            }

            // If no matching child, record a warning
            if (!foundResponse) {
                String warning = String.format(
                        "Warning: There is no corresponding response to server \"%s\" from server \"%s\"",
                        node.getServerName(), parentServer);
                node.getWarnings().add(warning);
            }
        }

        // Collect all warnings from nodes
        List<String> warnings = new ArrayList<>();
        for (Node node : nodeMap.values()) {
            warnings.addAll(node.getWarnings());
        }

        return Map.of(
                "nodeIndices", nodeIndices,
                "syncPairs", syncPairs,
                "warnings", warnings
        );
    }

    // Example usage
    public static void main(String[] args) {
        Node root = new Node("root", "ServerA", false);
        Node req1 = new Node("req1", "ServerB", true);
        Node resp1a = new Node("resp1a", "ServerA", false);
        Node resp1b = new Node("resp1b", "ServerA", false);
        Node req2 = new Node("req2", "ServerC", true);
        // No response for req2 to trigger a warning

        root.addChild(req1);
        root.addChild(req2);
        req1.addChild(resp1a);
        req1.addChild(resp1b); // multiple responses for req1

        Map<String, Object> result = analyzeScenario(root);
        System.out.println(result);
    }
}

/**
 * Simple node representation for the scenario tree.
 */
class Node {
    private final String name;
    private final String serverName;
    private final boolean isSync;
    private final List<Node> children = new ArrayList<>();
    private final List<String> warnings = new ArrayList<>();

    public Node(String name, String serverName, boolean isSync) {
        this.name = name;
        this.serverName = serverName;
        this.isSync = isSync;
    }

    public String getName() {
        return name;
    }

    public String getServerName() {
        return serverName;
    }

    public boolean isSync() {
        return isSync;
    }

    public List<Node> getChildren() {
        return children;
    }

    public void addChild(Node child) {
        children.add(child);
    }

    public List<String> getWarnings() {
        return warnings;
    }
}
