import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

class ThreadSynchronizer {
    private final ReentrantLock lock;
    private final Condition condition;
    private boolean isSignalled;

    public ThreadSynchronizer() {
        this.lock = new ReentrantLock();
        this.condition = lock.newCondition();
        this.isSignalled = false;
    }

    /**
     * Waits for the specified number of seconds. The method returns {@code true}
     * if the thread was notified before the timeout expires, and {@code false}
     * if the timeout elapsed or the thread was interrupted.
     *
     * @param waitSeconds the maximum number of seconds to wait
     * @return {@code true} if notified within the timeout, {@code false} otherwise
     */
    public boolean waitWithDeadline(int waitSeconds) {
        long nanos = TimeUnit.SECONDS.toNanos(waitSeconds);
        long deadline = System.nanoTime() + nanos;

        lock.lock();
        try {
            while (!isSignalled) {
                if (nanos <= 0L) {
                    return false; // timeout expired
                }
                try {
                    // Await with the remaining time
                    boolean signaled = condition.await(nanos, TimeUnit.NANOSECONDS);
                    if (signaled) {
                        return true; // notified
                    }
                } catch (InterruptedException e) {
                    // Restore interrupt status and treat as a timeout
                    Thread.currentThread().interrupt();
                    return false;
                }
                // Recalculate remaining time
                nanos = deadline - System.nanoTime();
            }
            return true; // was already signalled
        } finally {
            lock.unlock();
        }
    }

    /**
     * Sets the signalling flag and notifies all waiting threads.
     */
    public void notifyAllThreads() {
        lock.lock();
        try {
            isSignalled = true;
            condition.signalAll();
        } finally {
            lock.unlock();
        }
    }
}

