import java.util.Objects;

/**
 * EggDropSolver provides two ways to solve the classic egg‑drop problem:
 * 1. A dynamic‑programming approach that iteratively finds the minimum
 *    number of attempts needed in the worst case.
 * 2. A mathematical approach that uses binomial coefficients to compute
 *    the same result.
 *
 * Both methods validate the input and throw IllegalArgumentException
 * if the number of eggs or floors is non‑positive.
 *
 * The solveBoth method returns the results of both approaches along
 * with the time taken by each (in nanoseconds).
 */
public class EggDropSolver {

    /**
     * Result container that holds the DP and mathematical results
     * and the time taken by each method.
     */
    public static class Result {
        public final int dpResult;
        public final long dpTime;      // nanoseconds
        public final int mathResult;
        public final long mathTime;    // nanoseconds

        public Result(int dpResult, long dpTime, int mathResult, long mathTime) {
            this.dpResult = dpResult;
            this.dpTime = dpTime;
            this.mathResult = mathResult;
            this.mathTime = mathTime;
        }
    }

    /* --------------------------------------------------------------------- */
    /* 1. Dynamic‑programming solution                                         */
    /* --------------------------------------------------------------------- */

    /**
     * Computes the minimum number of attempts needed in the worst case
     * using a dynamic‑programming approach.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return minimum number of attempts
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static int solveEggDropDP(int k, int n) {
        validate(k, n);

        if (n == 1) return 1;
        if (k == 1) return n;

        long[] dp = new long[k + 1];   // dp[i] = max floors testable with i eggs and current moves
        int moves = 0;

        while (dp[k] < n) {
            moves++;
            for (int i = k; i >= 1; i--) {
                dp[i] = dp[i] + dp[i - 1] + 1;
            }
        }
        return moves;
    }

    /* --------------------------------------------------------------------- */
    /* 2. Mathematical solution                                               */
    /* --------------------------------------------------------------------- */

    /**
     * Computes the minimum number of attempts needed in the worst case
     * using a mathematical approach based on binomial coefficients.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return minimum number of attempts
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static int solveEggDropMath(int k, int n) {
        validate(k, n);

        if (n == 1) return 1;
        if (k == 1) return n;

        int moves = 0;
        while (true) {
            moves++;
            long sum = 0;
            long binom = 1; // C(moves, 0)
            for (int i = 1; i <= k; i++) {
                // Compute C(moves, i) iteratively
                binom = binom * (moves - i + 1) / i;
                if (binom > n) binom = n + 1; // avoid overflow
                sum += binom;
                if (sum >= n) break;
            }
            if (sum >= n) return moves;
        }
    }

    /* --------------------------------------------------------------------- */
    /* 3. Combined solution that returns both results and timings             */
    /* --------------------------------------------------------------------- */

    /**
     * Computes both the DP and mathematical solutions and returns
     * the results along with the time taken by each method.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return Result object containing both results and timings
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static Result solveBoth(int k, int n) {
        validate(k, n);

        long startDP = System.nanoTime();
        int dpRes = solveEggDropDP(k, n);
        long endDP = System.nanoTime();

        long startMath = System.nanoTime();
        int mathRes = solveEggDropMath(k, n);
        long endMath = System.nanoTime();

        return new Result(dpRes, endDP - startDP, mathRes, endMath - startMath);
    }

    /* --------------------------------------------------------------------- */
    /* Helper methods                                                         */
    /* --------------------------------------------------------------------- */

    private static void validate(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
    }
}

