import java.util.Arrays;

/**
 * EggDropSolver provides three independent algorithms to solve the classic
 * egg‑drop problem:
 * 1. Dynamic‑programming (iterative).
 * 2. Mathematical (binomial‑coefficient based).
 * 3. Binary‑search with memoization (recursive).
 *
 * The {@link #solveBoth(int, int)} method returns the results of all three
 * approaches together with the time taken by each (in nanoseconds).
 */
public class EggDropSolver {

    /* --------------------------------------------------------------------- */
    /* Result container                                                        */
    /* --------------------------------------------------------------------- */

    public static class Result {
        public final int dpResult;
        public final long dpTime;      // nanoseconds
        public final int mathResult;
        public final long mathTime;    // nanoseconds
        public final int bsResult;
        public final long bsTime;      // nanoseconds

        public Result(int dpResult, long dpTime,
                      int mathResult, long mathTime,
                      int bsResult, long bsTime) {
            this.dpResult = dpResult;
            this.dpTime = dpTime;
            this.mathResult = mathResult;
            this.mathTime = mathTime;
            this.bsResult = bsResult;
            this.bsTime = bsTime;
        }
    }

    /* --------------------------------------------------------------------- */
    /* 1. Dynamic‑programming solution                                         */
    /* --------------------------------------------------------------------- */

    public static int solveEggDropDP(int k, int n) {
        validate(k, n);

        if (n == 1) return 1;
        if (k == 1) return n;

        long[] dp = new long[k + 1];   // dp[i] = max floors testable with i eggs and current moves
        int moves = 0;

        while (dp[k] < n) {
            moves++;
            for (int i = k; i >= 1; i--) {
                dp[i] = dp[i] + dp[i - 1] + 1;
            }
        }
        return moves;
    }

    /* --------------------------------------------------------------------- */
    /* 2. Mathematical solution                                               */
    /* --------------------------------------------------------------------- */

    public static int solveEggDropMath(int k, int n) {
        validate(k, n);

        if (n == 1) return 1;
        if (k == 1) return n;

        int moves = 0;
        while (true) {
            moves++;
            long sum = 0;
            long binom = 1; // C(moves, 0)
            for (int i = 1; i <= k; i++) {
                binom = binom * (moves - i + 1) / i;
                if (binom > n) binom = n + 1; // avoid overflow
                sum += binom;
                if (sum >= n) break;
            }
            if (sum >= n) return moves;
        }
    }

    /* --------------------------------------------------------------------- */
    /* 3. Binary‑search with memoization solution                             */
    /* --------------------------------------------------------------------- */

    public static int solveEggDropBS(int k, int n) {
        validate(k, n);
        int[][] memo = new int[k + 1][n + 1];
        for (int[] row : memo) Arrays.fill(row, 0);
        return bs(k, n, memo);
    }

    private static int bs(int k, int n, int[][] memo) {
        if (n == 0) return 0;
        if (k == 1) return n;
        if (memo[k][n] != 0) return memo[k][n];

        int low = 1, high = n;
        int best = Integer.MAX_VALUE;

        while (low <= high) {
            int mid = (low + high) >>> 1;
            int lowVal = bs(k - 1, mid - 1, memo);
            int highVal = bs(k, n - mid, memo);
            int cur = Math.max(lowVal, highVal);

            if (cur < best) best = cur;

            if (lowVal < highVal) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        memo[k][n] = best + 1;
        return memo[k][n];
    }

    /* --------------------------------------------------------------------- */
    /* Combined solution that returns all results and timings                */
    /* --------------------------------------------------------------------- */

    public static Result solveBoth(int k, int n) {
        validate(k, n);

        long startDP = System.nanoTime();
        int dpRes = solveEggDropDP(k, n);
        long endDP = System.nanoTime();

        long startMath = System.nanoTime();
        int mathRes = solveEggDropMath(k, n);
        long endMath = System.nanoTime();

        long startBS = System.nanoTime();
        int bsRes = solveEggDropBS(k, n);
        long endBS = System.nanoTime();

        return new Result(dpRes, endDP - startDP,
                          mathRes, endMath - startMath,
                          bsRes, endBS - startBS);
    }

    /* --------------------------------------------------------------------- */
    /* Helper method                                                          */
    /* --------------------------------------------------------------------- */

    private static void validate(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
    }
}

