import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/**
 * EggDropResult encapsulates the results of the three egg‑drop algorithms
 * and provides a locale‑independent string representation.
 *
 * The output format is:
 *   DP: <dpResult> attempts (time: <dpTime> ns);
 *   Math: <mathResult> attempts (time: <mathTime> ns);
 *   BS: <bsResult> attempts (time: <bsTime> ns)
 *
 * All numeric values are formatted with comma separators for thousands
 * (pattern "#,##0") regardless of the system locale.
 */
public class EggDropResult {

    private final int dpResult;
    private final long dpTime;      // nanoseconds
    private final int mathResult;
    private final long mathTime;    // nanoseconds
    private final int bsResult;
    private final long bsTime;      // nanoseconds

    private static final DecimalFormat NUMBER_FORMAT;

    static {
        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.US);
        NUMBER_FORMAT = new DecimalFormat("#,##0", symbols);
    }

    public EggDropResult(int dpResult, long dpTime,
                         int mathResult, long mathTime,
                         int bsResult, long bsTime) {
        this.dpResult = dpResult;
        this.dpTime = dpTime;
        this.mathResult = mathResult;
        this.mathTime = mathTime;
        this.bsResult = bsResult;
        this.bsTime = bsTime;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("DP: ")
          .append(NUMBER_FORMAT.format(dpResult))
          .append(" attempts (time: ")
          .append(NUMBER_FORMAT.format(dpTime))
          .append(" ns); ");

        sb.append("Math: ")
          .append(NUMBER_FORMAT.format(mathResult))
          .append(" attempts (time: ")
          .append(NUMBER_FORMAT.format(mathTime))
          .append(" ns); ");

        sb.append("BS: ")
          .append(NUMBER_FORMAT.format(bsResult))
          .append(" attempts (time: ")
          .append(NUMBER_FORMAT.format(bsTime))
          .append(" ns)");

        return sb.toString();
    }

    // Getters (optional, if needed elsewhere)
    public int getDpResult() { return dpResult; }
    public long getDpTime() { return dpTime; }
    public int getMathResult() { return mathResult; }
    public long getMathTime() { return mathTime; }
    public int getBsResult() { return bsResult; }
    public long getBsTime() { return bsTime; }
}

