import java.util.HashMap;
import java.util.Map;

class GraphDatabaseManager {
    private final Map<Long, Node> nodes = new HashMap<>();
    private final Map<Long, Relationship> relationships = new HashMap<>();
    private long nextNodeId = 1;
    private long nextRelationshipId = 1;

    public GraphDatabaseManager() {
    }

    /**
     * Creates a new node with the given properties.
     *
     * @param properties a map of property names to values
     * @return the unique ID assigned to the new node
     */
    public long createNode(Map<String, Object> properties) {
        long id = nextNodeId++;
        nodes.put(id, new Node(id, properties));
        return id;
    }

    /**
     * Creates a directed relationship between two existing nodes.
     *
     * @param startNodeId the ID of the start node
     * @param endNodeId   the ID of the end node
     * @param type        the relationship type
     * @param properties  a map of relationship properties
     * @return the unique ID assigned to the new relationship
     * @throws IllegalArgumentException if either node does not exist
     */
    public long createRelationship(long startNodeId, long endNodeId,
                                   String type, Map<String, Object> properties) {
        if (!nodes.containsKey(startNodeId) || !nodes.containsKey(endNodeId)) {
            throw new IllegalArgumentException(
                    "Node not found: one or both specified nodes do not exist.");
        }
        long id = nextRelationshipId++;
        relationships.put(id, new Relationship(id, startNodeId, endNodeId, type, properties));
        return id;
    }

    // Optional helper methods
    public Node getNode(long id) {
        return nodes.get(id);
    }

    public Relationship getRelationship(long id) {
        return relationships.get(id);
    }

    // Node representation
    private static class Node {
        private final long id;
        private final Map<String, Object> properties;

        Node(long id, Map<String, Object> properties) {
            this.id = id;
            this.properties = new HashMap<>(properties);
        }

        public long getId() {
            return id;
        }

        public Map<String, Object> getProperties() {
            return new HashMap<>(properties);
        }

        @Override
        public String toString() {
            return "Node{id=" + id + ", properties=" + properties + '}';
        }
    }

    // Relationship representation
    private static class Relationship {
        private final long id;
        private final long startNodeId;
        private final long endNodeId;
        private final String type;
        private final Map<String, Object> properties;

        Relationship(long id, long startNodeId, long endNodeId,
                     String type, Map<String, Object> properties) {
            this.id = id;
            this.startNodeId = startNodeId;
