    /**
     * Authenticates a user using email/password or Google token.
     *
     * @param email       the user's email address
     * @param password    the user's password
     * @param googleToken the Google authentication token (currently unused)
     * @return a map containing:
     *         - "success" (Boolean)
     *         - "userEmail" (String, if successful)
     *         - "authMethod" (String, if successful)
     *         - "message" (String, if failed)
     */
    public Map<String, Object> authenticateUser(String email, String password, String googleToken) {
        Map<String, Object> response = new HashMap<>();

        // Basic validation: email and password must be non-null, non-empty, and email must contain '@'
        if (email != null && !email.isEmpty() && email.contains("@")
                && password != null && !password.isEmpty()) {
            response.put("success", true);
            response.put("userEmail", email);
            response.put("authMethod", "email");
        } else {
            response.put("success", false);
            response.put("message", "Invalid email or password");
        }

        return response;
    }
}

