import java.util.Map;
import java.util.HashMap;

public class AuthenticationService {

    /**
     * Authenticates a user using email/password or Google token.
     *
     * @param email       the user's email address
     * @param password    the user's password
     * @param googleToken the Google authentication token (currently unused for email/password)
     * @return a map containing:
     *         - "success" (Boolean)
     *         - "userEmail" (String, if successful)
     *         - "authMethod" (String, if successful)
     *         - "message" (String, if failed)
     */
    public Map<String, Object> authenticateUser(String email, String password, String googleToken) {
        Map<String, Object> response = new HashMap<>();

        // 1. Handle the special case where all credentials are null
        if (email == null && password == null && googleToken == null) {
            response.put("success", false);
            response.put("message", "Authentication failed: No credentials provided");
            return response;
        }

        // 2. If email and password are provided (non-null), attempt email/password authentication
        if (email != null || password != null) {
            boolean emailValid = email != null && !email.isEmpty() && email.contains("@");
            boolean passwordValid = password != null && !password.isEmpty() && password.length() >= 6;

            if (emailValid && passwordValid) {
                response.put("success", true);
                response.put("userEmail", email);
                response.put("authMethod", "email");
            } else {
                response.put("success", false);
                response.put("message", "Invalid email or password");
            }
            return response;
        }

        // 3. At this point, email and password are both null. Attempt Google token authentication.
        if (googleToken != null && googleToken.startsWith("google_")) {
            String localPart = googleToken.substring("google_".length());
            String userEmail = localPart + "@gmail.com";

            response.put("success", true);
            response.put("userEmail", userEmail);
            response.put("authMethod", "google");
        } else {
            response.put("success", false);
            response.put("message", "Google authentication failed");
        }

        return response;
    }
}

