import java.util.concurrent.*;

public class ThreadExecutor {

    /**
     * Executes the given task in a separate thread and returns its result.
     * If the task does not complete within the specified timeout, a
     * TimeoutException is thrown.
     *
     * @param task       the task to execute
     * @param timeoutMs  the maximum time to wait in milliseconds
     * @param <T>        the type of the task's result
     * @return the result of the task
     * @throws Exception if the task throws an exception or times out
     */
    public static <T> T executeTaskWithTimeout(Callable<T> task, long timeoutMs) throws Exception {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<T> future = executor.submit(task);
        try {
            return future.get(timeoutMs, TimeUnit.MILLISECONDS);
        } catch (TimeoutException e) {
            future.cancel(true);
            throw new TimeoutException("Task timed out after " + timeoutMs + " ms");
        } finally {
            executor.shutdownNow();
        }
    }
}

class SampleTask implements Callable<String> {
    private final String name;
    private final long sleepTimeMs;

    public SampleTask(String name, long sleepTimeMs) {
        this.name = name;
        this.sleepTimeMs = sleepTimeMs;
    }

    @Override
    public String call() throws Exception {
        System.out.println("Task " + name + " started.");
        Thread.sleep(sleepTimeMs);
        return "Result from " + name + " after " + sleepTimeMs + "ms";
    }
}

