import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.FutureTask;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

/**
 * Utility class for executing tasks with a timeout.
 */
public class ThreadExecutor {

    /**
     * Executes the given task in a separate thread and returns its result.
     * If the task does not complete within the specified timeout, a
     * {@link TimeoutException} is thrown with the message:
     * <pre>
     * The task does not complete within the specified timeout period.
     * </pre>
     *
     * @param task       the task to execute
     * @param timeoutMs  the maximum time to wait in milliseconds
     * @param <T>        the type of the task's result
     * @return the result of the task
     * @throws TimeoutException   if the task does not finish in time
     * @throws ExecutionException if the task throws an exception
     * @throws InterruptedException if the current thread is interrupted while waiting
     */
    public static <T> T executeTaskWithTimeout(Callable<T> task, long timeoutMs)
            throws TimeoutException, ExecutionException, InterruptedException {

        FutureTask<T> futureTask = new FutureTask<>(task);
        Thread worker = new Thread(futureTask);
        worker.start();

        try {
            return futureTask.get(timeoutMs, TimeUnit.MILLISECONDS);
        } catch (TimeoutException e) {
            // Interrupt the worker thread to allow it to clean up
            worker.interrupt();
            throw new TimeoutException(
                    "The task does not complete within the specified timeout period.");
        }
    }
}

