import java.util.concurrent.ExecutionException;
import java.util.concurrent.FutureTask;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

/**
 * Utility class for executing tasks with a timeout.
 */
public class ThreadExecutor {

    /**
     * Executes the given task in a separate thread and returns its result.
     * <ul>
     *   <li>If the task does not complete within the specified timeout, a
     *       {@link TimeoutException} is thrown with the message
     *       {@code "The task does not complete within the specified timeout period."}.</li>
     *   <li>If the task throws an exception, it is wrapped in a new {@link Exception}
     *       with the message {@code "Task execution failed"} and the original cause
     *       is preserved.</li>
     *   <li>If the current thread is interrupted while waiting, the interrupt
     *       status is restored and a new {@link Exception} with the message
     *       {@code "Task was interrupted"} is thrown.</li>
     * </ul>
     *
     * @param task       the task to execute
     * @param timeoutMs  the maximum time to wait in milliseconds
     * @param <T>        the type of the task's result
     * @return the result of the task
     * @throws TimeoutException if the task does not finish in time
     * @throws Exception        if the task throws an exception or the current thread
     *                          is interrupted
     */
    public static <T> T executeTaskWithTimeout(Callable<T> task, long timeoutMs)
            throws TimeoutException, Exception {

        FutureTask<T> futureTask = new FutureTask<>(task);
        Thread worker = new Thread(futureTask);
        worker.start();

        try {
            return futureTask.get(timeoutMs, TimeUnit.MILLISECONDS);
        } catch (TimeoutException e) {
            // Interrupt the worker thread to allow it to clean up
            worker.interrupt();
            throw new TimeoutException(
                    "The task does not complete within the specified timeout period.");
        } catch (ExecutionException e) {
            // Preserve the original cause while providing a clear message
            throw new Exception("Task execution failed", e.getCause());
        } catch (InterruptedException e) {
            // Restore interrupt status and report interruption
            Thread.currentThread().interrupt();
            throw new Exception("Task was interrupted");
