            );
        }
    }

    /**
     * Reads the file and returns its lines after performing validation.
     *
     * @param file the file to read
     * @return a list of lines from the file
     * @throws IllegalArgumentException if the file is null
     * @throws IOException if the file does not exist or cannot be read
     */
    public static List<String> readFileWithValidation(File file) throws IOException {
        if (file == null) {
            throw new IllegalArgumentException("File must not be null.");
        }
        if (!file.exists() || !file.canRead()) {
            throw new IOException("File does not exist or cannot be read: " + file.getPath());
        }

        List<String> lines = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                lines.add(line);
            }
        }
        return lines;
    }

    /**
     * Analyzes the content of the given file and returns statistics.
     *
     * @param file the file to analyze
     * @return a FileStats object containing the statistics
     * @throws IOException if the file cannot be read
     */
    public static FileStats analyzeFileContent(File file) throws IOException {
        List<String> lines = readFileWithValidation(file);

        int lineCount = lines.size();
        int characterCount = 0;
        int wordCount = 0;

        for (String line : lines) {
            characterCount += line.length();

            String trimmed = line.trim();
            if (!trimmed.isEmpty()) {
                // Split on one or more whitespace characters
                wordCount += trimmed.split("\\s+").length;
            }
        }

        double averageWordsPerLine = lineCount > 0 ? (double) wordCount / lineCount : 0.0;

        return new FileStats(lineCount, wordCount, characterCount, averageWordsPerLine);
    }

    /**
     * Writes the given content to the specified file path.
     *
     * @param filePath the path of the file to write to
     * @param content  the content to write
     * @param append   if true, append to the file; otherwise overwrite
     * @throws IOException if an I/O error occurs
     */
    public static void writeToFile(String filePath, String content, boolean append) throws IOException {
        Path path = Paths.get(filePath);
        Path parent = path.getParent();
        if (parent != null) {
            Files.createDirectories(parent);
        }

        try (FileWriter writer = new FileWriter(path.toFile(), append)) {
            writer.write(content);
        }
    }
}
