import java.util.ArrayList;
import java.util.List;

/**
 * Basic implementation of a TreePathAnalyzer that finds the longest path
 * (diameter) in an N‑ary tree. The longest path may start and end at any
 * two nodes in the tree, not necessarily passing through the root.
 */
public class TreePathAnalyzer {

    /** Root of the N‑ary tree */
    private final Node root;

    /** Holds the longest path found during DFS */
    private List<Node> bestPath = new ArrayList<>();

    public TreePathAnalyzer(Node root) {
        this.root = root;
    }

    /**
     * Returns the longest path in the tree as a list of nodes.
     * If the tree is empty (root is null), an empty list is returned.
     */
    public List<Node> findLongestPath() {
        if (root == null) {
            return new ArrayList<>(); // empty tree
        }
        dfs(root);
        return bestPath;
    }

    /**
     * Depth‑first search that returns the deepest path from the current node
     * to a leaf. While traversing, it updates {@code bestPath} with the
     * longest path found so far.
     */
    private List<Node> dfs(Node node) {
        // Collect deepest paths from all children
        List<List<Node>> childPaths = new ArrayList<>();
        for (Node child : node.children) {
            childPaths.add(dfs(child));
        }

        // Identify the two longest child paths
        List<Node> best1 = null;
        List<Node> best2 = null;
        for (List<Node> path : childPaths) {
            if (best1 == null || path.size() > best1.size()) {
                best2 = best1;
                best1 = path;
            } else if (best2 == null || path.size() > best2.size()) {
                best2 = path;
            }
        }

        // Candidate path that starts at this node and goes down to the deepest leaf
        if (best1 != null) {
            List<Node> pathThroughNode = new ArrayList<>();
            pathThroughNode.add(node);
            pathThroughNode.addAll(best1);
            if (pathThroughNode.size() > bestPath.size()) {
                bestPath = pathThroughNode;
            }
        }

        // Candidate path that goes from one deepest leaf, up to this node,
        // and down to another deepest leaf
        if (best1 != null && best2 != null) {
            List<Node> combined = new ArrayList<>();

            // Add leaf from best1 up to this node (reverse order)
            for (int i = best1.size() - 1; i >= 0; i--) {
                combined.add(best1.get(i));
            }

            // Add this node
            combined.add(node);

            // Add leaf from best2 down from this node (skip the first node to avoid duplication)
            for (int i = 1; i < best2.size(); i++) {
                combined.add(best2.get(i));
            }

            if (combined.size() > bestPath.size()) {
                bestPath = combined;
            }
        }

        // Return the deepest path from this node to a leaf
        if (best1 != null) {
            List<Node> deepest = new ArrayList<>();
            deepest.add(node);
            deepest.addAll(best1);
            return deepest;
        } else {
            // Leaf node
            List<Node> leafPath = new ArrayList<>();
            leafPath.add(node);
            return leafPath;
        }
    }

    /** Nested Node class representing a node in an N‑ary tree */
    public static class Node {
        public final int data;
        public final List<Node> children = new ArrayList<>();

        public Node(int data) {
            this.data = data;
        }

        public void addChild(Node child) {
            children.add(child);
        }

        @Override
        public String toString() {
            return Integer.toString(data);
        }
    }

