import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * TreePathAnalyzer finds the longest path (diameter) in an N‑ary tree.
 * The algorithm runs in O(N) time, visiting each node exactly once.
 */
public class TreePathAnalyzer {

    /** Root of the N‑ary tree */
    private final Node root;

    /** Length of the longest path found so far (number of nodes) */
    private int bestDiameterLength = 0;

    /** Endpoints of the longest path */
    private Node bestEndpoint1 = null;
    private Node bestEndpoint2 = null;

    public TreePathAnalyzer(Node root) {
        this.root = root;
    }

    /**
     * Returns the longest path in the tree as a list of nodes.
     * If the tree is empty (root is null), an empty list is returned.
     */
    public List<Node> findLongestPath() {
        if (root == null) {
            return new ArrayList<>(); // empty tree
        }

        // Run DFS to compute depths, deepest leaves, and diameter
        dfs(root);

        // Reconstruct the path from the two endpoints
        return buildPath(bestEndpoint1, bestEndpoint2);
    }

    /**
     * Depth‑first search that returns the depth of the subtree rooted at {@code node}
     * (number of nodes from {@code node} to the deepest leaf, inclusive).
     * During traversal it updates {@code bestDiameterLength} and the endpoints.
     */
    private int dfs(Node node) {
        if (node.children.isEmpty()) {
            // Leaf node: depth = 1, deepest leaf is itself
            node.deepestLeaf = node;
            return 1;
        }

        int topDepth1 = 0; // longest child depth
        int topDepth2 = 0; // second longest child depth
        Node topChild1 = null;
        Node topChild2 = null;

        for (Node child : node.children) {
            int childDepth = dfs(child) + 1; // depth from current node to deepest leaf via this child

            if (childDepth > topDepth1) {
                topDepth2 = topDepth1;
                topChild2 = topChild1;
                topDepth1 = childDepth;
                topChild1 = child;
            } else if (childDepth > topDepth2) {
                topDepth2 = childDepth;
                topChild2 = child;
            }
        }

        // The deepest leaf in this subtree is the deepest leaf of the child with max depth
        node.deepestLeaf = topChild1.deepestLeaf;

        // Path that goes through this node (using up to two deepest children)
        int pathThroughNode = topDepth1 + topDepth2 + 1; // +1 for the current node

        if (pathThroughNode > bestDiameterLength) {
            bestDiameterLength = pathThroughNode;
            if (topChild2 != null) {
                // Two children: endpoints are deepest leaves of both children
                bestEndpoint1 = topChild1.deepestLeaf;
                bestEndpoint2 = topChild2.deepestLeaf;
            } else {
                // Only one child: endpoints are current node and deepest leaf of that child
                bestEndpoint1 = node;
                bestEndpoint2 = topChild1.deepestLeaf;
            }
        }

        return topDepth1 + 1; // depth from this node to deepest leaf
    }

    /**
     * Builds the path between two nodes using parent pointers.
     */
    private List<Node> buildPath(Node a, Node b) {
        if (a == null || b == null) {
            return new ArrayList<>();
        }

        // Find lowest common ancestor (LCA) by walking up from one endpoint
        Set<Node> ancestors = new HashSet<>();
        Node cur = a;
        while (cur != null) {
            ancestors.add(cur);
            cur = cur.parent;
        }

        Node lca = null;
        cur = b;
        while (cur != null) {
            if (ancestors.contains(cur)) {
                lca = cur;
                break;
            }
            cur = cur.parent;
        }

        // Build path from a up to (but not including) LCA
        List<Node> path = new ArrayList<>();
        cur = a;
        while (cur != lca) {
            path.add(cur);
            cur = cur.parent;
        }

        // Add LCA
        path.add(lca);

        // Build path from b up to (but not including) LCA, then reverse
        List<Node> temp = new ArrayList<>();
        cur = b;
        while (cur != lca) {
            temp.add(cur);
            cur = cur.parent;
        }
        for (int i = temp.size() - 1; i >= 0; i--) {
            path.add(temp.get(i));
        }

        return path;
    }

    /** Nested Node class representing a node in an N‑ary tree */
    public static class Node {
        public final int data;
        public final List<Node> children = new ArrayList<>();
        public Node parent = null;          // parent pointer for path reconstruction
        public Node deepestLeaf = null;     // deepest leaf in this subtree

        public Node(int data) {
            this.data = data;
        }

        public void addChild(Node child) {
            child.parent = this;
            children.add(child);
        }

        @Override
        public String toString() {
            return Integer.toString(data);
        }
    }

    // Example usage (uncomment to test)
    // public static void main(String[] args) {
    //     Node root = new Node(1);
    //     Node a = new Node(2);
    //     Node b = new Node(3);
    //     Node c = new Node(4);
    //     Node d = new Node(5);
    //     Node e = new Node(6);
    //     root.addChild(a);
    //     root.addChild(b);
    //     a.addChild(c);
