        Map<String, String> result = new HashMap<>();

        String pattern = null;
        String type = null;
        String description = null;

        if ("literal".equals(patternType)) {
            String text = parameters.get("text");
            pattern = escapeRegexChars(text);
            type = "literal";
            description = "Literal text";
        } else if ("characterClass".equals(patternType)) {
            String classParam = parameters.get("class");
            switch (classParam != null ? classParam : "") {
                case "digit":
                    pattern = "\\\\d";
                    break;
                case "lowercase":
                    pattern = "[a-z]";
                    break;
                case "uppercase":
                    pattern = "[A-Z]";
                    break;
                default:
                    pattern = ".";
                    break;
            }
            type = "characterClass";
            description = "Character class";
        } else if ("boundary".equals(patternType)) {
            String typeParam = parameters.get("type");
            switch (typeParam) {
                case "start-line":
                    pattern = "^";
                    break;
                case "end-line":
                    pattern = "$";
                    break;
                case "word":
                    pattern = "\\\\b";
                    break;
                case "non-word":
                    pattern = "\\\\B";
