import java.util.HashMap;
import java.util.Map;

/**
 * A simplified simulator for a web fragment that demonstrates URL handling,
 * fragment visibility, network checks, and intent‑extra management.
 */
class WebFragmentSimulator {
    private String currentUrl;
    private boolean isFragmentVisible;
    private Map<String, String> intentExtras;
    private boolean networkAvailable;

    public WebFragmentSimulator() {
        this.currentUrl = null;
        this.isFragmentVisible = false;
        this.intentExtras = new HashMap<>();
        this.networkAvailable = false;
    }

    /**
     * Appends the application version and OS parameters to the given URL.
     *
     * @param url The original URL.
     * @return The URL with appended parameters.
     */
    private String appendUrlParameters(String url) {
        if (url == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder(url);
        if (url.contains("?")) {
