import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.atomic.AtomicInteger;

class PollingQueue<T> {
    private final Queue<T> queue;
    private final AtomicInteger pollingCount;
    private final int maxPollingAttempts;

    public PollingQueue(int maxPollingAttempts) {
        this.queue = new LinkedList<>();
        this.pollingCount = new AtomicInteger(0);
        this.maxPollingAttempts = maxPollingAttempts;
    }

    /** Adds an element to the queue and notifies waiting threads. */
    public synchronized void enqueue(T element) {
        queue.add(element);
        notifyAll(); // wake up threads waiting for an element
    }

    /**
     * Retrieves and removes the head of the queue.
     * Increments the polling counter and enforces the maximum polling attempts.
     */
    public synchronized T poll() {
        int attempts = pollingCount.incrementAndGet();
        if (attempts > maxPollingAttempts) {
            throw new IllegalStateException(
                "Maximum polling attempts (" + maxPollingAttempts + ") exceeded."
            );
        }
        return queue.poll();
    }

    /**
     * Waits up to {@code timeoutMs} milliseconds for an element to become available.
     * If an element appears, it is removed from the queue and returned.
     * If the timeout expires while the queue remains empty, {@code null} is returned.
     */
    public synchronized T waitForElement(long timeoutMs) {
        if (timeoutMs < 0) {
            throw new IllegalArgumentException("timeoutMs must be non‑negative");
        }

        long deadline = System.nanoTime() + timeoutMs * 1_000_000L;
        while (queue.isEmpty()) {
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0) {
                return null; // timeout elapsed
            }
            try {
                long millis = remaining / 1_000_000L;
                int nanos = (int) (remaining % 1_000_000L);
                wait(millis, nanos);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); // restore interrupt status
                return null;
            }
        }
        return queue.poll(); // element is now available
    }

    public int getPollingCount() {
        return pollingCount.get();
    }

    public int getMaxPollingAttempts() {
        return maxPollingAttempts;
    }
}

public class Main {
    public static void main(String[] args) {
        // Queue allows at most 3 polling attempts
        PollingQueue<String> pq = new PollingQueue<>(3);

        // Enqueue some elements
        pq.enqueue("first");
        pq.enqueue("second");

        // Poll normally
        System.out.println("poll(): " + pq.poll()); // first
        System.out.println("poll(): " + pq.poll()); // second

        // Attempt to poll beyond the limit
        try {
            System.out.println("poll(): " + pq.poll()); // third attempt (allowed)
            System.out.println("poll(): " + pq.poll()); // fourth attempt (exceeds limit)
        } catch (IllegalStateException e) {
            System.err.println("Error: " + e.getMessage());
        }

        // Demonstrate waitForElement with timeout
        Thread producer = new Thread(() -> {
            try {
                Thread.sleep(500); // simulate delay
                pq.enqueue("delayed");
                System.out.println("Producer: enqueued 'delayed'");
            } catch (InterruptedException ignored) {}
        });

        Thread consumer = new Thread(() -> {
            System.out.println("Consumer: waiting for element (timeout 2000ms)");
            String element = pq.waitForElement(2000);
            if (element != null) {
                System.out.println("Consumer: received '" + element + "'");
            } else {
                System.out.println("Consumer: timeout, no element received");
            }
        });

        producer.start();
        consumer.start();

        try {
            producer.join();
            consumer.join();
        } catch (InterruptedException ignored) {}

        System.out.println("Total polling attempts: " + pq.getPollingCount());
    }
}

