     * Waits up to {@code timeoutMs} milliseconds for an element to become available.
     * If an element appears, it is removed from the queue and returned.
     * If the timeout expires while the queue remains empty, {@code null} is returned.
     */
    public synchronized T waitForElement(long timeoutMs) {
        if (timeoutMs < 0) {
            throw new IllegalArgumentException("timeoutMs must be non‑negative");
