    public static void main(String[] args) {
        // Queue allows at most 3 polling attempts
        PollingQueue<String> pq = new PollingQueue<>(3);

        // Enqueue some elements
        pq.enqueue("first");
        pq.enqueue("second");

        // Poll normally
        System.out.println("poll(): " + pq.poll()); // first
        System.out.println("poll(): " + pq.poll()); // second

        // Attempt to poll beyond the limit
        try {
            System.out.println("poll(): " + pq.poll()); // third attempt (allowed)
            System.out.println("poll(): " + pq.poll()); // fourth attempt (exceeds limit)
        } catch (IllegalStateException e) {
            System.err.println("Error: " + e.getMessage());
        }

        // Reset the polling counter
        pq.resetPollingCount();
        System.out.println("Polling count after reset: " + pq.getPollingCount());

        // Demonstrate waitForElement with timeout
        Thread producer = new Thread(() -> {
            try {
                Thread.sleep(500); // simulate delay
                pq.enqueue("delayed");
                System.out.println("Producer: enqueued 'delayed'");
            } catch (InterruptedException ignored) {}
        });

        Thread consumer = new Thread(() -> {
            System.out.println("Consumer: waiting for element (timeout 2000ms)");
            String element = pq.waitForElement(2000);
            if (element != null) {
                System.out.println("Consumer: received '" + element + "'");
            } else {
                System.out.println("Consumer: timeout, no element received");
            }
        });

        producer.start();
        consumer.start();

        try {
            producer.join();
            consumer.join();
        } catch (InterruptedException ignored) {}

        System.out.println("Total polling attempts: " + pq.getPollingCount());
    }
}
