import java.util.HashMap;
import java.util.Map;
import java.util.ArrayList;
import java.util.List;

class AgricultureDataValidator {

    public Map<String, Object> validateAndProcessData(String ph, String humidity,
                                                      String fertilizer, String temperature,
                                                      String irrigation) {
        Map<String, Object> result = new HashMap<>();
        List<String> errors = new ArrayList<>();

        // Validate pH
        if (ph == null || ph.trim().isEmpty()) {
            errors.add("pH debe ser un número válido.");
        } else {
            try {
                double phValue = Double.parseDouble(ph.trim());
                if (phValue < 0 || phValue > 14) {
                    errors.add("pH incorrecto, debe estar entre 0 y 14.");
                }
            } catch (NumberFormatException e) {
                errors.add("pH debe ser un número válido.");
            }
        }

        // Validate humidity
        if (humidity == null || humidity.trim().isEmpty()) {
            errors.add("Humedad debe ser un número válido.");
        } else {
            try {
                double humValue = Double.parseDouble(humidity.trim());
                if (humValue < 0 || humValue > 100) {
                    errors.add("Humedad incorrecta, debe estar entre 0 y 100.");
                }
            } catch (NumberFormatException e) {
                errors.add("Humedad debe ser un número válido.");
            }
        }

        // Validate fertilizer
        if (fertilizer == null || fertilizer.trim().isEmpty()) {
            errors.add("Abono debe ser un número válido.");
        } else {
            try {
                double fertValue = Double.parseDouble(fertilizer.trim());
                if (fertValue < 0 || fertValue > 100) {
                    errors.add("Abono incorrecto, debe estar entre 0 y 100.");
                }
            } catch (NumberFormatException e) {
                errors.add("Abono debe ser un número válido.");
            }
        }

        // Validate temperature
        if (temperature == null || temperature.trim().isEmpty()) {
            errors.add("Temperatura debe ser un número válido.");
        } else {
            try {
                double tempValue = Double.parseDouble(temperature.trim());
                if (tempValue < -50 || tempValue > 100) {
                    errors.add("Temperatura fuera de rango (-50 a 100°C).");
                }
            } catch (NumberFormatException e) {
                errors.add("Temperatura debe ser un número válido.");
            }
        }

        // Validate irrigation
        if (irrigation == null || irrigation.trim().isEmpty()
                || !(irrigation.trim().equalsIgnoreCase("ON")
                || irrigation.trim().equalsIgnoreCase("OFF"))) {
            errors.add("Riego debe ser ''ON'' u ''OFF''.");
        }

        if (errors.isEmpty()) {
            result.put("isValid", true);
            String processed = String.format(
                    "ph=%s&humedad=%s&abono=%s&temperatura=%s&riego=%s",
                    ph.trim(),
                    humidity.trim(),
                    fertilizer.trim(),
                    temperature.trim(),
                    irrigation.trim().toUpperCase()
            );
            result.put("processedData", processed);
        } else {
