import java.util.Date;
import java.util.HashMap;
import java.util.Map;

/** Simple user representation. */
class User {
    private final String id;
    private final String name;
    private final String ip;

    public User(String id, String name, String ip) {
        this.id = id;
        this.name = name;
        this.ip = ip;
    }

    public String getId()   { return id; }
    public String getName() { return name; }
    public String getIp()   { return ip; }
}

/** Token representation with expiration and status. */
class Token {
    private final String tokenString;   // e.g. "user192.168.1.1"
    private final Date   expiration;   // when the token expires
    private final int    status;        // 1 = active, other = invalid
    private final String userId;        // id of the user this token belongs to

    public Token(String tokenString, Date expiration, int status, String userId) {
        this.tokenString = tokenString;
        this.expiration  = expiration;
        this.status      = status;
        this.userId      = userId;
    }

    public String getTokenString() { return tokenString; }
    public Date   getExpiration()  { return expiration; }
    public int    getStatus()      { return status; }
    public String getUserId()      { return userId; }
}

/** Core validator that checks token validity, expiration, status, IP and user existence. */
class AuthTokenValidator {
    // In‑memory storage for tokens and users
    private final Map<String, Token> tokenDatabase;
    private final Map<String, User>  userDatabase;

    public AuthTokenValidator() {
        tokenDatabase = new HashMap<>();
        userDatabase  = new HashMap<>();

        // Example user
        User alice = new User("user192.168.1.1", "Alice", "192.168.1.1");
        userDatabase.put(alice.getId(), alice);

        // Example token: valid for 1 hour, status 1 (active)
        Token token = new Token(
                "user192.168.1.1",
                new Date(System.currentTimeMillis() + 3600_000), // +1 hour
                1,
                alice.getId()
        );
        tokenDatabase.put(token.getTokenString(), token);
    }

    public Map<String, Object> validateToken(String tokenStr, String clientIp) {
        Map<String, Object> result = new HashMap<>();

        // 1. Basic checks
        if (tokenStr == null || tokenStr.isEmpty()) {
            result.put("valid", false);
            result.put("message", "Token is empty");
            return result;
        }

        if (!tokenStr.contains("user")) {
            result.put("valid", false);
            result.put("message", "Token format invalid");
            return result;
        }

        // 2. Token existence
        Token token = tokenDatabase.get(tokenStr);
        if (token == null) {
            result.put("valid", false);
            result.put("message", "Token not found");
            return result;
        }

        // 3. Expiration check
        if (token.getExpiration().before(new Date())) {
            result.put("valid", false);
            result.put("message", "Token expired");
            return result;
        }

        // 4. Status check
        if (token.getStatus() != 1) {
            result.put("valid", false);
            result.put("message", "Token invalid");
            return result;
        }

        // 5. User existence
        User user = userDatabase.get(token.getUserId());
        if (user == null) {
            result.put("valid", false);
            result.put("message", "User not found");
            return result;
        }

        // 6. IP extraction and comparison
        int userIndex = tokenStr.indexOf("user");
        String ipInToken = tokenStr.substring(userIndex + "user".length());
        if (!ipInToken.equals(clientIp)) {
            result.put("valid", false);
            result.put("message", "IP address mismatch");
            return result;
        }

        // 7. All checks passed
        result.put("valid", true);
        result.put("message", "Validation successful");
        result.put("user", user);
        return result;
    }
}

