import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import java.util.function.Function;

class AsyncOperationManager {

    // A shared scheduler for timeout tasks
    private static final ScheduledExecutorService scheduler =
            Executors.newScheduledThreadPool(1);

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {

        // Run the task asynchronously
        CompletableFuture<T> taskFuture = CompletableFuture.supplyAsync(taskSupplier);

        // Future that will complete with the fallback value after the timeout
        CompletableFuture<T> timeoutFuture = new CompletableFuture<>();

        // Schedule the timeout completion
        ScheduledFuture<?> timeoutHandle = scheduler.schedule(
                () -> timeoutFuture.complete(fallbackValue),
                timeout,
                timeUnit);

        // The result will be the first to complete: the task or the timeout
        CompletableFuture<T> resultFuture =
                taskFuture.applyToEither(timeoutFuture, Function.identity());

        // If the task completes first, cancel the timeout scheduling
        resultFuture.whenComplete((res, ex) -> timeoutHandle.cancel(true));

        return resultFuture;
