class AsyncOperationManager {

    // Shared scheduler for timeout tasks
    private static final ScheduledExecutorService scheduler =
            Executors.newScheduledThreadPool(1);

    /**
     * Executes the supplied task asynchronously with a timeout and a retry mechanism.
     *
     * @param taskSupplier  the task to execute
     * @param timeout       the timeout value
     * @param timeUnit      the unit of the timeout
     * @param fallbackValue the value to return if all attempts fail due to timeout
     * @param maxRetries    the maximum number of retries (excluding the initial attempt)
     * @param <T>           the type of the result
     * @return a CompletableFuture that completes with the task result, the fallback value,
     *         or exceptionally with the last exception if all attempts fail due to exceptions
     */
    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return attempt(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, null);
    }

    /**
     * Recursive helper that performs a single attempt and decides whether to retry.
     *
     * @param taskSupplier  the task to execute
     * @param timeout       the timeout value
     * @param timeUnit      the unit of the timeout
     * @param fallbackValue the fallback value for timeout failures
     * @param remainingRetries number of retries left
     * @param lastException the last exception encountered (used when all attempts fail due to exceptions)
     * @param <T>           the type of the result
     * @return a CompletableFuture representing the outcome of this attempt or a retry
     */
    private <T> CompletableFuture<T> attempt(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int remainingRetries,
            Throwable lastException) {

        // Asynchronously execute the task
        CompletableFuture<T> taskFuture = CompletableFuture.supplyAsync(taskSupplier);

        // Future that will complete with the fallback after the timeout
        CompletableFuture<T> timeoutFuture = new CompletableFuture<>();
        ScheduledFuture<?> timeoutHandle = scheduler.schedule(
                () -> timeoutFuture.complete(fallbackValue),
                timeout,
                timeUnit);

        // Flag to indicate whether the attempt timed out
        boolean[] timedOut = {false};

        // Capture any exception thrown by the task
        AtomicReference<Throwable> taskException = new AtomicReference<>();

        // If the task completes normally, cancel the timeout and complete the result
        taskFuture.whenComplete((res, ex) -> {
            if (ex == null) {
                timeoutHandle.cancel(true);
                resultFuture.complete(res);
            } else {
                taskException.set(ex);
            }
        });

        // If the timeout occurs, cancel the task and complete the result with fallback
        timeoutFuture.whenComplete((res, ex) -> {
            timedOut[0] = true;
            taskFuture.cancel(true);
            resultFuture.complete(res);
        });

        // The result future that will be completed by either the task or the timeout
        CompletableFuture<T> resultFuture = new CompletableFuture<>();

        // After resultFuture completes, decide whether to retry
        return resultFuture.thenCompose(res -> {
            // Determine if this attempt failed due to timeout or exception
            boolean timeoutOccurred = timedOut[0];
            boolean exceptionOccurred = taskFuture.isCompletedExceptionally();

            // If the attempt succeeded, return the result
            if (!timeoutOccurred && !exceptionOccurred) {
                return CompletableFuture.completedFuture(res);
            }

            // If all retries are exhausted
            if (remainingRetries <= 0) {
                if (timeoutOccurred) {
                    // All attempts failed due to timeout – return fallback
                    return CompletableFuture.completedFuture(fallbackValue);
                } else {
                    // All attempts failed due to exceptions – complete exceptionally
                    Throwable ex = taskException.get();
                    CompletableFuture<T> failed = new CompletableFuture<>();
                    failed.completeExceptionally(ex);
                    return failed;
