import java.util.ArrayList;
import java.util.List;

public class CelestialSimulator {

    /** Simple 2‑D vector class. */
    public static class Vector {
        public double x, y;

        public Vector(double x, double y) {
            this.x = x;
            this.y = y;
        }

        public Vector add(Vector v) {
            return new Vector(this.x + v.x, this.y + v.y);
        }

        public Vector subtract(Vector v) {
            return new Vector(this.x - v.x, this.y - v.y);
        }

        public Vector multiply(double scalar) {
            return new Vector(this.x * scalar, this.y * scalar);
        }

        public double magnitude() {
            return Math.sqrt(x * x + y * y);
        }

        public Vector normalize() {
            double mag = magnitude();
            if (mag == 0) return new Vector(0, 0);
            return new Vector(x / mag, y / mag);
        }
    }

    /** Representation of a celestial body. */
    public static class Celestial {
        public String name;
        public double mass;
        public Vector position;
        public Vector velocity;
        public Vector acceleration;

        public Celestial(String name, double mass, Vector position,
                         Vector velocity, Vector acceleration) {
            this.name = name;
            this.mass = mass;
            this.position = position;
            this.velocity = velocity;
            this.acceleration = acceleration;
        }

        /** Create a deep copy of this celestial body. */
        public Celestial copy() {
            return new Celestial(
                this.name,
                this.mass,
                new Vector(this.position.x, this.position.y),
                new Vector(this.velocity.x, this.velocity.y),
                new Vector(this.acceleration.x, this.acceleration.y)
            );
        }
    }

    /** Gravitational constant (in SI units). */
    private static final double G = 6.67430e-11;

    /**
     * Simulate the motion of celestial bodies.
     *
     * @param bodies List of celestial bodies to simulate.
     * @param dt     Time step (seconds).
     * @param steps  Number of simulation steps.
     * @return History of the simulation: a list of snapshots, each snapshot
     *         being a list of celestial bodies at that time.
     */
    public static List<List<Celestial>> simulate(
            List<Celestial> bodies, double dt, int steps) {

        List<List<Celestial>> history = new ArrayList<>();

        // Deep copy initial state
        List<Celestial> current = new ArrayList<>();
        for (Celestial b : bodies) {
            current.add(b.copy());
        }
        history.add(current);

        for (int step = 0; step < steps; step++) {
            int n = current.size();

            // Reset accelerations
            for (Celestial b : current) {
                b.acceleration = new Vector(0, 0);
