    private void postorderRec(Node root, List<Integer> result) {
        if (root != null) {
            postorderRec(root.left, result);   // left
            postorderRec(root.right, result);  // right
            result.add(root.value);            // root
        }
    }

    /* ---------- Removal ---------- */
    public void remove(int value) {
        root = removeRec(root, value);
    }

    private Node removeRec(Node root, int value) {
        if (root == null) {
            return null; // value not found
        }

        if (value < root.value) {
            root.left = removeRec(root.left, value);
        } else if (value > root.value) {
            root.right = removeRec(root.right, value);
        } else { // found the node to remove
            // Case 1: no children
            if (root.left == null && root.right == null) {
                return null;
            }
            // Case 2: one child
            if (root.left == null) {
                return root.right;
            }
            if (root.right == null) {
                return root.left;
            }
            // Case 3: two children
            // Find the smallest value in the right subtree
            Node minNode = findMinNode(root.right);
            root.value = minNode.value;
            // Remove the duplicate min node from the right subtree
            root.right = removeRec(root.right, minNode.value);
        }
        return root;
    }

    /* ---------- Contains ---------- */
    public boolean contains(int value) {
        return containsRec(root, value);
    }

    private boolean containsRec(Node root, int value) {
        if (root == null) {
            return false;
        }
        if (value == root.value) {
            return true;
        }
        return value < root.value
                ? containsRec(root.left, value)
                : containsRec(root.right, value);
    }

    /* ---------- Find Min ---------- */
    public int findMin() {
        if (root == null) {
            throw new IllegalStateException("Tree is empty");
        }
        return findMinNode(root).value;
    }

    private Node findMinNode(Node node) {
        while (node.left != null) {
            node = node.left;
        }
        return node;
    }

    /* ---------- Find Max ---------- */
    public int findMax() {
        if (root == null) {
            throw new IllegalStateException("Tree is empty");
        }
        return findMaxNode(root).value;
    }

    private Node findMaxNode(Node node) {
        while (node.right != null) {
            node = node.right;
        }
        return node;
    }

    /* ---------- Height ---------- */
    public int height() {
        return heightRec(root);
    }

    private int heightRec(Node root) {
        if (root == null) {
            return -1; // empty tree
        }
        int leftHeight = heightRec(root.left);
        int rightHeight = heightRec(root.right);
        return 1 + Math.max(leftHeight, rightHeight);
    }
}
