import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;

public class FileOperationsManager {

    /**
     * Writes the given list of strings to the specified file.
     *
     * @param filePath the path of the file to write to
     * @param lines    the list of strings to write, each as a separate line
     * @param append   if true, the content will be appended to the file;
     *                 if false, the file will be overwritten
     * @return {@code true} if the operation succeeds, {@code false} otherwise
     */
    public boolean writeToFile(String filePath, List<String> lines, boolean append) {
        if (filePath == null || lines == null) {
            return false;
        }

        Path path = Paths.get(filePath);
        try {
            // Ensure parent directories exist
            Path parent = path.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }

            // Determine the appropriate open options
            OpenOption[] options = append
                    ? new OpenOption[]{StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.APPEND}
                    : new OpenOption[]{StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING};

            // Write lines to the file using UTF-8 encoding
            try (BufferedWriter writer = Files.newBufferedWriter(path, StandardCharsets.UTF_8, options)) {
                for (String line : lines) {
                    writer.write(line);
                    writer.newLine();
                }
            }
            return true;
        } catch (IOException e) {
            // Log the exception if needed
            return false;
        }
    }
}

