public class AdvancedTileCalculator {

    /**
     * Calculates the tile configuration based on the presence of neighboring tiles.
     *
     * @param neighbors a set containing any of the strings "UP", "DOWN", "LEFT", "RIGHT"
     * @return a TileConfiguration instance:
     *         - (0, 0) if no neighbors are present,
     *         - (5, 2) if only UP and DOWN neighbors are present,
     *         - (1, 2) if only LEFT and RIGHT neighbors are present,
     *         - (1, 0) if only UP is present,
     *         - (0, 2) if only DOWN is present,
     *         - (5, 1) if only LEFT is present,
     *         - (5, 0) if only RIGHT is present,
     *         - (1, 1) for all other configurations
     */
    public TileConfiguration calculateAdvancedTile(Set<String> neighbors) {
        if (neighbors == null || neighbors.isEmpty()) {
            return new TileConfiguration(0, 0);
        }

        boolean hasUp = neighbors.contains("UP");
        boolean hasDown = neighbors.contains("DOWN");
        boolean hasLeft = neighbors.contains("LEFT");
        boolean hasRight = neighbors.contains("RIGHT");

        // Vertical passage: only UP and DOWN
        if (hasUp && hasDown && !hasLeft && !hasRight && neighbors.size() == 2) {
            return new TileConfiguration(5, 2);
        }

        // Horizontal passage: only LEFT and RIGHT
        if (hasLeft && hasRight && !hasUp && !hasDown && neighbors.size() == 2) {
            return new TileConfiguration(1, 2);
        }

        // Dead ends: exactly one neighbor
        if (neighbors.size() == 1) {
            if (hasUp) {
                return new TileConfiguration(1, 0);
            }
            if (hasDown) {
                return new TileConfiguration(0, 2);
            }
            if (hasLeft) {
                return new TileConfiguration(5, 1);
            }
            if (hasRight) {
                return new TileConfiguration(5, 0);
            }
        }

        // Default configuration
        return new TileConfiguration(1, 1);
