    public static void main(String[] args) {
        PlayerRegistry registry = new PlayerRegistry();

        System.out.println("Register player1: " + registry.registerPlayer("player1")); // true
        System.out.println("Register player1 again: " + registry.registerPlayer("player1")); // false
        System.out.println("Register player2: " + registry.registerPlayer("player2")); // true

        // Display all registered players
        for (PlayerInfo p : registry.getAllPlayers()) {
            System.out.println("Player ID: " + p.getPlayerId() + ", Score: " + p.getScore());
        }
    }
}
