import java.util.Collection;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

public class PlayerInfo {
    private final String playerId;
    private final AtomicInteger score = new AtomicInteger(0);
    private final AtomicBoolean active = new AtomicBoolean(true);

    public PlayerInfo(String playerId) {
        this.playerId = playerId;
    }

    public String getPlayerId() {
        return playerId;
    }

    public int getScore() {
        return score.get();
    }

    public void addScore(int delta) {
        score.addAndGet(delta);
    }

    public boolean isActive() {
        return active.get();
    }

    public void deactivate() {
        active.set(false);
    }
}

public class PlayerRegistry {
    // Thread‑safe storage for players
    private final ConcurrentMap<String, PlayerInfo> players = new ConcurrentHashMap<>();
    // Queue of active player IDs
    private final ConcurrentLinkedQueue<String> activeQueue = new ConcurrentLinkedQueue<>();

    /**
     * Registers a new player with the given unique ID.
     * The method is synchronized to guarantee atomicity of the check‑and‑put operation.
     *
     * @param playerId the unique identifier for the player
     * @return true if registration succeeded, false if the ID already exists
     */
    public synchronized boolean registerPlayer(String playerId) {
        if (players.containsKey(playerId)) {
            return false; // duplicate registration rejected
        }
        PlayerInfo p = new PlayerInfo(playerId);
        players.put(playerId, p);
        activeQueue.add(playerId);
        return true;
    }

    /**
     * Removes a player from the active queue and marks them as inactive.
     *
     * @param playerId the ID of the player to remove
     * @return true if the player existed and was removed, false otherwise
     */
    public boolean removePlayer(String playerId) {
        PlayerInfo p = players.get(playerId);
        if (p == null || !p.isActive()) {
            return false;
        }
        p.deactivate();
        activeQueue.remove(playerId); // O(n) but acceptable for small queues
        return true;
    }

    /**
     * Updates the score of an existing active player.
     *
     * @param playerId the ID of the player
     * @param delta    the amount to add (can be negative)
     * @return true if the score was updated, false if the player does not exist or is inactive
     */
    public boolean updateScore(String playerId, int delta) {
        PlayerInfo p = players.get(playerId);
        if (p == null || !p.isActive()) {
            return false;
        }
        p.addScore(delta);
        return true;
    }

    public PlayerInfo getPlayer(String playerId) {
        return players.get(playerId);
    }

    public Collection<PlayerInfo> getAllPlayers() {
        return players.values();
    }

    public Collection<String> getActiveQueue() {
        return activeQueue;
    }
}

public class Main {
    public static void main(String[] args) {
        PlayerRegistry registry = new PlayerRegistry();

        System.out.println("Register player1: " + registry.registerPlayer("player1")); // true
        System.out.println("Register player2: " + registry.registerPlayer("player2")); // true
        System.out.println("Register player1 again: " + registry.registerPlayer("player1")); // false

        System.out.println("Update score for player1 (+10): " + registry.updateScore("player1", 10)); // true
        System.out.println("Update score for player2 (-5): " + registry.updateScore("player2", -5)); // true
        System.out.println("Update score for non-existent player3: " + registry.updateScore("player3", 5)); // false

        System.out.println("Remove player1: " + registry.removePlayer("player1")); // true
        System.out.println("Remove player1 again: " + registry.removePlayer("player1")); // false

        // Attempt to update score of removed player
        System.out.println("Update score for removed player1 (+3): " + registry.updateScore("player1", 3)); // false

        // Display all registered players
        System.out.println("\nAll players:");
        for (PlayerInfo p : registry.getAllPlayers()) {
            System.out.println("Player ID: " + p.getPlayerId()
                    + ", Score: " + p.getScore()
                    + ", Active: " + p.isActive());
        }

        // Display active queue
        System.out.println("\nActive queue:");
        for (String id : registry.getActiveQueue()) {
            System.out.println(id);
        }
    }
}
