import java.io.PrintStream;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Stores basic player information.
 */
class PlayerInfo {
    private final String playerId;
    private final AtomicInteger score = new AtomicInteger(0);
    private final AtomicBoolean active = new AtomicBoolean(true);

    public PlayerInfo(String playerId) {
        this.playerId = playerId;
    }

    public String getPlayerId() {
        return playerId;
    }

    public int getScore() {
        return score.get();
    }

    public void addScore(int delta) {
        score.addAndGet(delta);
    }

    public boolean isActive() {
        return active.get();
    }

    public void deactivate() {
        active.set(false);
    }
}

/**
 * Thread‑safe registry that manages players, turn order, rankings, and output streams.
 */
class PlayerRegistry {
    // Map of all players (active or inactive)
    private final ConcurrentMap<String, PlayerInfo> players = new ConcurrentHashMap<>();
    // Queue of active player IDs for round‑robin turns
    private final ConcurrentLinkedQueue<String> activeQueue = new ConcurrentLinkedQueue<>();
    // Thread‑safe list of output streams
    private final CopyOnWriteArrayList<PrintStream> outputStreams = new CopyOnWriteArrayList<>();

    /**
     * Registers a new player with a unique ID.
     *
     * @param playerId the unique identifier
     * @return true if registration succeeded, false if ID already exists
     */
    public synchronized boolean registerPlayer(String playerId) {
        if (players.containsKey(playerId)) {
            return false; // duplicate registration rejected
        }
        PlayerInfo p = new PlayerInfo(playerId);
        players.put(playerId, p);
        activeQueue.add(playerId);
        return true;
    }

    /**
     * Removes a player from the active queue and marks them inactive.
     *
     * @param playerId the ID to remove
     * @return true if the player existed and was removed, false otherwise
     */
    public boolean removePlayer(String playerId) {
        PlayerInfo p = players.get(playerId);
        if (p == null || !p.isActive()) {
            return false;
        }
        p.deactivate();
        activeQueue.remove(playerId); // O(n) but acceptable for small queues
        return true;
    }

    /**
     * Updates the score of an existing active player.
     *
     * @param playerId the ID of the player
     * @param delta    the amount to add (can be negative)
     * @return true if the score was updated, false if player does not exist or is inactive
     */
    public boolean updateScore(String playerId, int delta) {
        PlayerInfo p = players.get(playerId);
        if (p == null || !p.isActive()) {
            return false;
        }
        p.addScore(delta);
        return true;
    }

    /**
     * Retrieves the next active player in round‑robin order.
     * The player is moved to the back of the queue after retrieval.
     *
     * @return the next active PlayerInfo, or null if no active players exist
     */
    public synchronized PlayerInfo getNextPlayer() {
        int size = activeQueue.size();
        for (int i = 0; i < size; i++) {
            String id = activeQueue.poll();
            if (id == null) {
                break;
            }
            PlayerInfo p = players.get(id);
            if (p != null && p.isActive()) {
                activeQueue.add(id); // move to back
                return p;
            }
            // If player is inactive, skip and continue
        }
        return null; // no active players
    }

    /**
     * Returns a list of active players sorted by score in descending order.
     *
     * @return sorted list of active PlayerInfo objects
     */
    public List<PlayerInfo> getRankings() {
        List<PlayerInfo> activePlayers = new ArrayList<>();
        for (PlayerInfo p : players.values()) {
            if (p.isActive()) {
                activePlayers.add(p);
            }
        }
        activePlayers.sort(Comparator.comparingInt(PlayerInfo::getScore).reversed());
        return activePlayers;
    }

    /**
     * Adds an output stream to the registry.
     *
     * @param stream the PrintStream to add
     */
    public void addOutputStream(PrintStream stream) {
        if (stream != null) {
            outputStreams.addIfAbsent(stream);
        }
    }

    /**
     * Removes an output stream from the registry.
     *
     * @param stream the PrintStream to remove
     */
    public void removeOutputStream(PrintStream stream) {
        outputStreams.remove(stream);
    }

    /**
     * Returns a copy of the current list of output streams.
     *
     * @return a List containing all registered PrintStreams
     */
    public List<PrintStream> getOutputStreams() {
        return new ArrayList<>(outputStreams);
    }

    public PlayerInfo getPlayer(String playerId) {
        return players.get(playerId);
    }

    public Collection<PlayerInfo> getAllPlayers() {
        return players.values();
    }

    public Collection<String> getActiveQueue() {
        return activeQueue;
    }
}

/**
 * Demonstrates the player registry with turn management, rankings, and output streams.
 */
public class Main {
    public static void main(String[] args) {
        PlayerRegistry registry = new PlayerRegistry();

        // Register players
        System.out.println("Register player1: " + registry.registerPlayer("player1")); // true
        System.out.println("Register player2: " + registry.registerPlayer("player2")); // true
        System.out.println("Register player3: " + registry.registerPlayer("player3")); // true

        // Update scores
        registry.updateScore("player1", 10);
        registry.updateScore("player2", 5);
        registry.updateScore("player3", -3);

        // Turn order demonstration
        System.out.println("\nTurn order:");
        for (int i = 0; i < 6; i++) {
            PlayerInfo next = registry.getNextPlayer();
            if (next != null) {
