                        + " (Score: " + next.getScore() + ")");
            } else {
                System.out.println("Turn " + (i + 1) + ": No active players");
            }
        }

        // Rankings
        System.out.println("\nRankings:");
        List<PlayerInfo> rankings = registry.getRankings();
        int rank = 1;
        for (PlayerInfo p : rankings) {
