import java.util.HashMap;
import java.util.Map;

public class UserAuthenticator {

    // Hardcoded user database: phone number -> password
    private static final Map<String, String> userDatabase = new HashMap<>();

    // Stores verification codes for phone numbers that passed the first factor
    private final Map<String, String> verificationCodes = new HashMap<>();

    static {
        userDatabase.put("1234567890", "pass123");
        userDatabase.put("0987654321", "pass456");
    }

    /**
     * Authenticates a user based on phone number and password.
     *
     * @param phoneNumber The user's phone number.
     * @param password    The user's password.
     * @return AuthenticationResult containing status code, message, and user info.
     * @throws IllegalArgumentException if phoneNumber or password is null/empty,
     *                                  or if phoneNumber length is not exactly 10 digits.
     */
    public AuthenticationResult authenticate(String phoneNumber, String password) {
        // Input validation
        if (phoneNumber == null || phoneNumber.isEmpty()) {
            throw new IllegalArgumentException("Phone number cannot be null or empty.");
        }
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be null or empty.");
        }
        if (phoneNumber.length() != 10) {
            throw new IllegalArgumentException("Phone number must be exactly 10 digits long.");
        }

        if (!userDatabase.containsKey(phoneNumber)) {
            return new AuthenticationResult(404, "User not found.", null);
        }

        if (!userDatabase.get(phoneNumber).equals(password)) {
            return new AuthenticationResult(401, "Invalid password.", null);
        }

        // First factor succeeded – generate and store verification code
        String code = generateVerificationCode();
        verificationCodes.put(phoneNumber, code);

        return new AuthenticationResult(250, "Verification required.", phoneNumber);
    }

    /**
     * Verifies the two‑factor authentication code.
     *
     * @param phoneNumber The user's phone number.
     * @param code        The verification code provided by the user.
     * @return AuthenticationResult with status 200 on success or 401 on failure.
     */
    public AuthenticationResult verifyCode(String phoneNumber, String code) {
        if (phoneNumber == null || phoneNumber.isEmpty() || code == null || code.isEmpty()) {
            throw new IllegalArgumentException("Phone number and code cannot be null or empty.");
        }

        String storedCode = verificationCodes.get(phoneNumber);
        if (storedCode != null && storedCode.equals(code)) {
            // Successful two‑factor authentication – remove the stored code
            verificationCodes.remove(phoneNumber);
            return new AuthenticationResult(200, "Two‑factor authentication successful.", phoneNumber);
        } else {
            return new AuthenticationResult(401, "Invalid verification code.", null);
        }
    }

    /**
     * Generates a verification code. For this example it always returns '123456'.
     *
     * @return The verification code.
     */
    private String generateVerificationCode() {
        return "123456";
    }

    /**
     * Structured result of an authentication attempt.
