import java.util.Map;
import java.util.HashMap;
import java.util.Set;
import java.util.HashSet;
import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;

/**
 * Exception thrown when configuration validation fails.
 */
class ConfigurationException extends RuntimeException {
    public ConfigurationException(String message) {
        super(message);
    }
}

/**
 * Functional interface for custom validation logic.
 */
interface Validator {
    /**
     * Validates the given value.
     *
     * @param value the value to validate
     * @return true if the value passes validation, false otherwise
     */
    boolean validate(Object value);

    /**
     * Returns the error message to be used if validation fails.
     *
     * @return the error message
     */
    String getErrorMessage();
}

/**
 * Manages configuration key-value pairs with support for required keys and custom validation.
 */
public class ConfigurationManager {
    private final Map<String, Object> configMap;
    private final Set<String> requiredKeys;
    private final Map<String, List<Validator>> validators;

    /**
     * Creates a new ConfigurationManager.
     *
     * @param requiredKeys the set of keys that must be present in any loaded configuration
     * @param validators   a map of validators for specific keys
     */
    public ConfigurationManager(Set<String> requiredKeys, Map<String, List<Validator>> validators) {
        this.requiredKeys = new HashSet<>(requiredKeys);
