import java.util.HashMap;
import java.util.Map;

public class AuthService {

    // Simple User class
    public static class User {
        private final String username;

        public User(String username) {
            this.username = username;
        }

        public String getUsername() {
            return username;
        }

        @Override
        public String toString() {
            return "User{username='" + username + "'}";
        }
    }

    /**
     * Authenticates a user against a mock credential set.
     *
     * @param identifier The account name (username).
     * @param password   The password.
     * @return A map containing:
     *         - "authenticated" (Boolean)
     *         - "user" (User) if authenticated
     *         - "error" (String) if authentication fails
     */
    public static Map<String, Object> authenticateUser(String identifier, String password) {
        Map<String, Object> result = new HashMap<>();

        // Mock credentials
        final String MOCK_USERNAME = "testuser";
        final String MOCK_PASSWORD = "password";

        if (MOCK_USERNAME.equals(identifier) && MOCK_PASSWORD.equals(password)) {
            User user = new User(identifier);
            result.put("authenticated", true);
            result.put("user", user);
        } else {
            result.put("authenticated", false);
            result.put("error", "Invalid credentials");
        }

        return result;
    }

    // Demo usage
    public static void main(String[] args) {
        // Successful authentication
        Map<String, Object> success = authenticateUser("testuser", "password");
        System.out.println("Success case: " + success);

        // Failed authentication
        Map<String, Object> failure = authenticateUser("testuser", "wrongpass");
        System.out.println("Failure case: " + failure);
    }
}

