import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class AuthService {

    /* Mock user data */
    private static final String MOCK_USERNAME = "testuser";
    private static final String MOCK_EMAIL    = "test@example.com";
    private static final String MOCK_PASSWORD = "password";
    private static final Long   MOCK_ID       = 1L;

    /* Thread‑safe caches */
    private static final ConcurrentHashMap<String, User> accountCache = new ConcurrentHashMap<>();
    private static final ConcurrentHashMap<String, User> emailCache   = new ConcurrentHashMap<>();
    private static final ConcurrentHashMap<Long,   User> idCache      = new ConcurrentHashMap<>();

    /* Simple User class */
    public static class User {
        private final String username;
        private final String email;
        private String password; // mutable only via setter

        public User(String username, String email, String password) {
            this.username = username;
            this.email    = email;
            this.password = password;
        }

        public String getUsername() { return username; }
        public String getEmail()    { return email; }
        public String getPassword() { return password; }

        public void setPassword(String newPassword) { this.password = newPassword; }

        @Override
        public String toString() {
            return "User{username='" + username + "', email='" + email + "'}";
        }
    }

    /* Simulate a database lookup */
    private static User findUserInDatabase(Object identifier) {
        if (identifier instanceof String) {
            String idStr = (String) identifier;
            if (idStr.equals(MOCK_USERNAME) || idStr.equals(MOCK_EMAIL)) {
                return new User(MOCK_USERNAME, MOCK_EMAIL, MOCK_PASSWORD);
            }
        } else if (identifier instanceof Long) {
            Long idLong = (Long) identifier;
            if (idLong.equals(MOCK_ID)) {
                return new User(MOCK_USERNAME, MOCK_EMAIL, MOCK_PASSWORD);
            }
        }
        return null; // not found
    }

    /* Store a user in all caches */
    private static void cacheUser(User user) {
        accountCache.put(user.getUsername(), user);
        emailCache.put(user.getEmail(), user);
        idCache.put(MOCK_ID, user); // only one mock user
    }

    /**
     * Authenticates a user against the mock data.
     *
     * @param identifier The account name, email, or user ID.
     * @param password   The password.
