     *         - "error" (String) if authentication fails
     * @throws IllegalArgumentException if the identifier type is unsupported
     */
    public static Map<String, Object> authenticateUser(Object identifier, String password) {
        if (!(identifier instanceof String || identifier instanceof Long)) {
            throw new IllegalArgumentException("Unsupported identifier type");
        }

        User user = null;

        /* Check the appropriate cache first */
        if (identifier instanceof String) {
            String idStr = (String) identifier;
            boolean isEmail = idStr.contains("@");
            user = isEmail ? emailCache.get(idStr) : accountCache.get(idStr);
        } else { // Long
            Long idLong = (Long) identifier;
            user = idCache.get(idLong);
        }

        /* If not in cache, simulate a database lookup */
        if (user == null) {
            user = findUserInDatabase(identifier);
            if (user != null) {
                cacheUser(user);
            }
        }

        /* Build the result map */
        Map<String, Object> result = new HashMap<>();
        if (user != null && user.getPassword().equals(password)) {
            result.put("authenticated", true);
            result.put("user", user);
        } else {
            result.put("authenticated", false);
            result.put("error", "Invalid credentials");
        }
        return result;
    }

    /**
     * Updates the password for a user identified by the given identifier.
     *
     * @param identifier The account name, email, or user ID.
     * @param newPassword The new password to set.
     * @return true if the password was updated successfully, false if the user was not found.
     * @throws IllegalArgumentException if the identifier type is unsupported
     */
    public static boolean updatePassword(Object identifier, String newPassword) {
        if (!(identifier instanceof String || identifier instanceof Long)) {
            throw new IllegalArgumentException("Unsupported identifier type");
        }

        User user = null;

        /* Locate the user in the appropriate cache */
        if (identifier instanceof String) {
            String idStr = (String) identifier;
            boolean isEmail = idStr.contains("@");
            user = isEmail ? emailCache.get(idStr) : accountCache.get(idStr);
        } else { // Long
