        if (user == null) {
            user = findUserInDatabase(identifier);
            if (user != null) {
                cacheUser(user);
            }
        }

        /* If user exists, update password and refresh caches */
        if (user != null) {
            user.setPassword(newPassword);
            cacheUser(user); // refresh all caches with the updated user
            return true;
        } else {
            return false;
        }
    }

