class UserManager {
    private Map<String, User> userDatabase;
    private Map<String, String> activeSessions;

    public UserManager() {
        this.userDatabase = new HashMap<>();
        this.activeSessions = new HashMap<>();
    }

    /**
     * Registers a new user.
     *
     * @param username the desired username
     * @param password the desired password
     * @param email    the user's email address
     * @return true if registration succeeded, false if the username already exists
     */
    public boolean registerUser(String username, String password, String email) {
        if (userDatabase.containsKey(username)) {
            return false; // username already taken
        }
        User user = new User(username, password, email);
        userDatabase.put(username, user);
        return true;
    }

    /**
     * Logs in a user.
     *
     * @param username the username
     * @param password the password
     * @return a session token if login succeeded, null otherwise
     */
    public String loginUser(String username, String password) {
        User user = userDatabase.get(username);
        if (user == null) {
            return null; // user does not exist
        }
        if (!user.getPassword().equals(password)) {
            return null; // incorrect password
        }
        // Generate a simple session token
        String sessionId = UUID.randomUUID().toString();
        activeSessions.put(username, sessionId);
        return sessionId;
    }

    /**
     * Logs out a user.
     *
     * @param username the username to log out
     * @return true if logout succeeded, false if the user was not logged in
     */
    public boolean logoutUser(String username) {
        if (!activeSessions.containsKey(username)) {
            return false; // user not logged in
        }
        activeSessions.remove(username);
        return true;
    }

    /**
     * Checks if a user is currently logged in.
     *
     * @param username the username to check
     * @return true if the user has an active session, false otherwise
     */
    public boolean isUserLoggedIn(String username) {
        return activeSessions.containsKey(username);
    }

