class Category {
    private long id;
    private String name;
    private long parentId;

    public Category(long id, String name, long parentId) {
        this.id = id;
        this.name = name;
        this.parentId = parentId;
    }

    public long getId() { return id; }
    public String getName() { return name; }
    public long getParentId() { return parentId; }

    public void setId(long id) { this.id = id; }
    public void setName(String name) { this.name = name; }
    public void setParentId(long parentId) { this.parentId = parentId; }
}

/**
 * Node used to build the category tree.
 */
class CategoryNode {
    private Category category;
    private List<CategoryNode> children = new ArrayList<>();

    public CategoryNode(Category category) {
        this.category = category;
    }

    public Category getCategory() { return category; }
    public List<CategoryNode> getChildren() { return children; }

    public void addChild(CategoryNode child) {
        children.add(child);
    }
}

/**
 * Result wrapper for the list of category nodes.
 */
class CatResult {
    private List<CategoryNode> data;

    public CatResult(List<CategoryNode> data) {
        this.data = data;
    }

    public List<CategoryNode> getData() { return data; }
    public void setData(List<CategoryNode> data) { this.data = data; }
}

/**
 * Service that manages categories and builds the hierarchy.
 */
class ItemCatService {
    // Stores all categories by id
    private Map<Long, Category> categories = new HashMap<>();
    // Maps parent id to list of child categories
    private Map<Long, List<Category>> childrenMap = new HashMap<>();

    /**
     * Adds a new category.
     *
     * @param id       the unique id of the category
     * @param name     the name of the category
     * @param parentId the id of the parent category (0 for root)
     */
    public void addCategory(long id, String name, long parentId) {
        Category cat = new Category(id, name, parentId);
        categories.put(id, cat);
        childrenMap.computeIfAbsent(parentId, k -> new ArrayList<>()).add(cat);
    }

    /**
     * Builds and returns the category tree.
     *
     * @return CatResult containing the root nodes of the tree
     */
    public CatResult getItemCatList() {
        if (categories.isEmpty()) {
            return new CatResult(new ArrayList<>());
        }

        List<CategoryNode> roots = new ArrayList<>();
        // Root categories have parentId == 0
        List<Category> rootCategories = childrenMap.getOrDefault(0L, Collections.emptyList());
        for (Category rootCat : rootCategories) {
            CategoryNode rootNode = buildNode(rootCat);
            roots.add(rootNode);
        }
        return new CatResult(roots);
    }

    /**
     * Recursively builds a CategoryNode and its children.
     *
     * @param cat the category to build
     * @return the constructed CategoryNode
     */
    private CategoryNode buildNode(Category cat) {
        CategoryNode node = new CategoryNode(cat);
        List<Category> childCats = childrenMap.getOrDefault(cat.getId(), Collections.emptyList());
        for (Category child : childCats) {
            node.addChild(buildNode(child));
        }
        return node;
    }
}

