/**
 * Service that manages categories and builds the hierarchy.
 */
class ItemCatService {
    // Stores all categories by id
    private Map<Long, Category> categories = new HashMap<>();
    // Keeps the order in which root categories were added
    private List<Long> rootOrder = new ArrayList<>();

    /**
     * Adds a new category.
     *
     * @param id       the unique id of the category
     * @param name     the name of the category
     * @param parentId the id of the parent category (0 for root)
     */
    public void addCategory(long id, String name, long parentId) {
        Category cat = new Category(id, name, parentId);
        categories.put(id, cat);
        if (parentId == 0) {
            rootOrder.add(id);
        }
    }

    /**
     * Builds and returns the category tree.
     *
     * @return CatResult containing the root nodes of the tree
     */
    public CatResult getItemCatList() {
        if (categories.isEmpty()) {
            return new CatResult(new ArrayList<>());
        }

        // Determine which categories are valid (their parent exists or is root)
        Set<Long> validIds = new HashSet<>();
        for (Category cat : categories.values()) {
            if (cat.getParentId() == 0 || categories.containsKey(cat.getParentId())) {
                validIds.add(cat.getId());
            }
        }

        // Build a children map that only contains valid categories
        Map<Long, List<Category>> validChildrenMap = new LinkedHashMap<>();
        for (Category cat : categories.values()) {
            if (!validIds.contains(cat.getId())) {
                continue; // skip invalid category
            }
            validChildrenMap
                .computeIfAbsent(cat.getParentId(), k -> new ArrayList<>())
                .add(cat);
        }

        // Build the tree starting from root categories in the order they were added
        List<CategoryNode> roots = new ArrayList<>();
        for (Long rootId : rootOrder) {
            if (!validIds.contains(rootId)) {
                continue; // skip root that became invalid
            }
            Category rootCat = categories.get(rootId);
            CategoryNode rootNode = buildCategoryTree(rootCat, validChildrenMap);
            roots.add(rootNode);
        }

        return new CatResult(roots);
    }

    /**
     * Recursively builds a CategoryNode and all its descendants.
     *
     * @param cat            the category to build
     * @param childrenMap    map of parent id to list of child categories
     * @return the constructed CategoryNode with full hierarchy
     */
    private CategoryNode buildCategoryTree(Category cat, Map<Long, List<Category>> childrenMap) {
        CategoryNode node = new CategoryNode(cat);
        List<Category> childCats = childrenMap.getOrDefault(cat.getId(), Collections.emptyList());
        for (Category child : childCats) {
            node.addChild(buildCategoryTree(child, childrenMap)); // recursive call
        }
        return node;
    }
}

