public class FileHandler {

    /**
     * Handles file operations based on the provided operation type.
     *
     * @param operationType the type of operation to perform (e.g., "upload", "download", "zip")
     * @param files         the list of files to process (used for upload and zip)
     * @param targetDir     the directory where files should be uploaded or from where they should be downloaded
     * @param fileName      the name of the file to download (ignored for upload and zip)
     * @return a message indicating the result of the operation for upload,
     *         the file contents as a byte array for download,
     *         or the zip archive as a byte array for zip.
     */
    public static Object handleFileOperation(String operationType,
                                             List<Path> files,
                                             Path targetDir,
                                             String fileName) {
        if ("upload".equals(operationType)) {
            try {
                // Ensure the target directory exists
                Files.createDirectories(targetDir);

                int uploadedCount = 0;
                for (Path file : files) {
                    if (Files.exists(file) && Files.isRegularFile(file)) {
                        Path destination = targetDir.resolve(file.getFileName());
                        Files.copy(file, destination, StandardCopyOption.REPLACE_EXISTING);
                        uploadedCount++;
                    }
                }
                return uploadedCount + " file" + (uploadedCount == 1 ? "" : "s") + " uploaded";
            } catch (IOException e) {
                return "Error during upload: " + e.getMessage();
            }
        } else if ("download".equals(operationType)) {
            try {
                Path fileToRead = targetDir.resolve(fileName);
                return Files.readAllBytes(fileToRead);
            } catch (IOException e) {
                // In a real application you might throw an exception or return null
                return ("Error during download: " + e.getMessage()).getBytes();
            }
        } else if ("zip".equals(operationType)) {
            try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
                 ZipOutputStream zos = new ZipOutputStream(baos)) {

                for (Path file : files) {
                    if (Files.exists(file) && Files.isRegularFile(file)) {
                        ZipEntry entry = new ZipEntry(file.getFileName().toString());
                        zos.putNextEntry(entry);
                        Files.copy(file, zos);
                        zos.closeEntry();
                    }
                }
                zos.finish();
                return baos.toByteArray();
            } catch (IOException e) {
                // Return an empty byte array or handle the error as needed
                return new byte[0];
            }
        }

        // Unsupported operation
        return null;
    }
}

