     *         or the zip archive as a byte array for zip.
     * @throws IOException              if an I/O error occurs during the operation
     * @throws IllegalArgumentException if the operation type is unsupported
     */
    public static Object handleFileOperation(String operationType,
                                             List<Path> files,
                                             Path targetDir,
                                             String fileName) throws IOException {
        switch (operationType) {
            case "upload":
                return upload(files, targetDir);
            case "download":
                return download(targetDir, fileName);
            case "zip":
                return zip(files);
            default:
                throw new IllegalArgumentException("Unsupported operation: " + operationType);
        }
    }

    // ---------- Private helper methods ----------

    private static String upload(List<Path> files, Path targetDir) throws IOException {
        Files.createDirectories(targetDir);
        int uploadedCount = 0;
        for (Path file : files) {
            if (Files.exists(file) && Files.isRegularFile(file)) {
                Path destination = targetDir.resolve(file.getFileName());
                Files.copy(file, destination, StandardCopyOption.REPLACE_EXISTING);
                uploadedCount++;
            }
        }
        return uploadedCount + " file" + (uploadedCount == 1 ? "" : "s") + " uploaded";
    }

    private static byte[] download(Path targetDir, String fileName) throws IOException {
        Path fileToRead = targetDir.resolve(fileName);
        return Files.readAllBytes(fileToRead);
