import java.util.ArrayList;
import java.util.List;

public class DivisionUtil {

    /**
     * Performs element‑wise integer division of two lists.
     *
     * @param dividend the list of numerators
     * @param divisor  the list of denominators
     * @return a list containing the integer division results
     * @throws IllegalArgumentException if the lists are null or of different sizes
     * @throws ArithmeticException      if any divisor is zero
     */
    public static List<Integer> elementWiseDivision(List<Integer> dividend, List<Integer> divisor) {
        if (dividend == null || divisor == null) {
            throw new IllegalArgumentException("Input lists cannot be null");
        }
        if (dividend.size() != divisor.size()) {
            throw new IllegalArgumentException("Lists must have the same size");
        }

        List<Integer> result = new ArrayList<>(dividend.size());
        for (int i = 0; i < dividend.size(); i++) {
            int d = divisor.get(i);
            if (d == 0) {
                throw new ArithmeticException("Division by zero at index " + i);
            }
            result.add(dividend.get(i) / d);
        }
        return result;
    }

    // Example usage (optional)
    public static void main(String[] args) {
        List<Integer> nums = List.of(10, 20, 30);
        List<Integer> dens = List.of(2, 5, 3);
        List<Integer> res = elementWiseDivision(nums, dens);
        System.out.println(res); // Output: [5, 4, 10]
    }
}
