import java.util.ArrayList;
import java.util.List;

public class DivisionUtil {

    /**
     * Performs element‑wise integer division of two lists.
     * Handles division by zero, null elements, and cases where the denominator list
     * is shorter than the numerator list.
     *
     * @param dividend the list of numerators
     * @param divisor  the list of denominators
     * @return a list containing the integer division results
     * @throws IllegalArgumentException if either input list is null
     */
    public static List<Integer> elementWiseDivision(List<Integer> dividend, List<Integer> divisor) {
        if (dividend == null || divisor == null) {
            throw new IllegalArgumentException("Input lists cannot be null");
        }

        List<Integer> result = new ArrayList<>(dividend.size());
        for (int i = 0; i < dividend.size(); i++) {
            try {
                Integer numObj = dividend.get(i);
                Integer denObj = divisor.get(i); // may throw ArrayIndexOutOfBoundsException
                int num = numObj; // may throw NullPointerException
                int den = denObj; // may throw NullPointerException
                result.add(num / den); // may throw ArithmeticException
            } catch (ArrayIndexOutOfBoundsException e) {
                System.out.println("ArrayIndexOutOfBoundsException at index " + i);
                result.add(-3);
                return result;
            } catch (NullPointerException e) {
                System.out.println("NullPointerException at index " + i);
                result.add(-2);
            } catch (ArithmeticException e) {
                System.out.println("ArithmeticException at index " + i + ": Division by zero");
