class Workshop {
    private final Stock inputStock;
    private final Stock outputStock;

    public Workshop(Stock inputStock, Stock outputStock) {
        this.inputStock = inputStock;
        this.outputStock = outputStock;
    }

    /**
     * Processes up to {@code count} items.
     *
     * @param count maximum number of items to process
     * @return number of items actually processed
     */
    public int processItems(int count) {
        int processed = 0;
        while (processed < count && inputStock.size() > 0) {
            Item item = inputStock.removeItem();
            outputStock.addItem(item);
            processed++;
        }
        return processed;
    }

    public Stock getInputStock() {
        return inputStock;
    }

    public Stock getOutputStock() {
