/**
 * Factory that sets up workshops according to the specified version.
 */
class Factory {
    private final int version;
    private final Stock inputStock = new Stock();
    private final Stock outputStock = new Stock();
    private final List<Workshop> workshops = new ArrayList<>();
    private final List<Stock> intermediateStocks = new ArrayList<>();

    public Factory(int version) {
        this.version = version;
        setupVersion();
    }

    private void setupVersion() {
        switch (version) {
            case 1:
                // Version 1: Single workshop
                workshops.add(new Workshop(inputStock, outputStock));
                break;
            case 2:
                // Version 2: Two workshops in series
                Stock intermediate1 = new Stock();
                intermediateStocks.add(intermediate1);
                workshops.add(new Workshop(inputStock, intermediate1));
                workshops.add(new Workshop(intermediate1, outputStock));
                break;
            case 3:
                // Version 3: Three workshops in parallel
                Stock out1 = new Stock();
                Stock out2 = new Stock();
                Stock out3 = new Stock();
                workshops.add(new Workshop(inputStock, out1));
                workshops.add(new Workshop(inputStock, out2));
                workshops.add(new Workshop(inputStock, out3));
                // Combine outputs into final output stock after processing
                intermediateStocks.add(out1);
                intermediateStocks.add(out2);
                intermediateStocks.add(out3);
                break;
            case 4:
                // Version 4: Three workshops in series
                Stock inter1 = new Stock();
                Stock inter2 = new Stock();
                intermediateStocks.add(inter1);
                intermediateStocks.add(inter2);
                workshops.add(new Workshop(inputStock, inter1));
                workshops.add(new Workshop(inter1, inter2));
                workshops.add(new Workshop(inter2, outputStock));
                break;
            default:
                throw new IllegalArgumentException("Unsupported factory version: " + version);
        }
    }

    /**
     * Simulates processing of items through the factory.
     *
     * @param totalItemsToProcess maximum number of items to process
     * @return Result containing processed count and remaining input count
     */
    public Result simulate(int totalItemsToProcess) {
        int processed = 0;

        if (version == 3) {
            // Parallel processing: round-robin among workshops
            while (processed < totalItemsToProcess && inputStock.size() > 0) {
                for (Workshop w : workshops) {
                    if (processed == totalItemsToProcess || inputStock.size() == 0) {
                        break;
                    }
                    int p = w.processItems(1);
                    processed += p;
                }
            }
            // Combine all parallel outputs into final output stock
            for (Stock s : intermediateStocks) {
                while (s.size() > 0) {
                    outputStock.addItem(s.removeItem());
                }
            }
        } else {
            // Series or single workshop processing
            for (Workshop w : workshops) {
                if (processed == totalItemsToProcess) {
                    break;
                }
                int p = w.processItems(totalItemsToProcess - processed);
                processed += p;
            }
        }

        return new Result(processed, inputStock.size());
    }

    public Stock getInputStock() {
        return inputStock;
    }

    public Stock getOutputStock() {
        return outputStock;
    }
}

/**
 * Result of a simulation run.
 */
class Result {
    private final int processedCount;
    private final int remainingInputCount;

    public Result(int processedCount, int remainingInputCount) {
        this.processedCount = processedCount;
        this.remainingInputCount = remainingInputCount;
    }

    public int getProcessedCount() {
        return processedCount;
    }

    public int getRemainingInputCount() {
        return remainingInputCount;
    }
}
