/**
 * Basic factory simulation supporting four distinct factory versions.
 * Each version has a specific workshop arrangement.
 * All stock operations are thread‑safe and each workshop runs in its own thread.
 */
public class FactorySimulation {

    public static void main(String[] args) throws InterruptedException {
        // Example usage for all four factory versions
        for (int version = 1; version <= 4; version++) {
            System.out.println("=== Factory Version " + version + " ===");
            Factory factory = new Factory(version);

            // Populate input stock with 10 items
            for (int i = 1; i <= 10; i++) {
                factory.getInputStock().addItem(new Item("Item" + i));
            }

            // Process 7 items
            Result result = factory.simulate(7);

            System.out.println("Processed items: " + result.getProcessedCount());
            System.out.println("Remaining items in input stock: " + result.getRemainingInputCount());
            System.out.println("Final output stock size: " + factory.getOutputStock().size());
            System.out.println();
        }
    }
}

/**
 * Simple representation of an item.
 */
class Item {
    private final String name;

    public Item(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }
}

/**
 * Queue‑based stock container with synchronized operations.
 */
class Stock {
    private final java.util.Queue<Item> items = new java.util.LinkedList<>();

    public synchronized void addItem(Item item) {
        items.offer(item);
        notifyAll();
    }

    public synchronized Item removeItem() {
        return items.poll();
    }

    public synchronized int size() {
        return items.size();
    }
}

/**
 * Runnable workshop that moves items from its input stock to its output stock.
 */
class Workshop implements Runnable {
    private final Stock inputStock;
    private final Stock outputStock;
    private final int totalItemsToProcess;
    private final AtomicInteger processedCount;
    private final boolean isFinalWorkshop;
    private final List<Stock> allStocks;

    public Workshop(Stock inputStock, Stock outputStock, int totalItemsToProcess,
                    AtomicInteger processedCount, boolean isFinalWorkshop, List<Stock> allStocks) {
        this.inputStock = inputStock;
        this.outputStock = outputStock;
        this.totalItemsToProcess = totalItemsToProcess;
        this.processedCount = processedCount;
        this.isFinalWorkshop = isFinalWorkshop;
        this.allStocks = allStocks;
    }

    @Override
    public void run() {
        while (true) {
            // Check if processing limit reached
            if (processedCount.get() >= totalItemsToProcess) {
                notifyAllStocks();
                return;
            }

            Item item = null;
            synchronized (inputStock) {
                while (inputStock.size() == 0) {
                    if (processedCount.get() >= totalItemsToProcess) {
                        notifyAllStocks();
                        return;
                    }
                    try {
                        inputStock.wait();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
                item = inputStock.removeItem();
            }

            // Process item (simply move it)
            synchronized (outputStock) {
                outputStock.addItem(item);
                outputStock.notifyAll();
            }

            if (isFinalWorkshop) {
                processedCount.incrementAndGet();
                notifyAllStocks();
            }
        }
    }

    private void notifyAllStocks() {
        for (Stock s : allStocks) {
            synchronized (s) {
                s.notifyAll();
            }
        }
    }
}

/**
 * Factory that sets up workshops according to the specified version.
 */
class Factory {
    private final int version;
    private final Stock inputStock = new Stock();
    private final Stock outputStock = new Stock();
    private final List<Stock> intermediateStocks = new ArrayList<>();
    private final List<WorkshopInfo> workshopInfos = new ArrayList<>();
    private final List<Stock> allStocks = new ArrayList<>();

    public Factory(int version) {
        this.version = version;
        setupVersion();
    }

    private void setupVersion() {
        allStocks.add(inputStock);
        allStocks.add(outputStock);

        switch (version) {
            case 1:
                // Version 1: Single workshop
                workshopInfos.add(new WorkshopInfo(inputStock, outputStock, true));
                break;
            case 2:
                // Version 2: Two workshops in series
                Stock inter1 = new Stock();
                intermediateStocks.add(inter1);
                allStocks.add(inter1);
                workshopInfos.add(new WorkshopInfo(inputStock, inter1, false));
                workshopInfos.add(new WorkshopInfo(inter1, outputStock, true));
                break;
            case 3:
                // Version 3: Three workshops in parallel
                workshopInfos.add(new WorkshopInfo(inputStock, outputStock, true));
                workshopInfos.add(new WorkshopInfo(inputStock, outputStock, true));
                workshopInfos.add(new WorkshopInfo(inputStock, outputStock, true));
                break;
            case 4:
                // Version 4: Three workshops in series
                Stock interA = new Stock();
                Stock interB = new Stock();
                intermediateStocks.add(interA);
                intermediateStocks.add(interB);
                allStocks.add(interA);
                allStocks.add(interB);
                workshopInfos.add(new WorkshopInfo(inputStock, interA, false));
                workshopInfos.add(new WorkshopInfo(interA, interB, false));
                workshopInfos.add(new WorkshopInfo(interB, outputStock, true));
                break;
            default:
                throw new IllegalArgumentException("Unsupported factory version: " + version);
        }
    }

    /**
     * Simulates processing of items through the factory.
     *
     * @param totalItemsToProcess maximum number of items to process
     * @return Result containing processed count and remaining input count
     */
    public Result simulate(int totalItemsToProcess) throws InterruptedException {
        AtomicInteger processedCount = new AtomicInteger(0);
        List<Thread> threads = new ArrayList<>();

        for (WorkshopInfo info : workshopInfos) {
            Workshop workshop = new Workshop(info.inputStock, info.outputStock,
                    totalItemsToProcess, processedCount, info.isFinalWorkshop, allStocks);
            Thread t = new Thread(workshop);
            t.start();
            threads.add(t);
        }

        // Wait for all workshop threads to finish
        for (Thread t : threads) {
            t.join();
        }

        return new Result(processedCount.get(), inputStock.size());
    }

    public Stock getInputStock() {
        return inputStock;
    }

    public Stock getOutputStock() {
        return outputStock;
    }

    private static class WorkshopInfo {
        final Stock inputStock;
        final Stock outputStock;
        final boolean isFinalWorkshop;

        WorkshopInfo(Stock inputStock, Stock outputStock, boolean isFinalWorkshop) {
            this.inputStock = inputStock;
            this.outputStock = outputStock;
            this.isFinalWorkshop = isFinalWorkshop;
        }
    }
}

/**
 * Result of a simulation run.
 */
class Result {
    private final int processedCount;
    private final int remainingInputCount;

    public Result(int processedCount, int remainingInputCount) {
        this.processedCount = processedCount;
        this.remainingInputCount = remainingInputCount;
    }

    public int getProcessedCount() {
        return processedCount;
    }

    public int getRemainingInputCount() {
        return remainingInputCount;
    }
}

