        this.version = version;
    }

    /**
     * Runs the simulation for the specified number of items.
     *
     * @param totalItemsToProcess maximum number of items to process
     * @return FactoryPerformance containing all simulation metrics
     * @throws InterruptedException if thread execution is interrupted
     */
    public FactoryPerformance runSimulation(int totalItemsToProcess) throws InterruptedException {
        Factory factory = new Factory(version);

        // Populate input stock with 10 items for demonstration
        for (int i = 1; i <= 10; i++) {
            factory.getInputStock().addItem(new Item("Item" + i));
        }

        long startTime = System.nanoTime();
        Result result = factory.simulate(totalItemsToProcess);
        long endTime = System.nanoTime();

        long executionTimeMs = (endTime - startTime) / 1_000_000;

        List<Integer> intermediateSizes = new ArrayList<>();
        for (Stock s : factory.getIntermediateStocks()) {
            intermediateSizes.add(s.size());
        }

        return new FactoryPerformance(
                executionTimeMs,
                result.getProcessedCount(),
                factory.getErrorCount(),
                factory.getInputStock().size(),
                intermediateSizes,
                factory.getOutputStock().size()
        );
    }
