class Factory {
    private final int version;
    private final Stock inputStock = new Stock();
    private final Stock outputStock = new Stock();
    private final List<Stock> intermediateStocks = new ArrayList<>();
    private final List<WorkshopInfo> workshopInfos = new ArrayList<>();
    private final List<Stock> allStocks = new ArrayList<>();
    private final AtomicInteger errorCount = new AtomicInteger(0);

    public Factory(int version) {
        this.version = version;
        setupVersion();
    }

    private void setupVersion() {
        allStocks.add(inputStock);
        allStocks.add(outputStock);

        switch (version) {
            case 1:
                // Version 1: Single workshop
                workshopInfos.add(new WorkshopInfo(inputStock, outputStock, true));
                break;
            case 2:
                // Version 2: Two workshops in series
                Stock inter1 = new Stock();
                intermediateStocks.add(inter1);
                allStocks.add(inter1);
                workshopInfos.add(new WorkshopInfo(inputStock, inter1, false));
                workshopInfos.add(new WorkshopInfo(inter1, outputStock, true));
                break;
            case 3:
                // Version 3: Three workshops in parallel
                workshopInfos.add(new WorkshopInfo(inputStock, outputStock, true));
                workshopInfos.add(new WorkshopInfo(inputStock, outputStock, true));
                workshopInfos.add(new WorkshopInfo(inputStock, outputStock, true));
                break;
            case 4:
                // Version 4: Three workshops in series
                Stock interA = new Stock();
                Stock interB = new Stock();
                intermediateStocks.add(interA);
                intermediateStocks.add(interB);
                allStocks.add(interA);
                allStocks.add(interB);
                workshopInfos.add(new WorkshopInfo(inputStock, interA, false));
                workshopInfos.add(new WorkshopInfo(interA, interB, false));
                workshopInfos.add(new WorkshopInfo(interB, outputStock, true));
                break;
            default:
