public class LinkedListSwapper {

    /**
     * Swaps the first two nodes of a singly linked list.
     * Assumes the list has at least two nodes.
     *
     * @param head the original head of the list
     * @return the new head after swapping
     */
    public static LinkedListNode swapNodes(LinkedListNode head) {
        if (head == null || head.next == null) {
            return head; // no swap needed
        }
        LinkedListNode second = head.next;
        head.next = second.next; // detach second from first
        second.next = head;      // point second to first
        return second;           // new head
    }

    /**
     * Creates a singly linked list from a list of integers.
     *
     * @param values the list of integer values
     * @return the head of the created linked list
     */
    public static LinkedListNode createLinkedList(java.util.List<Integer> values) {
        if (values.isEmpty()) {
            return null;
        }
        LinkedListNode dummy = new LinkedListNode(0);
        LinkedListNode current = dummy;
        for (int val : values) {
            current.next = new LinkedListNode(val);
            current = current.next;
        }
        return dummy.next;
    }

    /**
     * Converts a singly linked list back into a list of integers.
     *
     * @param head the head of the linked list
     * @return a list containing the node values in order
     */
    public static java.util.List<Integer> linkedListToList(LinkedListNode head) {
        java.util.List<Integer> result = new java.util.ArrayList<>();
        while (head != null) {
            result.add(head.data);
            head = head.next;
        }
        return result;
    }
}

