public class LinkedListSwapper {

    /**
     * Swaps the nodes at positions i and j (0‑based) in the list.
     * The method adjusts pointers only; data values are not swapped.
     *
     * @param head the head of the list
     * @param i    the first index (0‑based)
     * @param j    the second index (0‑based)
     * @return the new head of the list after swapping
     */
    public static LinkedListNode swapNodes(LinkedListNode head, int i, int j) {
        if (head == null || i == j) {
            return head; // nothing to do
        }

        // Ensure i < j for easier handling
        if (i > j) {
            int tmp = i;
            i = j;
            j = tmp;
        }

        // Dummy node simplifies handling of head changes
        LinkedListNode dummy = new LinkedListNode(0);
        dummy.next = head;

        // Find predecessor and current node for position i
        LinkedListNode prevX = dummy;
        LinkedListNode currX = dummy.next;
        for (int idx = 0; idx < i; idx++) {
            prevX = currX;
            currX = currX.next;
        }

        // Find predecessor and current node for position j
        LinkedListNode prevY = dummy;
        LinkedListNode currY = dummy.next;
        for (int idx = 0; idx < j; idx++) {
            prevY = currY;
            currY = currY.next;
        }

        // If nodes are adjacent (currX.next == currY)
        if (currX.next == currY) {
            // prevX -> currX -> currY
            prevX.next = currY;
            currX.next = currY.next;
            currY.next = currX;
        } else {
            // Non‑adjacent nodes
